/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250415-5","meetingId":"r07-cm04","date":"2025年4月15日","dateIso":"2025-04-15","committee":"総務委員会","time":"午後 １時００分～午後 ４時０８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件整理しています。","topics":[{"id":"topic-01","title":"幹部職員の異動","agenda":"幹部職員の異動","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今回、雨水排水能力の増強ということですが、下水管が太くなるということなのですか。排水能力を増強するとありますが、これは太さを変えることなのでしょうか、説明するよう求めました。","respondent":"佐藤経理課長","answer":"排水能力の増強についてですけれども、委員ご指摘のとおり、古い下水管の入替えの際に径を太くするということで、例えば２５ｃｍのものを３５ｃｍに入れ替えるとか、そういったことで排水能力を増強すると聞いております。","id":"exchange-001"}]},{"id":"topic-02","title":"品川区総合実施計画の改定","agenda":"品川区総合実施計画の改定","exchanges":[{"speaker":"西本委員","kind":"質問","question":"それで、左側の短いほうをとじて、こう見る感じなのですか。ごめんなさい、非常に慣れなくて、だから、普通このぐらいの大きさだとすればこうではないですか、それでこうではないか尋ねました。","respondent":"崎村企画課長","answer":"今回、Ａ４横判で製本させていただいておりまして、今、委員お話しのように、横判の左側をとじて右からめくっていただくような形になります。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"この目標値というのは、今後どうするのですか。３つの重点項目というのがあって、というところがあって、品川区全体としてどういう方向に持っていくのですかというのがなかなか見えないのです。","respondent":"崎村企画課長","answer":"令和５年度に行った区民アンケートですとか昨年度の世論調査でも、この辺の幸福度、この実施計画の大きな特徴かなと考えているところです。あくまで実施計画については、各課の事業がＳＤＧｓの１７のゴール、こちらはご理解いただければと思います。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"本当でしょうかというところがあって、実際どういうところからの根拠を持ち出すのか、これは。どうなっていくかというのを多分見やすくしておかないと、そういう財政的なシミュレーション、そういうものを手がけるというのはあるのか尋ねました。","respondent":"崎村企画課長","answer":"この数値に基づいて事業を実施していくということを必ずしも考えているわけではなくて、こういった指標を活用していくところです。総合実施計画ということで、また、もう少し長いスパンで考えていかなければいけないと企画経営部としても考えております。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"これ、毎年見直しを図っていくのでしょうか。５年間ですけれど、１年やってみて来年度どうなったか、それだけ説明するよう求めました。","respondent":"崎村企画課長","answer":"まずはこの総合実施計画というものを毎年度改定していくかというと、そこについては検討が必要かなと思いますけれども、必ずその実施計画事業については。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"２０２５年度が４９０億円余ですか、２０２７年度が６７０億円余ということですが、こんなものでは足りないのです。先ほどの質問に対して答えるよう求めました。","respondent":"崎村企画課長、加島財政課長","answer":"年代ですとか性別、そういったところの少し細かい部分を分析しながら、区としての取組について検討していくところかと考えているところです。インフレスライドの発生に途中で対応できるよう、今現在、一般財源については利払いのみという形にしております。対応できるように財源を考えていくとともに、５億円が学校改築という形で先々積立てを行いまして、そのような考えです。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"私の質問が悪かったのか、区有施設に対しても、相当な金額がやはりかかってくる。投資的経費もおのずと２倍近く跳ね上がって、ここに計上するべきではなかったのかなと少し思ったもので、それで質問をさせていただいたところです。","respondent":"加島財政課長","answer":"今回の予算編成におきましても、起工時につきましてインフレスライドを見込んだ予算編成というのを行っております。インフレスライド、じかにということではないですけれども、財源の確保には努めてまいりたいと思います。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"なぜなら、起債したりとかといって、その償還はどうなっていくのかというのが全然見えないのです。それらの全体の返済というのはどうなっているのかというのを、少しまとめてもらうことはできないのか尋ねました。","respondent":"加島財政課長","answer":"償還計画につきましては、予算特別委員会資料の中で、これまで借り入れた分、定期償還、満期一括償還も含めて、そのときの元金払い、利払いというのを表示していますので、こちらが計画になります。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"どこの部分がどういう返済になっているかというのが、予算書の中のものは全体が入っているので、それぞれのものがよく見えないのです。","respondent":"加島財政課長","answer":"議会にお示しする資料といたしましては、全体の償還計画を今、提出させていただいているところです。個別につきましては財政課で管理をしておりますので、今現在、議会に提出する予定はございません。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"それが出せる状況まで、概要でもいいのですけれど難しいのでしょうか。それ全体の借入れ、それから返済とかというシミュレーション的なものというのは、お示しは難しいか尋ねました。","respondent":"加島財政課長","answer":"今現在は、先ほど申し上げたとおり償還計画の中でお示しすることを考えております。こちらのほうにつきましては、今、財政課で管理するという方向性でやっております。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"では要望だけ言っておきます。これは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-03","title":"中高生リバースメンターの募集","agenda":"中高生リバースメンターの募集","exchanges":[{"speaker":"松本委員","kind":"質問","question":"たかまつななさんの笑下村塾というところがやっているというのを見るのですけれど、今回はそうした、どこかに委託するということなのか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"本件は、中高生の検討会４回のファシリテートですとか、専門的な知見を持つ事業者に事業の支援を委託する予定です。委員からご紹介がございました、株式会社笑下村塾に、品川区もプロポーザル方式による事業者選定において委託をすることにしております。","id":"exchange-012"},{"speaker":"松本委員","kind":"提案","question":"本来は、より現場に近い方に対して提案をしていくというのが、事業化をしていく上では大事なのではないかと思っています。ここでお伺いしたいのが、所管されている部署の職員の方たちとどのくらい接点を持つ機会があるのかというところをお伺いできたらと思いますとの意見を述べました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"検討を進めていきたいというところではありますが、検討会４回の中で、１つ考えているところです。若手を中心とした職員にサポーターとして検討会の途中から、大きく２点、各部署と中高生との接点として考えているところです。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"自ら見いだすという方向には、このシステムだとならないのではないかと私は思いますので、そこをどう思ってやられるのですか。品川区に、行政などに意見が言えるような道筋をつくってあげるほうが現実的ではないのかなと思うのですけれど、いかがか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"なぜこの事業を実施するのか、こちらは教育委員会、学校で実施している探究学習とはもちろん親和性は高いのですけれども。国から出ているようなガイドラインにも沿って、子どもたちの自発性を尊重するような対応、体制を取ってまいりたいと考えているところです。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"だからもっと広い意味で、教育委員会の中でどういう学習をしているのかということも調べてやってほしいなと思います。これは意見なので、別に答弁は求めませんので結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須貝委員","kind":"意見","question":"という一つのそういう目標があって、その子たちに何か役立てば、それはそれでいいのではないかと私は思います。意見だけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"あまり軽んじるべきではないかなと私は思っておりまして、区をよりよくするためにいいアイデアが出るということは十分あり得ると考えています。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"それから若者の考え方などについてアドバイスをしたりといったところで、資生堂が２０１７年からかなりの長い間、実施していることが有名です。","id":"exchange-017"},{"speaker":"松本委員","kind":"意見","question":"そういう意味では、品川区としてより区政に反映できるような形でのやり方というのを考えていただければなと思います。以上、意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"新妻副委員長","kind":"質問","question":"１０名の区民、この１０人の人選に当たっての、この１０人を選ぶところもこの委託の事業者がやるということでしょうか。そこをお聞きしたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"リバースメンター、中高生１０名の選定主体についてのご質問ですが、リバースメンターの募集、それから選定については委託事業者ではなく、区が実施する予定です。","id":"exchange-019"},{"speaker":"新妻副委員長","kind":"提案","question":"ここに提案のテーマとして２つ掲げられておりますが、どういうふうに、どういうふうに人選をしていくのかと。この１０名の作文を、区の職員のどなたが見ていただいてどういう基準でそこを選んでいくのかというところを少しお聞きしたいと思いますとの意見を述べました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"作文の審査については区の企画経営部の管理職を中心として実施する予定ですが、１次審査、２次審査のあたりは今後検討したいと考えているところです。","id":"exchange-020"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"一歩突っ込んで言ってくれるような、そういう作文を書いてくださった方の意見もぜひ取り入れていただきたいなということを要望させていただいて、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"しっかりやっていただきたいのと、１０人いて、教える内容というのは国の研修内容というものがあるのですか。要は教えるにも教え方が多分あるのでしょうから、どんなものなのかなというのを教えていただきたいのと、そこら辺何かあれば説明するよう求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"子どもたちの多様な考えを受け止めるような進め方といったものが、区の職員には研修、事前説明を行っていきたいと思います。２点目として、１０人の中高生リバースメンターに対して何人ぐらいの職員をですが、各部署の体制なども含めて今後検討してまいりたいと考えています。","id":"exchange-022"},{"speaker":"まつざわ委員","kind":"質問","question":"でもやはりなかなか人を増やすのも大変でしょうから、それでもこの事業は成功させてほしい、職員のケアも含めて検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"大倉委員","kind":"確認","question":"結構、予算プレスを見ると９月から事業化が検討されると、ここに合わせてやっているのだろうなというところでいいのかということの確認。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"所管課と一緒に事業化に向けて検討を進めるといったところを据えておりますので、全４回の検討会というのはかなりタイトになってきております。この検討会は全体で進めるものですが、政策をより検討していたり、支援しながら進めてまいりたいと考えているところです。","id":"exchange-024"}]},{"id":"topic-04","title":"コンプライアンス推進のための取組み","agenda":"コンプライアンス推進のための取組み","exchanges":[{"speaker":"西本委員","kind":"意見","question":"みんなその勉強をしていくのは当然なのですけれど、その辺の受け止め方というのは、どういう訓練をしていかれますか。なぜそういう、どうあるべきだったのかという、これをつくるに当たって検討はされていますかとの意見を述べました。","respondent":"川村コンプライアンス推進担当課長","answer":"策定に当たりましては、職員１人が抱え込まずに組織的に判断し対応をするために、こちらのカスタマー・ハラスメント対応要領を策定いたしました。","id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"パワハラとかセクハラとか、もう今問題になっていることに関しては、どういうふうに対応していくのか。こういうことを言っていいのだとか、そういうことも含めて、どういうふうな取組をされますかとの意見を述べました。","respondent":"川村コンプライアンス推進担当課長","answer":"組織のトップのほうからの意識改革も含めまして、職層に応じた研修を行っていけるように検討してまいります。こちら、それぞれハラスメントに関する窓口を設置しておりますので、そういったものをもっと職員に周知していけるように努めてまいりたいと思います。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"職場関係というものになっていただきたいと、なっているとは思いますが、ぜひそれを実現してほしいなと思います。こういうところでも私、カスハラと言われてしまうのかなとすごく心配になってしまうのですけれど、それはいかがか尋ねました。","respondent":"川村コンプライアンス推進担当課長","answer":"最後のご質問に関しましてですが、議員の方も区の職員も、区政のよりよい実現に向かって建設的な議論を交わしていると捉えておりますので、そこはカスタマー・ハラスメントではないと考えています。","id":"exchange-027"},{"speaker":"松本委員","kind":"質問","question":"いざ録音をするというときに、録音機、ボイスレコーダーがどのぐらい配置されているのかというのが多分問題になるのかなと思います。ここは窓口におけるボイスレコーダー、録音機の対応というのはどのようになる予定なのか、お伺いできればと思います。","respondent":"川村コンプライアンス推進担当課長","answer":"窓口対応などのレコーダーの配置についてですが、現時点で、カスタマー・ハラスメント対応としてレコーダーの配置の予定はございません。","id":"exchange-028"},{"speaker":"松本委員","kind":"質問・要望","question":"何か起こってからというよりも、庁内のほうで検討していただいて、置くべきところには置いていただきたいなというところを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいのは、部課長級で判断されるのか、それとも別の決まった方が判断されるのか教えてください。その後に第三者機関が入る余地があるのか、それともそういうものは一切入れないのかという、その２点だけ説明するよう求めました。","respondent":"川村コンプライアンス推進担当課長","answer":"まず、そういった形で組織内の中立的な立場で判断してもらうのを進めていく取組をまず、進めてまいりたいと考えています。いざ、もっと大きな問題に直面したときの第三者委員会などの設置につきましては、今後の検討課題かなと思います。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"そういうやはり、きちんとした客観的に見える状況ではなくなってしまうのではないかなと思うのですが、その辺についてはどのようにお考えか尋ねました。","respondent":"川村コンプライアンス推進担当課長、柏原区長室長","answer":"ご心配の趣旨は理解できますけれども、大変職務意識の高い推進指導員に携わっていただいておりますので、その辺りはご心配ないように……。これは区の中だけの部分では、それはもう第三者的な機関を場合によっては設置して、判断をもらったりなどというものが出てくるのだろうと。そういったところでは、常に判断をしながらというところにはなってこようかと思います。","id":"exchange-031"},{"speaker":"須貝委員","kind":"意見","question":"恐らくフジテレビでも皆さんそういうふうにやっていたと思うのですけれど、ただ実際、いざとなると、どうしても内部で収めてしまう。民間企業では第三者機関に通報または相談というのが今、普通の仕組みになっているようなので、それだけ少し意見として言わせていただきますとの意見を述べました。","respondent":"柏原区長室長","answer":"そういった意味では、内部だけでの判断というよりは、そういった制度も使いながらというところはあります。そういったものを持ちながら、足りない部分があれば、もっと改善できるように検討しながらということになろうかと思います。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"別枠でそういう逃げ込むところ、頼れるところというものをつくっておいたほうがいいのではないかなと思いますけれど、今あるのですか。品川区はそういう職員の駆け込み寺みたいなものはありますか。","respondent":"川村コンプライアンス推進担当課長","answer":"公益通報に関しましては、外部の窓口を設置しておりまして、そちらに通報していただくことができる体制を取っております。そして、調査委員会などについてはやはり、先ほどの重複になりますけれども、事案に応じた判断が生じる場合もあるのかなとは考えております。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問・要望","question":"精神的に病んでしまったりしてしまうので、そうならないように救済措置はきちんとあるということは、職員の方々に知ってほしい。お一人お一人の職員の方に認識していただくというものが必要かなと私は思っているので、ぜひ、よろしくお願いしたいと思います。","respondent":"柏原区長室長","answer":"外部にも相談窓口を今、置いておりますので、内部で言いづらい部分はそこに言っていただくという体制は取っております。職員も言いやすい環境であったりとか状況というものをきちんとつくっていくというのが我々の役目だろうと思っていますので、その辺は努力します。","id":"exchange-034"},{"speaker":"まつざわ委員","kind":"質問","question":"例えば、一部の方が職員を１時間質疑で拘束してしまう。カスハラになるのですか、そういったコンプライアンス推進の先にどう広げていくのかなという、まずビジョンがあるのかなというのを説明するよう求めました。","respondent":"川村コンプライアンス推進担当課長","answer":"お互いコンプライアンス意識を高めていく中で、そういったハラスメントを防いでいければと考えています。対応要領、一概に区民の方とは申しませんけれども、そこはお互いのコンプライアンス意識の醸成が必要かと考えています。","id":"exchange-035"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ちくりという表現がいいのかな、内部告発というのですか、例えばそういうのはなかなか言えない部分が強いと思っているのです。相談しづらいというのがあるかなと思うので、やはりそういった機関というものはこの先、いろいろ検討していただけたらなという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-05","title":"「デジタルプラットフォーム」を活用した区民意見募集の結果","agenda":"「デジタルプラットフォーム」を活用した区民意見募集の結果","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これ、今後いろいろなテーマで、このデジタルプラットフォームで意見を聞くよという理解でいいでしょうか。当然ながら、今回は防災訓練で防災課とのフィードバックという形になると思いますけれど、これ、テーマはどういうふうにして決めるのか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"今回は防災訓練で実施をしましたけれども、今後は区政の様々な課題について、こういった意見を聞いていくような使い方をしていこうと考えています。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"公開基準に合わないコメント１３件、これ、どんな類いのものなのですか。今回１３件で、具体的な内容はいいのですが、その決まりというか基準というものを説明するよう求めました。","respondent":"與那嶺戦略広報課長","answer":"試行実施という形で、先ほどご説明申し上げたように、そういったものがあれば当然そこはフィルターをかけていく形になります。企業からのコメントで、そういったところはさすがに案件としてはそぐわないかなというところで、フィルターをかけさせていただいたです。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"２番のところで、採用しないというのは、その部署の中での検討という感覚でよろしいのですか。ここは、その結果を部署に渡して、あとはそれを使うかどうかというのはその部署が考えるという使い方になるのか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"原課になる部署のところで検討、このような観点から検討できるものがないですか、そこの中で確認をしていくというような考え方です。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"こういう企画をすればいいのではないのですかという話なのですが、これからどうするというより、私は評価できるのではないかと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"新妻副委員長","kind":"質問","question":"デジタルプラットフォームであったから意見があったのかという、そこら辺の分析をどうされているのかというところをお聞きしたいのが１点。","respondent":"與那嶺戦略広報課長","answer":"今回実施に当たった事業者と、約３３日間の期間で１１７件というところは、多かったというように評価したところです。必要なものにつながるとは限らないので、そこは少しバランスを見ながら検討していかなければならないのかなとは思っております。","id":"exchange-041"},{"speaker":"新妻副委員長","kind":"意見","question":"そもそもデジタルプラットフォームを活用した区民意見の募集というのが、今回１１７件集まりましたが、まだ知られていない。今年度も行われるに当たっては、そこら辺もまた取組をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"大倉委員","kind":"質問","question":"できているのですかというのが、何かの移動時間など、ちょっとした隙間時間に答えているということもあるのかなと。なかなか中学生１人、大学生２人というところではアクセスしたけれど、何かその辺の分析などはあるのか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"１０日ぐらいたってからまたＸで周知をしたりとか、その投稿が行われるごとに、徐々にコメント数が伸びてきたというところは実績としてはあるのです。６０代以上の方からも投稿いただいて、まず、そちらのほうに力を入れていきたいと考えております。","id":"exchange-043"},{"speaker":"大倉委員","kind":"確認","question":"ぜひいろいろな、いろいろなところで周知していただいて広まって、これだけ回答があったということでは非常にすばらしいなと思っているところです。一点、今取っていないということは、取れるけれど取っていないのかというところの確認だけさせていただければ。","respondent":"與那嶺戦略広報課長","answer":"今回の実施に当たっての事業者との話の中でも、取れるか取れないかということから我々のほうで認識をしていないという形になります。","id":"exchange-044"},{"speaker":"大倉委員","kind":"確認","question":"確認していただいて、確認して、ぜひそういうことも分析に入れていただければいいかなと思いましたのでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]},{"id":"topic-06","title":"都市ブランドデザイン","agenda":"都市ブランドデザイン","exchanges":[{"speaker":"西本委員","kind":"質問","question":"さきにいろいろご説明いただいた経緯があるのですけれども、改めて質問を幾つかしたいのですが、なぜゆえに、株式会社ヘラルボニーなのでしょうか、ということと、周知の方法を、区民の方への周知はどうされるのかを説明するよう求めました。","respondent":"與那嶺戦略広報課長","answer":"デザイナーとか、コピーライターとか、そういった方を様々な観点から検討してきた経緯があります。そのほかに、そういった動きを取らせていただいて、多くの方に知っていただけるような取組を行っていきたいと考えております。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"品川区と何かしら関係があったからとか、という、その辺はどうでしょうかということと、これ、使い方はいろいろ出てくると思うのです。このロゴはフィックスという形で、そういう細かい話もあるのかなと思うのですけれど、それはどのように説明していくのか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"そちらについてはプロポーザルで選定し契約を行いました。いざこういった形で決めてしっかりと表に出したというところについては、しっかりと自信を持ってお示しできるデザインになったと考えています。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"その多彩区というのが、なぜ多彩なのというところ、そこの説明を先にしたほうが分かりやすいのかなと。でもやはり、なるべく税金を使わないような方法を考えていただきたいなと思いますが、その辺はどのような工夫をされますか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"ブランディングについて３面ぶち抜きのような形で特集記事を予定しておりまして、そういったところを説明できるような形でまず出していきます。","id":"exchange-048"},{"speaker":"新妻副委員長","kind":"確認","question":"そういう場があるのかというところを１点確認と、これは、このヘラルボニーがやっていくということでしたでしょうか。ヘラルボニーの品川のこのアートがモチーフになっていたと伺っていますけれども、グッズについてもお聞きしたいと思います。","respondent":"與那嶺戦略広報課長","answer":"今回つくったアートを区民の皆さんに見ていただいて、親しんでいただく、これが非常に大事なことかなと考えています。例えば地域の方であるとか企業の方と連携をしていく中で、そういったこともできたらいいなと、そのように考えてあります。","id":"exchange-049"}]},{"id":"topic-07","title":"債権の放棄","agenda":"債権の放棄","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これ、発生日というのと、何年間返済がなかったら、それを債権放棄というふうに、これは年数で決められるのですか。その仕組みをもう少し教えてほしいのですけれど。","respondent":"品川会計管理者","answer":"２番のケースに関しましては、返済開始から１０年間を基準として、時効ということを判断しております。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"そうすると、２番のケースのようなものは、１０年間たてば返さなくていいという仕組みになっているのですか。１番目のほうは、このぐらい待ったけれど無理ですというのは、何年ぐらいで判断することになるのか尋ねました。","respondent":"品川会計管理者","answer":"このケースについては１０年というところなのですが、しないとか、そういったもろもろのケースがあります。こういった個別の判断のところを、品川区の債権管理審議会において審議をした結果として、債権を放棄するという判断をしたという結果です。","id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"こういう措置があるということは理解はできるのですが、令和７年度では給付型の奨学金など、品川区はやっていくではないですか。全部が全部対象には難しいかもしれないですけれど、入れるということは可能なのではないかなと思うのですが、その辺いかがか尋ねました。","respondent":"品川会計管理者","answer":"奨学金については平成３０年の制度改正によって、これより先についてはあまりこういうケースが出てこないのですが、それより前の制度というような形で今回のケースが出てきているです。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"ですからやはり平成３０年の前の人たちに対して、とても大変だというのであれば、そこもカバーするということがあってもいいのかなと思います。検討していただく可能性はありますか尋ねました。","respondent":"品川会計管理者","answer":"個別のケースによっていろいろあると思いますので、まずはこういう制度にのっとった形で、そういう状況もいろいろ勘案して判断するところが、審議会という場所がありますので、こういったところで時効の判断、放棄の判断などといったものをしていくという考えです。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜなら、やはり救済措置というのはある程度考えられないことではないのかなと思いますので、そこは検討材料の中に入れてほしいなと思います。ある方向では必要なのかなと思いますので、ぜひ検討の俎上に上げていただきたいと、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"}]},{"id":"topic-08","title":"公職選挙法の一部を改正する法律","agenda":"公職選挙法の一部を改正する法律","exchanges":[{"speaker":"西本委員","kind":"確認","question":"それがあるということなのですか。なので、一つは、どんなものが駄目で、それを確認するのは、事前の提出、もちろんいろいろあると思うのですが、そこで確認するのか尋ねました。","respondent":"今井選挙管理委員会事務局長","answer":"それにつきましては、ガイドラインについては特につくる予定というのは、国会の答弁ではございませんでした。ですので、ポスターについては事前審査がございませんので、あとは候補者の自覚、そして有権者の判断に委ねられるものです。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"でも、そのほかに規制というのは何か、今の時点であるのかどうかというのを教えてほしいと思います。幅４０ｃｍ以内というのは、これは令和８年度からになりますが、区議選もこの大きさになるという理解でよろしいか尋ねました。","respondent":"今井選挙管理委員会事務局長","answer":"審議されておりますので、そのような形で、今検討されているという認識があります。それから２番目ですけれども、長さ４２ｃｍから幅４０ｃｍ以内という形になりますので、この大きさの範囲内となるものです。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/121362?Template=document&Id=7027#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":56588,"voices":178}},{"id":"r07-20250416-14","meetingId":"r07-cm04","date":"2025年4月16日","dateIso":"2025-04-16","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時５７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"総括質疑の中でも確認をしたのですが、もう少し詳しくご説明いただきたいというところが幾つかあるので、確認をしていきます。そもそもＢＴＯ方式ありきだったのですかということがこれから問われる可能性があるので、もう一度丁寧にご説明ほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"１つＤＢＯ方式のほうが優れているというところもありますが、いわゆる財政の平準化ができる、こういったメリットがある。こういった部分のところから、こちらの記載をさせていただいているとおり、ＢＴＯ方式の採用を検討したというところで進めているです。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"これは広町の跡地の活用の中でも、当初はそれは教えていただけなかったのですが、たしか途中で何か教えていただいたのでしたか。どれぐらいの数の事業者が関心を示しているのか、もし教えていただける範囲があるならば、説明するよう求めました。","respondent":"吉岡政策推進担当課長","answer":"昨年の秋口にサウンディング調査を実施いたしまして、あるいは運営をしていく事業者に対して、１０社程度サウンディング調査を行ったです。こちらの１０社程度のところを数十社に、それも複数回、何度も何度も行わせていただくというように考えているところです。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"７社ぐらいが構成されているＳＰＣでしたが、ちょっと細かいことですけれども、説明するよう求めました。","respondent":"吉岡政策推進担当課長","answer":"代表になるかならないかということは今後のというところではありますけれども、代表になり得る事業者に対しては半数程度以上に聞いているです。そういった部分については、また別途、今回のサウンディング調査で聞かせていただいたです。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"提案","question":"そういったよりよい提案をいただいていく中で反映するのだという、そのようなご答弁だったと思うのです。そこについてはできるだけたくさんの企業からできるだけたくさんの提案をいただいて、そこについてもう一度ご答弁お願いしますとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"庁内連携、庁内検討がより具体化、深度化をしてまいります。よりよい提案が出てくるというところが期待される部分はありますので、このサウンディング調査をしっかりとやっていきたいと考えています。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それと２つ、あと２点だけ質問します。これはお願いしたいと思うのですけれども、そこについてご見解を、お願いいたします。","respondent":"吉岡政策推進担当課長","answer":"やはり全国の自治体の、こういった図書館を中心とした複合施設を拝見いたしますと、そういった部分があります。財源もありますので、どこに注力するかというところは、今後引き続きしっかりと検討していきたいと考えています。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"提案","question":"やはり施設の中の１つスペースをしっかりつくった上で、もしくはワークスペースというものが、結構今はもう全国的には当たり前になってきていますとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"いわゆる社会人の方にも非常に幅広く使っていただいている、学生の方にも使っていただいているというところは十分認識をしています。仕事ができるというスペースは重要だと考えていますので、今後のサウンディング調査を進めながら、しっかり検討していきたいと考えております。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"この住民説明会が３月に行われたということで、そこでどのような意見、あるいは質疑があったのか、それに区はどう答えたのか伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"住民説明会のほうで３月２４日に行わせていただいたというところでの質問の件ですけれども、まず、大きく防災に関する質問ございました。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"有機的にもつながっていくというのですか、運営の部分、それを含めて区民に愛される施設になるように力を尽くしてほしいと求めました。もし何かご答弁あれば、伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"庁内の連携というのはもとよりですけれども、あるいは区と話合いを進めながら契約を結ぶ、引き続き検討を深めていきたいと考えております。","id":"exchange-008"},{"speaker":"山本委員","kind":"質問・要望","question":"４ｍなど取る必要があるというものが実態でございまして、そういった、より大会利用できるような形にしてほしいというようなお話がございました。","respondent":"吉岡政策推進担当課長","answer":"当然ながら、そういったスポーツの全体をどういったスポーツをやっていただけるか、なるべく制限もかけないようにというところで検討しています。","id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"図書館や、そのような幅の中でミニマムに収まってしまうという懸念というものがあるのですが、その辺りいかがでしょうか。仕様をどこまで区で決めて公募するようなお考えなのかということと、それ以外の全般的な今のお考えのところについて、２点お伺いいたします。","respondent":"吉岡政策推進担当課長","answer":"もう実際できるようなゾーニングといいますか、施設のプランというものはもうほぼ固まってきてしまうというようなところもあります。ここは自由提案にしてほしいですとか、区としてはここは絶対譲れないとか、今どこまでということはなかなか申し上げられないのかなです。","id":"exchange-010"},{"speaker":"山本委員","kind":"質問・要望","question":"使い勝手も含めて、利用者の方々が想定される使い方など関係者の方々に聞いていただいて、それをこの施設に盛り込めるように進めていただきたいです。やはり事業者に全て任せるということではなくて、その声をできるだけ聴いて反映できるような進め方を要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"筒井委員","kind":"意見","question":"最後に。ちょっと１点だけ、４９ページの公共と民間事業者の役割のところで、その辺りのことを説明するよう求めました。","respondent":"吉岡政策推進担当課長","answer":"今年度実施方針、あるいは要求水準書を策定する中で、民間事業者にお願いしたい業務というものを確定するところです。その中で解体業務が加わるか、加わらないかというところが確定をいたしますので、そういった意味では今年度中です。","id":"exchange-012"}]},{"id":"topic-02","title":"新庁舎整備に向けた実施設計概要等の説明","agenda":"新庁舎整備に向けた実施設計概要等の説明","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"現段階では、そういった、今までの、いわゆる区の一定程度の規模の施設の形での発注と同じような形で、今出されているということで伺いました。","respondent":"小林新庁舎建設担当課長","answer":"それをしっかり反映させることで、不調対策をしっかりと、不調を防いでいこうといったところを取組として今進めていたところです。いわゆる予定価格が比較的低かったことから不調になっている事例も聞いているところですので、不調対策を進めてきたといったところです。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問・要望","question":"要望も含めて、先方がある話ですから、手を挙げてくれるところがどれぐらいあるのかというところもあると思います。何というのでしょうか、決意というか、ぜひ成し遂げるという決意を最後お伺いしたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"この新庁舎につきましては、委員のご案内のとおり、非常に長きにわたって検討を重ねてきたところです。今回予算の中でしっかりと、我々としてもスケジュールどおりに進められるよう、今後もしっかりと対応をしていきたいと考えるところです。","id":"exchange-014"}]},{"id":"topic-03","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"１点だけ、現庁舎跡地等についてというところの（４）番で、これは「地域経済への効果を」としたほうが分かりやすいのかなと思いました。経済効果というものは品川区での効果ということだと思いますので、そのほうがいいのかなとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"こちらも１年、この策定委員会に区議会の代表も入れていただきたいということで、これは入れていただければなと思います。多分私どもの会派だけではなくて、ほかの会派からも出ていましたので、ぜひ入れてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/390831?Template=document&Id=7029#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":19991,"voices":66}},{"id":"r07-20250417-19","meetingId":"r07-cm04","date":"2025年4月17日","dateIso":"2025-04-17","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時０２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"エコルフェス－２０２５ ＳＰＲＩＮＧ－の開催","agenda":"エコルフェス－２０２５ ＳＰＲＩＮＧ－の開催","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"きっとやっているに違いないと思いつつ確認なのですけれども、キッチンカーの電気はこの屋上で発電した電気を使っておりますとかいう宣伝というのでしょうか、そういうことはされる予定はいかがか尋ねました。","respondent":"中西環境課長","answer":"今回も同じようにやる予定です。そこがスタートアップ企業であるというところで、地域産業振興課のほうとも連携しながら、何か掲示ができないかというところは今検討しています。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問・要望","question":"できれば要望なのですけれども、蓄電機を置くではないですか。一応要望なのですけれども、どう使うのか、もしやっていただければありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"品川区災害時トイレ確保・管理計画","agenda":"品川区災害時トイレ確保・管理計画","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"このＡ３判の資料で、簡易トイレは４９４基あるということですけれども、そういうものはどう考えられているのか伺いたい。マンホールトイレで、しかも下水に直結しているものというのは、この５２０基のうちどれくらいあるのか伺いたいのですが、お願いします。","respondent":"羽鳥防災課長","answer":"間仕切りについては、やはり便器だけですと使用できませんので、その上物、テントも含めて併せて備蓄をしている状況です。直結していてもそこに貯留できるタイプなど、いろいろありますので、そういったところは今後詳細の数値のほうは確認してまいりたいと考えています。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"提案","question":"「災害時に使いたいのはどのトイレですか」という問いに対しても、仮設トイレとかあるのですけれども、マンホールトイレが８２％になっていたりとの意見を述べました。","respondent":"羽鳥防災課長","answer":"そういった用地が出てきたときに検討するという内容ではありますが、直近ですと、そこにもマンホールトイレが設置されてあります。そういった区有施設の改築の機会を捉えてマンホールトイレを設置する、増やしていくように対応していきたいと考えています。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"大きい３番の、発災から１か月後でマイナス８５９基ということなのですけれども、これを充足させるという考え方でいいのですか。３,２１９基なのか８５９基なのか、３,２１９基のほうだとしたら、これをゼロにするということを目指すということなのか尋ねました。","respondent":"羽鳥防災課長","answer":"やはり区としてはこれをゼロにするというところが目標です。今回この計画を立てたところで、可視化できましたので、早めに手を打てるというところが今回のメリットだったのかなとは考えてあります。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"マイナス３,２１９基をゼロにするというところを目指すということで、そして、この計画もよかったなと思っています。「区民避難所から半径２５０ｍ圏内にあるトイレを含めると、耐震化とかもされているのかというところまで把握されているということか尋ねました。","respondent":"羽鳥防災課長","answer":"耐震化されているトイレは、「災害対応型トイレ」となっていますのが、上下水道の管が耐震化されたトイレという形になってあります。スフィア基準の５０人に１基、２０人に１基という部分も、便器の数で算出をしているという状況です。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"避難所から半径２５０メートル圏内にあるトイレというのは、大きい２番の（１）で言うと災害対応型トイレということなので、区の関わりのある施設ということでいいか尋ねました。","respondent":"羽鳥防災課長","answer":"委員のおっしゃるとおり、区有施設のトイレになります。コンビニですとか商業施設、そういったトイレは含まれてございません。","id":"exchange-007"},{"speaker":"えのした委員","kind":"質問・要望","question":"３月はしながわシティランでお披露目展示ですね、私も実際に使用させていただきました。まだ２回しか展示されていないので、この２回展示された中で何か気づいた点ですとか、課題に思った点があれば教えてほしいと求めました。","respondent":"羽鳥防災課長","answer":"今後利用方法についても検討させていただきたいのと、男性、やはり分けてほしいというお声もいただいてあります。いろいろ今回課題が見えてまいりましたので、そういった課題も含めて、いろいろ検討してまいりたいと考えています。","id":"exchange-008"},{"speaker":"えのした委員","kind":"質問・要望","question":"本当に助け合いですから、また、またますますトイレトラックのネットワークというのが広がっていくのではないかなと私は考えるところであります。その辺についてはいかがか尋ねました。","respondent":"羽鳥防災課長","answer":"で、いろいろ課題は出てくると思いますので、展示ということであればそういった連携は比較的可能性はあるのかなとは考えてあります。今後そういった平時のトイレネットワークの連携も含めて、いろいろ検討してまいりたいと考えています。","id":"exchange-009"},{"speaker":"えのした委員","kind":"質問・要望","question":"本当に地元の地域にトイレトラックが来てほしいというお声も地域の方からお話を伺っていますので、そちらのほうも要望として終わりにします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"発災後２週間までとか１週間以降ということですか、２０人に１基ということで、どこから来ているのかというのをご説明いただきたいのと。","respondent":"羽鳥防災課長","answer":"ですので、５０人に１基という認識は、多少不便でも災害発生当初はそれで耐えていただく。ただ、長期化するとなかなかその基準ですと厳しいので、２０人に１基ということで、より環境を整えるという認識です。","id":"exchange-011"},{"speaker":"塚本委員","kind":"確認","question":"きちんとしたトイレを増やして使えるようにしていくということで不足が出てくると、こういう認識でいいのかということで一応ご確認したいと求めました。","respondent":"羽鳥防災課長","answer":"５０人に１基、２０人に１基の考え方ですが、なるべく長期化したときはトイレを含めた生活環境を改善していくという考え方かなと認識しています。災害時には断水するエリアと断水していないエリアで対応が異なりますので、災害時にそういった個々の状況が発生する。","id":"exchange-012"},{"speaker":"ひがし委員","kind":"質問","question":"今年度の１月ぐらいに記事を読んでいたら、男性のほうが時間はかからないけれども個数が多くて並ばないのだみたいな記事を拝見させていただきました。","respondent":"羽鳥防災課長","answer":"それを踏まえまして、品川区といたしましても、避難所運営マニュアルに災害用のトイレは男女比１対３で設置することと書かせていただいております。","id":"exchange-013"},{"speaker":"こんの委員","kind":"質問・要望","question":"そのときに、この辺の耐震化というところは、そうしたことがもう既にスタートしているのであればその辺を教えてほしいと求めました。","respondent":"羽鳥防災課長","answer":"上下水道の耐震のところにつきましては、管轄する東京都のほうで計画的に対策が進められているというところで認識していますが、まず。トイレ以外も含めて、そういった部分はＴＫＢＢの視点も踏まえて対策をとってまいりたいと考えています。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問・要望","question":"何か所かある、１階から４階、３階までの校舎の１系統という理解でいいのかといったところを確認させていただきたい。この表でいくと、２０人に１基のときに不足するよという学校は、その辺は丸になっているので大丈夫なのですかというのをいま一度確認したいと求めました。","respondent":"羽鳥防災課長","answer":"徒歩５分圏内にあるトイレを合計いたしまして、それぞれ２０人に１基、５０人に１基を割り返しているという状況です。不足していないところが８か所あったというところで、想定避難者数で割り返したところ、充足しているという状況です。","id":"exchange-015"},{"speaker":"こんの委員","kind":"質問・要望","question":"だから、１つの管だけは耐震化されているので、ほかの耐震化されていないところを簡易トイレとして使うという理解でいいのでしょうか。避難所の中のエリアの見直しというのはどういったことなのかをご説明ほしいと求めました。","respondent":"羽鳥防災課長","answer":"既存の耐震化されているもの、不足しているものに関しましては、組立式の簡易トイレというのをさらに配置いたします。その配置するという計画は立てるものの、そこも含めて検討するという内容になってあります。","id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"で、しつらえになっておりますが、その中でやはりこの辺をこういうふうに使ったほうがいいですよみたいな案は持ち合わせているのでしょうか。ゼロベースで協議会というか検討会へ投げてもなかなか難しいかなと思うのですが、品川区の想定している案などがあるのか尋ねました。","respondent":"羽鳥防災課長","answer":"昨年度、そういった委員のご指摘もありますので、品川区として標準的な避難所の運営の方針を定めたマニュアルを定めさせていただきました。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"そこら辺の案はお持ちですかということですけれども、そういうのは、標準の中にこんなふうに考えていったほうがいいですよ。標準マニュアルの中にそういうのも示してさしあげたほうが検討しやすいかなと思ったので、その辺をお伺いしましたけれども、いかがか尋ねました。","respondent":"羽鳥防災課長","answer":"要配慮者のことも考えて、男女をしっかり分ける、そういった様々な配慮が必要になってくると思います。そういった動線であったりスペースが確保できるのかというところを細部まで詰めていくような作業になるのかなと考えています。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"簡易トイレのスペースも今後早急にというか、なるべく早くこのことを検討していただきながら、体制をつくっていただきたいなと思います。","respondent":"羽鳥防災課長","answer":"今回、防災課のほうで災害時のトイレ確保・管理計画というものを策定いたしました。今後、庁内にこの計画を共有いたしまして、各所管で必要な対策を進めていただければと考えています。","id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"品川区内も２００超の町会、防災に関してというのは温度差があるところ、当然地域性にもよるではないですか。私はすごくそれを痛感したので、ぜひお願いしたいと思っていますので、もしそのことで何かあれば、要望なのですけれども、。","respondent":"羽鳥防災課長","answer":"実は本計画にも、２６ページになりますが、令和６年度に実施した携帯トイレ全区民配布で今後の使い方を啓発すると書かせていただいております。これに基づきまして、区といたしましても積極的に地域の皆様にご活用いただけるように啓発してまいりたいと考えています。","id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"いま一度要望とします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"具体的に伺いたいのですけれども、先ほど耐震化されているところは１系統ということで、その点を伺いたいです。１３ページのところに、災害時のトイレを使えるかどうかということで、そのところを伺いたいと思います。","respondent":"羽鳥防災課長","answer":"最初のご質問ですが、耐震化されていないトイレにつきましては、断水が起きている状況の際は携帯トイレを使うという考え方です。そういったやり方で断水状況という、被害状況というのを確認していただいてからご利用いただくというのが順番になります。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それはだから一般の人でも簡単に点検ができるということで考えていいのか、その点も伺いたいと思います。ぜひそうしていただいたほうがさらに使えるようになるのかなと思うのですけれども、そこの方針、計画についても伺いたいと思います。","respondent":"羽鳥防災課長","answer":"いっぱいになってしまったらもう使えなくなりますし、まずは断水が起きているようであれば携帯トイレのほうをご利用いただくと考えています。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問・要望","question":"被害想定というところで帰宅困難者が２３万３,３１６人ということであるのですけれども、４ページのところに、そこら辺のところはどう考えられているのかも教えてほしいと求めました。","respondent":"羽鳥防災課長","answer":"で、区といたしましては民間事業者とも協定を結んで一時滞在施設というものを確保しています。一時滞在施設については、区としては３日分の携帯トイレの備蓄をさせていただいていますので、そちらをご利用いただくということで対応しています。","id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問","question":"そのときに水をどう確保していくかというところで、防災井戸というのは各避難所は全て設置されているのか、そのことも伺いたいと思います。生活用水という点では必要ではないかなと思うのですけれども、そこら辺の方針はどうなっているのかも伺いたいと思います。","respondent":"羽鳥防災課長、溝口防災まちづくり部長","answer":"その場所に設置できるかできないか、状況がありますので、実際に設置されている井戸とマンホールトイレが併設されていて。先ほど防災課長が答えたように、できるところはしっかり、マンホールトイレを含め、また、井戸を設置していきたいとは考えているところです。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"さらによりもっと安心にということも進めていただきたいですし、区民への周知徹底という点ではどのように考えられているのか伺いたいと思います。先ほど３,２１９基を、そこのところはいつまでにどういう形で設置を進めていくかというのは、その点についても伺います。","respondent":"羽鳥防災課長","answer":"こちらは区として備蓄や整備をするということはやはり具体的には現実的ではないかとは考えてあります。そこは国や都、他自治体、民間事業者、そういった協力体制を平時から築いていくというところで対応をとってまいりたいと考えています。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"だって調べられないではないですか。ああしてくれとは言えないと思うのですが、まずそこをどのようにお考えになっているのか、基礎的なことだけ説明するよう求めました。","respondent":"羽鳥防災課長","answer":"排水設備の確認がとれるまでは水を流さずに携帯トイレをということでお願いしています。平時からどういうふうに確認をとるのかというところを確認しておいていただくというところが重要になってくるのかなと考えています。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"１,０００人から１,３００人ぐらいは使えるという話が、６００人だったら、これで満杯になってしまったらどこで給水するのですか。これは本当に、耐震化は分かるのですけれども、給水化というのができてないと全く機能しないのではないか尋ねました。","respondent":"羽鳥防災課長","answer":"先ほども説明したように井戸もあるというところの、上水が断水した場合でもそういった水を使って流すということで考えているところです。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"まして暗かったら絶対行けないではないですか。そうすると、病気になったり倒れたりする方も増えるのではないかと思うのですが、この辺はどういうふうにお考えになっているのか説明するよう求めました。","respondent":"羽鳥防災課長","answer":"体調を崩して、最悪の場合は災害関連死ということにつながりかねませんので、トイレの環境というのは改善が必要だと考えています。便器の和式については、便器のほうは洋式でなるべくご利用できるような体制はとっているところです。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"それが災害が起きた、どうするのだ、いや、災害だから何とか使いなさいと言っても、私はそれはやはり難しいのではないかと思います。ぜひ、大変だと思うのですけれども、様々な対応を予算がかからない方法で私はやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"せお委員","kind":"質問","question":"１点だけなのですけれども、それを共有したりしているのかというところも含めてなのですけれども、そういうのを説明するよう求めました。","respondent":"羽鳥防災課長","answer":"他区の状況を確認したところ、ネットで検索するレベルではありますが、近隣区については特に計画が作成されている状況は確認できておりません。今後、他区の防災の課長会などで情報共有させていただきながら、他区と連携を深めていきたいと考えています。","id":"exchange-031"},{"speaker":"せお委員","kind":"質問・要望","question":"ぜひこれからですけれども、協力だったりとか、そういったところを含めて連携は大切になってくるのかなと。やはり空白エリアが区境だったりするので、そういったところでも何か連携できるのか模索していっていただきたいなと、それだけ要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"１個ではないよ、もう１６個やってしまえといって、そこはちょっと違うのかなと思っているのですよね。何が大切かというのを引き続き考えていきたい、いただきたいなと思っていますけれども、それについて。","respondent":"羽鳥防災課長","answer":"生活環境が悪化する避難者の生活をどう区として対応していくかというところのまず一つの策であると考えています。方針、区としてはバランスよく対応していくという方針で、今後もいろいろ検討してまいりたいと考えていますので。","id":"exchange-033"},{"speaker":"ゆきた副委員長","kind":"質問","question":"東京都トイレ防災マスタープランでは、今できたばかりですけれども、この点について今後の道筋というものがあればお聞きしたいと思います。","respondent":"羽鳥防災課長","answer":"今後、都とも連携しながら様々な面で対応を進めていくと考えています。今後そういったものも踏まえましてどういった利用ができるのか、財政当局とも協議の上、検討してまいりたいと考えています。","id":"exchange-034"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"新年度の東京都の予算の活用については、補正予算とかを使っていただいて活用に努めてほしいと求めました。こちらは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"１３ページに、自分の区だけでは調達できないものについてお互いに譲り合うというのでしょうか、ここに視点を持ったのはよかったなと思って。その後、いざくみ取り式のマンホールトイレとか、それからためておくということになったら必ず必要ではないか尋ねました。","respondent":"羽鳥防災課長","answer":"防災課のほうで詳細は把握していないところではありますが、もちろん都と連携をしながら対策をとるところと、それでは足りない部分に関しましては民間事業者の力も得ながら対応していくということになろうかと考えています。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、こういう災害のときのし尿収集車の台数の不足というのは、まさにこの所管のところで問題になるわけではないですか。これは今は要望にとどめておきますので、ぜひ今後ご検討いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-03","title":"品川区防災ポータル・アプリの導入","agenda":"品川区防災ポータル・アプリの導入","exchanges":[{"speaker":"まつざわ委員","kind":"確認","question":"すみません、確認だけさせてください。もう全部被害状況とか、アプリごと切り替わって、画面ごと変わってしまうのか尋ねました。","respondent":"羽鳥防災課長","answer":"平常時の情報に関しましてはそのまま残して、少しレイアウトを変更して災害情報が上のほうにいくような設計になっています。被災情報であったり避難所の開設状況といったところは、災害時モードで初めて表示されるという状況になってあります。","id":"exchange-038"},{"speaker":"まつざわ委員","kind":"質問","question":"とてもいい取組だなと、ぜひこのＷｉ－Ｆｉを活用して災害の訓練に役立ててほしいという話をしたら、何かそんな答弁があったのです。１年に１回、そのようなものがないからどういうふうなのかが分かっていないのですけれども、そこら辺どうか尋ねました。","respondent":"羽鳥防災課長","answer":"訓練のときの活用ですが、テスト環境をつくって訓練用に災害モードに切り替えるということも、可能かどうかも含めて検討してまいりたいと考えております。","id":"exchange-039"}]},{"id":"topic-04","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"裏ページというのですか、防災の２ページ目のところの一番上の（２）のところなのですけれども、これは個別避難計画ではないのか尋ねました。","respondent":"大倉委員長","answer":"在宅避難のところの（２）の「活用について周知・啓発等を含め」ということで、正副で話し合って提出させていただければと思います。","id":"exchange-040"},{"speaker":"鈴木委員","kind":"意見","question":"「避難行動要支援者の対象に障害者も含まれていることを示すなど、表記方法に十分配慮されたい」というのが、意味がよく分からないなと。どういう意味で、どこに表記するのかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/505358?Template=document&Id=7031#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":37218,"voices":128}},{"id":"r07-20250425-10","meetingId":"r07-cm04","date":"2025年4月25日","dateIso":"2025-04-25","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"特別委員会の調査事項等","agenda":"特別委員会の調査事項等","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"今ご説明いただきました件の中で確認をさせていただきたい点があります。それは、備考のほうもよろしいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"こんの委員","kind":"提案","question":"それから３点目が、その活用についても、「など」という中に確認をさせてほしいと求めました。どのように考えていらっしゃるのかといったところも提案させていただきましたので、このようにお願いをしたいと思っているところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"山本委員","kind":"質問・要望","question":"当会派から２年越しで要望させていただきました事項でもあり、特に、ありがとうございました。３つ目のまちづくり・公共交通推進特別委員会では、当会派から要望した新庁舎、ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"せお委員","kind":"質問・要望","question":"３つの会派からでしょうか、要望があった上で、正副委員長には感謝申し上げたいと思います。確認なのですけれども、一定の成果を出すというか、そういった目的が加わっているという理解でよろしいか尋ねました。","respondent":"まつざわ委員長","answer":"４月１４日の議会運営委員会でいろいろな話が出たときに、特別委員会の在り方というのをもう一度いろいろ検討しましょうというお話の中で、そして最終的には区長にしっかりと提言していくという特別委員会であっていきたいと考えています。","id":"exchange-004"},{"speaker":"安藤委員","kind":"提案","question":"議会として委員会として提案するけれども、きちんとまとまったところを提案していくというところが私は大事だと思いますので、意見だけ述べしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"安藤委員","kind":"提案","question":"よく議論することが大事、そして、その結果まとまったものについては、提案していくと。そのまとめる努力とか議論する努力というのは、共産党としてもやっていくということは考えているということだけ述べさせてほしいと求めました。","respondent":"あくつ副議長","answer":"しっかり区長に実現を迫っていく、意見を収れんしていく、そのことの努力はしっかりしていただきたいと思います。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"特別委員会の調査事項、要望はかなりたくさん出たのだと思うのです。確認なのですが、皆さんのいろいろな要望はありましたけれども、その特別委員会の中で決めていくというスタンスでいいのですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"これは委員会なわけですから、議員によって所属する委員会の数が違うという不公平についてはどのように考えているのか。全ての議員が公平に特別委員会と常任委員会に所属するというのが議会の本来の在り方だと私は思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"安藤委員","kind":"提案","question":"それをなぜ改善しないのですか。なぜ改善しないのか尋ねました。","respondent":"まつざわ委員長","answer":"やりたいという方もいらっしゃれば、それは迷惑だからやらないでほしいという方も実際にいらっしゃいました。特別委員会に、無所属一丸となって入れてくださいというお話は、私にはありませんでした。","id":"exchange-009"},{"speaker":"須貝委員","kind":"提案","question":"安藤委員からそういう提案が出ましたけれども、せっかく提案していただいたので、検討する場をつくられたらいかがかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"せお委員","kind":"意見","question":"私は９人でよろしいかと思います。一定の提言というのをまとめるに当たっては、１３人では多いと感じておりますので、そこは私たち会派も９人が妥当なのではないかと考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"安藤委員","kind":"提案","question":"須貝委員より、別の場をつくって討議したらどうかという提案だと私は受け止めたのですけれども、どのようにお考えなのか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"塚本委員","kind":"確認","question":"ペーパーレスは全然いいかと思うのですけれども、基本的には今あるものが、そのままペーパーレスですか。多少、中身は省くようなものが出たりはするのか尋ねました。","respondent":"大澤区議会事務局長","answer":"この形のままアップするということではなくて、ここに載っている必要な情報については、何らかの形で皆さんに、紙ではなくてお手元に行くようにいたします。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/350163?Template=document&Id=7033#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":12767,"voices":47}},{"id":"r07-20250512-6","meetingId":"r07-cm05","date":"2025年5月12日","dateIso":"2025-05-12","committee":"区民委員会","time":"午後 １時００分～午後 ３時４２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件整理しています。","topics":[{"id":"topic-01","title":"「荏原町安全安心ステーション」の廃止","agenda":"「荏原町安全安心ステーション」の廃止","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"協議というのはいつ行うのかというところを教えていただきたいのと、考えでその協議に臨むのかということを確認させていただきたいのが１つです。","respondent":"澤邉生活安全担当課長","answer":"２点目、町会の意見を聞きながら、そういったところも含めて協議していきたいと考えています。区として把握している部分だけですが、商店街を中心に約２３個の防犯カメラの設置があると把握しております。そのボタンについては、次が何になるかにもよるのですけれども、基本的には外すような形になると思います。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"話合いの間、どんな意見が出されたのかなというか、少し紹介してほしいと求めました。廃止に反対という声はなかったのかというのも含めて、教えてほしいと求めました。","respondent":"澤邉生活安全担当課長","answer":"開設された平成１９年当時とは社会情勢も変わりまして、今はスマホだとか、ひとつ仕方がないのかなというようなご意見もありました。むしろ、高齢者の方がこういうふうに働き続けるということはどうなのだというような意見もいただいたぐらいです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"１８年前に、交番を残してほしいという大きな地域の要求運動が相当あったのですよね。ちょっと難しい質問かもしれないのですけれども、お願いしたいと思います。","respondent":"澤邉生活安全担当課長","answer":"基本的に区としましては、警察４署ありますけれども、そこと連携してこういった防犯を進めていくというスタンスは変わりません。先ほどご説明させていただきましたが、そういったもろもろを総合的に考えて、治安上の問題は生じないと考えます。","id":"exchange-003"},{"speaker":"安藤委員","kind":"意見","question":"あるいは周辺の関係ですとか、そういったことを踏まえた上で、ぜひご検討していただければと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"今の質疑で確認させていただいた中でも、あと、推進員の声もお聞きしながら進めてきたということを確認させていただきました。平均年齢が８０歳以上の方々ということですけれども、要望があれば受けるという形だけではなくて、この辺についてお聞きできればと思います。","respondent":"澤邉生活安全担当課長","answer":"平均年齢８０歳以上と申し上げましたけれども、皆様かくしゃくとしていらっしゃいます。そういった方々が働ける場だとか、そういったことを何か、課を超えてになりますけれども、我々も考えていきたいと考えています。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"確認させていただきました。ぜひ推進員の方々の意向を酌んで、受け身ではなくて、要望に沿った形で進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"おぎの委員","kind":"意見","question":"公表するかどうかというのは防犯面でまた難しいかと思いますので、また地域の町会の方のお話を聞きながら、進めていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"なかったですか。１０年前、その辺のチェックというのは区が指導してやっていっていただきたいと私は思うのですけれども、いかがか尋ねました。","respondent":"小林地域産業振興課長、澤邉生活安全担当課長","answer":"９０歳を超えても登録されている方とか、８０歳後半で実際に働かれている方もいらっしゃいますので、特に年齢制限があるものではございません。健康状態、体力の状況などに合わせて働いていただいているという状況です。そういった施策を広めていきまして、ぜひとも新しいものに付け替えるといったところについても、区として広報していきたいと考えています。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"５月ですから、やはり１回つけたらつけっ放しでないといけないのかなと思われているところもあるので、そうではないのだと。間違いなく防犯カメラというのは効果があるというのはもう分かっていることですから、まず説明して、その辺についてはいかがか尋ねました。","respondent":"澤邉生活安全担当課長","answer":"まだ私も着任１か月半ですけれども、実際に私も行かせていただきまして、説明はさせていただきました。そういったものについては丁寧に対応していきたいと思います。","id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１回そこを逃げ道として、１つの象徴するステーションとして、ぜひ取り組んでいっていただきたいなと。これは要望で、ぜひその辺の視点を含めて検討してほしいと求めましたが、何かあればお話しほしいと求めました。","respondent":"澤邉生活安全担当課長","answer":"実際にやる業務の中身にもよるのですけれども、委員のお話になったところになると、本当に交番機能のような形になるのかと思っています。","id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"地域の方たちのご意見を活かしてこの土地の活用をする場合、これはあくまで使用貸借を前提とした協議を進められるということなのでしょうか。その点、確認させてほしいと求めました。","respondent":"澤邉生活安全担当課長","answer":"交番があった昭和４９年から使用貸借契約でずっと来ておりまして、平成１９年に設置した際にも、新たに使用貸借ということで契約を行っております。私どもとしましては、地域の皆様のご要望をお届けして、何とか引き続きできるような形を模索してまいりたいと思っています。","id":"exchange-011"},{"speaker":"吉田副委員長","kind":"提案","question":"区としてはどうしても使用貸借でいきたいという方向なのかということを伺ったのですけれども、使用貸借でない、いわゆる賃貸借になるのでしょうか。そこまで検討されているのか、今おっしゃれる範囲で結構ですので、伺いたいと思いますが、いかがか尋ねました。","respondent":"澤邉生活安全担当課長","answer":"私の浅はかな知識で言いますと、使用貸借というのは、土地の所有者から無償で土地のほうを限定して借りるです。土地を賃貸借にするのかということまでは、今、考えておりません。","id":"exchange-012"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"どうしても使用貸借と言い張る必要もないのかなと思って、今のところ品川区としてはそこまで全然考えていないということでよろしいでしょうか。要望としては、それとしてはすごく弱いと思うのですけれども、いかがか尋ねました。","respondent":"澤邉生活安全担当課長","answer":"考え方としては、使用貸借だと発生しないという部分で、双方にメリットがあるのかなと考えております。無償のような形で、跡地を地元の方たちに使っていただくような形で、何とか交渉したいというのが担当としての考えです。","id":"exchange-013"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そういうことも、こちらの交渉のときのカードと言うのはちょっと嫌らしい言い方になるかもしれませんけれども、あってもいいのかなと思いました。これ以上はもう答弁は求めませんけれども、私の意見として申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"八潮地区における買物弱者支援事業","agenda":"八潮地区における買物弱者支援事業","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"教えていただきたいなというのと、区の事業費用は発生しているのかどうか、その辺を伺います。","respondent":"今井八潮まちづくり担当課長","answer":"エリアの右下側、都営４８～５０号棟エリアにつきましては、隔週月曜日に移動販売を実施していただいているところでございまして。生鮮食品、先ほど冒頭にご説明いたしました、パン工房プチレーブのパンの移動販売が毎週水曜日の１４時から１５時まで実施されているところです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"費用もまだかかっていないということですけれども。そこら辺についてはどうなのかというのをお伺いしたいのと、それと、これはどんな覚書の内容なのかというのをご紹介ほしいと求めました。","respondent":"今井八潮まちづくり担当課長","answer":"覚書については２種類ございまして、都・区、連携して取り組んでいきましょうといったような約束事が取り交わされているものです。実施場所としてどこの都営住宅の敷地の中で販売をするかといったような内容ですとか、実施日時ですね、それから販売商品の内容といったところで。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"後で教えていただけないでしょうかというのが１つと、移動販売になったその経緯というのですか、確かに先ほど課長の答弁にもありましたが。そこに至るまでの検討の経過をもう少し伺いたいのですけれども、その中で移動支援の要望、そこら辺の検討経過を伺いたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"この実施に当たっては、その場でご紹介いただいたのが、今回の東京都の事業スキームである都営住宅における買物弱者支援事業というものです。実施の要件として、移動販売事業者でどこか八潮地区内で移動販売を実施できるところはないかという検討をさせていただいて。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺をお伺いしたいのと、近くに店が来てくれるという、もしかすると商品の値段とかというのもちょっと割高になる可能性もあると思うのです。その辺の体制をとってほしいという要望なども住民のほうからはあって、いかがか尋ねました。","respondent":"今井八潮まちづくり担当課長","answer":"東京都につきましては、一部を使わせてもらうといった事業になりますので、基本的には東京都のほうも費用はかかっていないと認識しております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"意見","question":"本質的には買物支援だと思うので、今回こういった形で移動販売ということで事業がスタートいたしましたけれども、やる中で、様々、当事者の住民の方の声を聞きながら、移動支援なども検討していっていただければありがたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"おぎの委員","kind":"質問","question":"私からも何点かお聞きしたいのですが、雨天のときの対応はどうなっているのかというのと、１者ですか。今後また何者か増える予定とかはあるのか、説明するよう求めました。","respondent":"今井八潮まちづくり担当課長","answer":"雨天時の対応なのですけれども、基本的には、例えば都営住宅の敷地のひさしの下とか、ぬれないところで販売できるように対応を検討しています。個人事業主としては２者で、機会を捉えて、拡大に向けて調整を進めていきたいと考えております。","id":"exchange-020"},{"speaker":"おぎの委員","kind":"質問","question":"天気にも対応できて、その場所なのかなという気がしました。お買物なんかもとても楽しく、外出の機会も増えるのでいいと思うのですけれども、広報の方法というのはどういった予定か尋ねました。","respondent":"今井八潮まちづくり担当課長","answer":"あるいは各自治会の中にある自治会の掲示板に掲出していただいたりといったようなことで事業のＰＲに取り組んでいるのと、あと最近できましたＩＫＵＭＯの施設にもこの移動販売のパンフレットとかを置いていただきまして、ＰＲをさせていただいているところです。","id":"exchange-021"},{"speaker":"おぎの委員","kind":"意見","question":"品川区のホームページを見られない方もいらっしゃると思いますので、チラシとかをつくっていただくのはすごくいいと思います。ぜひ皆さんが利用しやすいように工夫していただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"石田（し）委員","kind":"質問","question":"場所を提供しているだけですと言われたら、では、何かあったときに誰が責任をとるのですかというところでもあるわけです。なので、今回、どういうふうに報告事項として上がってきたのか分からないのだけれども、その辺、改めて説明するよう求めました。","respondent":"今井八潮まちづくり担当課長","answer":"申し訳ありません。１月２５日から試験運用という形で、どういった内容で販売するのがいいのかいろいろトライアル的に試しながら実施をしてきたところでして。","id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なので、そこはやはりもう少し丁寧に報告事項の在り方を考えてほしい。これは別に答弁は要らないですけれども、ぜひその辺は、特に前列の皆さんにはしっかりと、いわゆる情報共有については考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"せお委員","kind":"質問","question":"私としても、今、石田しんご委員がおっしゃったようなところは感じていたので、ぜひ考えていってほしいというところです。もしかしたらスーパーの需要が減ってしまうのかなというところで、そこら辺の話合いとかは何かあったのか、説明するよう求めました。","respondent":"今井八潮まちづくり担当課長","answer":"その期間、例えば駐車場ですとかスーパーの別の敷地とかを使って販売とかができないのかといったような調整を最初にとらせていただいたところです。ただ、品川区で対応を検討した結果、スーパーバリュー側との関係性が悪くなるといったようなことはないと思っているところです。","id":"exchange-025"},{"speaker":"せお委員","kind":"意見","question":"事業者が変わってしまうということですけれども、区民の方はもちろんですけど、こういう事業者とも関係性がよくなるような取組をぜひ続けていただくよう求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"どういう経過でこの販売事業者が選ばれて、どういう契約になっているかというのは、ここの委員会での意見にもすごく影響すると思うのです。","respondent":"今井八潮まちづくり担当課長","answer":"この事業者で販売内容としてもふさわしいということで、区としてお声かけをさせていただいて、移動販売をしていただいているといったような形です。移動販売を実施してほしいと個別に調整をとらせていただいて、覚書を締結して、実施していただいているといったような状況です。","id":"exchange-027"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"募集したわけでもなく、ピンポイントでその事業者をこちらが選んで、契約ではなく覚書ということなのでしょうか。そういう自由を求めるのだったら何か手続が必要になるかと思うのですけれども、その点についてはいかがか尋ねました。","respondent":"今井八潮まちづくり担当課長","answer":"東京都側との調整もとらせていただいて、実現するということは今後も十分考えられますし、可能な仕組みになっております。区としては、八潮地域内で販売のなじみのある、こういった事業者に声をかけさせていただいて実施しているといったところです。","id":"exchange-028"},{"speaker":"吉田副委員長","kind":"質問","question":"就労継続支援Ａ型の事業所ですから、やはり販売者を決める何か手続というか、しかるべき手順があってもよかったのではないかなと。もし何か見解とか伺えることがあったら、聞きたいです。","respondent":"今井八潮まちづくり担当課長","answer":"先ほどご説明した内容と重複もしてくるのですけれども、買物弱者支援事業の発端といたしましては、直近の。今回は緊急的な対応といったところで事業者をこのような形で決定いたしましたけれども、今後の課題として考えさせていただければと思います。","id":"exchange-029"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"これはあくまで要望です。強く要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"撤退したらどうしよう、どうしよう、しないかもしれないわけではないですか。八潮の将来ということを考えたら、今から課題として考えていかないといけないと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"今井八潮まちづくり担当課長","answer":"八潮まちづくり担当としても、広い意味で、長期的な目線で対応していかなければいけないと考えているところです。は、新たな事業者を見つけて、徐々に事業を拡大できるように取り組んでまいりたいと考えています。","id":"exchange-031"}]},{"id":"topic-03","title":"氏名の振り仮名法制化に伴う品川区の対応","agenda":"氏名の振り仮名法制化に伴う品川区の対応","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"品川区は全て住所が分かるものなのですかというか、そこら辺どうなのかというのを伺いたいなと思います。それと、はがきなのですけれども、はがきを送るとあるのですが、個人情報などプライバシーが配慮されたものになっているのかどうか、伺います。","respondent":"築山戸籍住民課長","answer":"３点目の質問です。こちらは個人情報保護がされている形で、開かないと分からない形式のはがきを使いますので、そこは保護されているもので送付する予定です。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"中小企業センターですから、第２庁舎の部屋とかで、ほかの場所というのは検討できなかったのでしょうか。１１日号の広報も見せていただいたのですけれども、工夫をいただきたいのですが、いかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"会場についてですが、会場は様々検討してきたところです。周知は区でもしてまいりますが、広報紙ももう一度発行いたしますが、このような形で周知してまいりたいと考えております。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"はがき送付が６月下旬ということで、コールセンターはその前から、今月末からということなのですけれども、まだ時間は若干あると思うのです。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"おぎの委員","kind":"質問","question":"件数を考えますと、結構大変な作業と思うのですが、特設会場・コールセンターの部署となります中小企業センターには、増員というか、職員の配置はどれぐらいになっているのか尋ねました。","respondent":"築山戸籍住民課長","answer":"職員の配置の状況ですが、繁忙の状況にもよりますけれども、職員１０名と、あと委託事業者も入れますので、そこで２０名程度を想定しています。","id":"exchange-035"},{"speaker":"おぎの委員","kind":"質問・要望","question":"なかなか大人数で１年間取り組んでいただくという形になるのだと確認しました。こちらは要望で、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"ゆきた委員","kind":"質問","question":"郵送で希望する方もいると思うのですけれども、その場合、切手の費用はどうなるのか。一定数あると思うのですが、そこについての予算の考慮もされているのか、お聞きしたいと思います。","respondent":"築山戸籍住民課長","answer":"郵送の場合につきましては、そのままご返信いただくような形を考えております。","id":"exchange-037"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"それが１点で、もう１つは、はがきで送らないとかそういう人は、中小企業センターとか設置されているところに行って申請するのですか。予想すると大体４万人ぐらいいるのではないかという数で役所としては考えているということでいいのか尋ねました。","respondent":"築山戸籍住民課長","answer":"委員のおっしゃるとおりで、まず、人数としては大体４万人ぐらい、誤っていて届出が必要になるのではないかと想定しています。窓口にお越しいただくということのほか、マイナンバーを持っている方はマイナポータルから正しいお名前を届け出ていただくというような形になります。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"そこまでは分かって、最初の質問で、一番最初の一歩で、「しながわ」さんと「ひんかわ」さん、そういう理解でいいのですよね。最初の一歩はそれでいいのですよね。","respondent":"築山戸籍住民課長","answer":"おっしゃるとおりで、名前の振り仮名が間違っていなければ、何もしなくて結構です。読み方が、「ひんかわ」さんが「しながわ」さんとなっていた場合は、正しくは「ひんかわ」ですというように届け出ていただく必要があるです。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"品川区だから「しながわ」さんと言っているだけですからね、まあ、「しながわ」だろうなという感覚でやるということですか。だから、１回目というか、最初は大体予想をつけて出してみようという思いでいいのか尋ねました。","respondent":"築山戸籍住民課長","answer":"異動等の手続がなかった方は、昔の紙のときの情報のまま、自治体が振り仮名を登録している場合があります。今回、これまで分からなかった、間違って登録していたという方々がたくさん出てくるのではないかと考えているところです。","id":"exchange-041"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"区から直接何かを求めることはないですよというのを、やはりそろそろ公式な郵送をするときのルール化というか、ぜひ進めていただきたい。なので、ぜひその辺、改めて検討して考えていただきたいなと思うので、これは要望で終わりますが、ぜひ検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"視覚障害者の方へのはがき上の配慮はどういうふうになっているのか、改めて確認させてほしいと求めました。その方に読んでもらってやってもらうのだと思うのですけれども、直接区としての配慮があったら、説明するよう求めました。","respondent":"築山戸籍住民課長","answer":"これは、視覚障害あるなしに関わらず、全通知に対してＵｎｉ－Ｖｏｉｃｅをつけたいと考えています。アプリで、この音声読み取りにつきましてはそれぞれの通知文に対応しておりますので、個々の振り仮名が読み上げられるようなものになっております。","id":"exchange-043"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"最近視覚を失われた方以外は、ご要望いただくのは、せめて視覚障害者協会にこういう情報は提供してほしいと。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"何とかしていただけないでしょうか。いかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"なるべく郵送というのはお勧めしていなくて、お越しにならないでいただけるマイナポータルを利用していただくとかということを考えているところです。１回に限り、後日でも変更することは制度上可能となっておりますので、そのように考えているところです。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"マイナカードというのはつくるかつくらないか任意ということでやっていたわけですから、まずは品川区が持つと。これは要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"ゆきた委員","kind":"意見","question":"この２点、あると思います。マイナンバーもなく郵送で行う方も数多く、この点についてぜひ考慮してほしいと求めましたが、何かあればお願いしますとの意見を述べました。","respondent":"築山戸籍住民課長","answer":"ただ、期間を１年間設けておりますので、先ほどもお答えいたしましたが、一度に限り、家庭裁判所の許可なく変更も可能となっております。切手代はご負担していただくことになりますが、そういった手段もありますので、様々な方法で届け出ていただければと考えております。","id":"exchange-047"},{"speaker":"石田（し）委員","kind":"質問","question":"各地域センターとか、住民票とかを担当しているところでは駄目なのか、そこだけ。どこで届け出られるのかだけ、説明するよう求めました。","respondent":"築山戸籍住民課長","answer":"今回は戸籍の届出になりますので、そうすると本庁のみとなっております。","id":"exchange-048"}]},{"id":"topic-04","title":"品川歴史館リニューアル１周年記念企画展「昭和100年 しながわめぐり」","agenda":"品川歴史館リニューアル１周年記念企画展「昭和100年 しながわめぐり」","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ１８歳まで無料にしていただきたいと思うのですけれども、そういった検討をぜひしていただきたいと思うのですが、いかがでしょう。","respondent":"大森文化観光戦略課長","answer":"年齢でいうと１２歳以上１８歳までという形で高校生以下の無料はいかがかというようなお話ですけれども、一般の１００円をお支払いいただいて、見ていただきたいなと思っているところです。","id":"exchange-049"},{"speaker":"安藤委員","kind":"意見","question":"１８歳以下の方に見ていただくことが大事だと思いますので、子どもの権利条約では１８歳までが子どもとなっておりますので、ご検討していただけるとありがたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問","question":"品川区民に向けてということなのか、それとも品川区の魅力をアピールしたいみたいな、どういった狙いで品川駅になったのでしょうか。以上２点、お願いします。","respondent":"大森文化観光戦略課長","answer":"品川駅の利用者は１日２７万４,０００人ということも出ておりますので、何点かご提案をいただいた中で、この提案をとったという形になります。金額は、「ミュージアムめぐり」の掲載と品川駅のサイネージを合わせまして、２７万円になります。","id":"exchange-051"}]},{"id":"topic-05","title":"品川区立総合区民会館における指定管理者候補者の公募","agenda":"品川区立総合区民会館における指定管理者候補者の公募","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"３の（３）なのですけれども、そこら辺のすみ分けというのでしょうか、どうなっているのかというのをお伺いしたいと思います。","respondent":"大森文化観光戦略課長","answer":"こちらは、５０万円以下の金額のものについては指定管理者側で修繕をお願いするということで契約内容に入っているものです。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"経費の縮減を図るということを求められると、これを同時に求めているということですので、どちらを重視しているのか。安定した人が配置できるような、そこで働く人のきちんとした待遇を確保するということについてはどのように考えているのか、伺いたいと思います。","respondent":"大森文化観光戦略課長","answer":"3)人的能力とか、管理後に従業員たちの労務環境のチェックとか、そういったものも実施しています。離職が起こらないように、そういったものは選定された事業者とこちらもよく詰めて、労務環境については配慮していきたいと思っているところです。","id":"exchange-053"},{"speaker":"安藤委員","kind":"提案","question":"業者には提案書を提出させて、評価したその書類とか、どういう形で評価したのかというのはきちんと委員会に出してほしいのです。私たちは何をもって提案したのかも分からないので、ぜひ提出していただきたいのですけれども、そのように改善されるお考えはあるか尋ねました。","respondent":"大森文化観光戦略課長","answer":"報告の様式についてということなのですけれども、できるだけ透明性とか公平性といったものを重視して選定していくということがこちらのプロポーザルの主たるものだと思いますので、議会の皆様に対してもできる限り分かりやすい説明ができるように心がけてまいります。","id":"exchange-054"},{"speaker":"藤原委員","kind":"確認","question":"指定管理ということで、品川区は十何年の歴史があると思うのです。ずっと同じところが選定されていると思っているのですけれども、まず確認ですが、それでよろしいのか尋ねました。","respondent":"大森文化観光戦略課長","answer":"１回目から指定管理者に選ばれているところは、公益財団法人品川文化振興事業団となります。１回目から今回で５期目となります。","id":"exchange-055"},{"speaker":"藤原委員","kind":"意見","question":"品川区は文化振興事業団しか事業ができないのだ、一応公募としているけれども、あそこが落とすのだと。なぜならば、この辺、どう考えますかとの意見を述べました。","respondent":"大森文化観光戦略課長","answer":"課長としての考えとしては、貸館業になるので、そこで文化振興事業団しかできないものではないとは当然思っているところです。いい提案をいただいて、そこで公平に審査をして、選定ができればいいのではないかと私は思っているところです。","id":"exchange-056"},{"speaker":"藤原委員","kind":"質問","question":"ちょっと今日不思議に、すっきりしなかったもので、伺わせていただきました。そういうふうに言ってくれるように私は心から希望してこの質問を終えたいと思うのですけれども、その辺について、いかがか尋ねました。","respondent":"大森文化観光戦略課長","answer":"逆に、最低限１者なり２者なりというところは応募がないと、これまたこちらも運営上困ってしまうというところも出てくる事実があると思います。プロポーザルが５年ごとであるという、そういったことを必死に考えているものだと考えていますので、こんなのあるよという……。","id":"exchange-057"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"その評価の１つとして、働く人への労務管理のモニタリングを入れてほしいというのを、これは指定管理のモニタリングのときにそういう要望を出したら。","respondent":"大森文化観光戦略課長","answer":"労務環境に関しましては、２年目に社労士を入れた労務環境の調査が入っていると記憶しています。やはり始まってから入れるほうがよろしいのではないかなと考えていますので、そういったところも管理してまいりますし、選定していきたいと思います。","id":"exchange-058"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"２年目で入るということになって、それはすごい前進だと思って、よかったと思います。今後、選定の中に入れていただきたいと思うのですけれども、その点については現状どうなっているのか尋ねました。","respondent":"大森文化観光戦略課長","answer":"は実際にプロポーザルによる採点という２段階で評価して進めていくというところがありますので、十分間に合うところだと思いますので、そういった視点も入れていければと考えています。","id":"exchange-059"}]},{"id":"topic-06","title":"品川区立体育館における指定管理者候補者の公募","agenda":"品川区立体育館における指定管理者候補者の公募","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"（５）に自主事業というのがあるのですけれども、（２）がなくて自主事業しかなかったのですが、（２）と（５）は実際にどんなことを今やっているのかというのを改めてざっとご説明ほしいと求めました。","respondent":"守屋スポーツ推進課長","answer":"これは基本的に体育館で実施しておりますスポーツ事業であるとかレクリエーションに係る一般的な事業の運営に関することでございまして、（４）。それは（２）の体育、（５）ということで特出ししまして、分かりやすいようにして表記したです。","id":"exchange-060"},{"speaker":"安藤委員","kind":"提案","question":"後でお願いしたいのと、提案書の提出を受けて、提案書というのはどのような提案書を出してもらうという予定になっているのか。決まっているのであれば、ある程度の内容を教えてほしいと求めました。","respondent":"守屋スポーツ推進課長","answer":"かかる経費等を主な内容として、採点というか、審査をしていくです。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"今回幾つ来るのかというのはこれからなのですが、公募の仕方というのですか、どういうふうにしていく考えなのか。もう少し積極的に、それともホームページに載せて終わりということなのか、そこら辺の実態だけ教えてもらえればと思います。","respondent":"守屋スポーツ推進課長","answer":"周知につきましては、ホームページやスポーツ推進課窓口にて公募要項を配布させていただいて、応募いただくという形になります。いつ、どこの自治体で指定管理が開始されるという情報を把握されているようですので、多くのところにご応募いただければと考えているところです。","id":"exchange-062"},{"speaker":"ゆきた委員","kind":"提案","question":"2)体育館の適切な維持および管理ならびに管理に係る経費の縮減とありますが、提案の手が挙がるものも挙がらなくなってくると思うのですけれども、そういったものがあればお聞きできればと思いますとの意見を述べました。","respondent":"守屋スポーツ推進課長","answer":"各種業務における、接遇をはじめとしたサービス全体に対する利用者の満足度が高くなるような業務を行っていただきたいと考えております。会社というかスタッフとして入っていただくことで、適正な人員配置や効率的な業務を行っていただきたいというところを考えているところです。","id":"exchange-063"},{"speaker":"ゆきた委員","kind":"提案","question":"具体的に選定基準がどうあって、どこに勝負をかけていけば提案が評価されるのかという、ここについてもう一度との意見を述べました。","respondent":"守屋スポーツ推進課長","answer":"応募いただいた会社には必ず現地説明会に参加していただくことが必須となっておりますので、こういったサービスができるというのをご確認した上で、最終的に応募というか申請していただくという中身になっているです。","id":"exchange-064"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"デフリンピックの開催を議題にした話合いというのですか、そういう話合いをしたことがあるのかどうか伺いたいのと、いかがか尋ねました。","respondent":"守屋スポーツ推進課長","answer":"聴覚障害者団体の区内、協会と……。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"駅には毎日多くの方が足を運ぶわけですから、駅への掲示をお願いするということをぜひやっていただきたいのですけれども、どうでしょうか。ぜひやっていただけないか尋ねました。","respondent":"守屋スポーツ推進課長","answer":"各イベントのチラシであるとか設置物につきまして、そういった町会等に、広く知っていただくためにＰＲ活動を行ってきたところです。作成するということはすぐには難しいとは考えておりますけれども、引き続き、地域に対しての細やかなＰＲ等を進めていきたいと考えております。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"デフリンピックは１１月１５日から開催ということで、まだもう少し時間があるわけです。やはり最大限そのチャンスを活かすべきだと私は思うので、必要な予算もつけて、普及啓発を推進していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/541601?Template=document&Id=7043#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":48852,"voices":182}},{"id":"r07-20250512-7","meetingId":"r07-cm05","date":"2025年5月12日","dateIso":"2025-05-12","committee":"厚生委員会","time":"午後 １時００分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等の整備","agenda":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等の整備","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"前も公募で事業者からのこういう提案だったのか、そこのところは確認していないのですけれども、そういう条件としては変わっているのか。それから、もう公募をして、応募の見通しというのがあるのか、その点についても伺いますとの意見を述べました。","respondent":"東野福祉計画課長","answer":"１０社、そのうち２社が辞退して、８社で提案をしていただいたという形になっております。現在、何社かから問合せをいただいておりますので、応募につきましては、意思があるところが十分確保できるのではないかと考えています。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"補助も増額されて、既に問合せもあるということで、ぜひ特養ホームができる限り早くに開設できるように、取組を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"品川区立平塚橋特別養護老人ホームおよび品川区立平塚橋高齢者多世代交流支援施設（平塚橋ゆうゆうプラザ）指定管理者候補者の選定","agenda":"品川区立平塚橋特別養護老人ホームおよび品川区立平塚橋高齢者多世代交流支援施設（平塚橋ゆうゆうプラザ）指定管理者候補者の選定","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"７月に予備委員会で、８月には選定委員会ということなので、そこら辺のところも、もう決まっているのかと思うのですけれども、伺いたいと思います。待遇の部分や何かも含めて、ここのところは大丈夫なのかということについても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"サービスの見直しを行い、随時満足度の向上に努めるなど、今回公募によらずという形の選択を取らせていただいております。３つ目の、同じような形で報告書は提出させていただきまして、審議をしていただく予定となっております。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"意見","question":"長い間、人材確保を何とかしたいということで、いつも意見していただいているという思いがしているのです。だから、それはそれで本当に介護全体のことですので、人材確保ができるような、そういうところへの介護の充実というのが本当に大事だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"筒井委員","kind":"質問","question":"今回、非公募ということでやられるということですけれども、これ、今、人材不足というご答弁がありましたが、非公募の場合、当初の運営期間終了後、連続して１０年を限度とするという縛りがあると思うのですけれども、今回。","respondent":"菅野高齢者福祉課長","answer":"委員ご指摘のとおり、こちらの施設は平成２８年５月にオープンしましたので、ちょうど今回で１０年ということになります。次の５年で連続して、更新期間１５年が限度となっておりますので、次は公募という形を取らせていただく予定です。","id":"exchange-005"}]},{"id":"topic-03","title":"品川区健康危機対処計画（感染症編）策定","agenda":"品川区健康危機対処計画（感染症編）策定","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"ここのところの１８ページのところに、この体制というか、人材の体制をどうつくっていくのかというところはすごく最も大事なところなのではないかと。","respondent":"五十嵐保健予防課長","answer":"基本的には、保健師であれば、感染症の対応ができるようにすることが必要と考えております。まず、やはり感染症に慣れていただくということが一番大事かと考えていますので、着脱訓練などをしていくというのをまず考えているところです。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問","question":"今でもそのような状況だということは伺っていまして、５歳児健診だったり、新たな事業というのも加わっている部分もあるではないですか。ベテランの人も、新人の育成ということもすごく大変でというところも伺っているのですけれども、そこら辺のところはいかがか尋ねました。","respondent":"五十嵐保健予防課長","answer":"品川区がどのぐらい足りないかという評価を私がすることは難しいかと考えていますが、何区か回ってきた中では思っております。急に増やしてしまうと、増やすにしても、計画的にある程度の人数を考えながら増やしていくということになっているのかと思っているところです。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"このガイドラインを見ていましたら、この統括保健師ということに対しての品川区の考え方はどういうことなのかということも伺いたいと思います。","respondent":"高山健康推進部次長、五十嵐保健予防課長","answer":"現在、地域医療連携課の中に保健調整担当という部署を設けておりまして、その中で統括保健師を１名配置しています。いきなりいろいろなこと全ては難しい部分があるかと考えていますので、統括保健師とも連携を取りながら、今後もいろいろやっていけるようにしていきたいと思っているところです。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ただただ現場での労働強化にとなるのではなくて、そこのところは計画もつくって増やしていただきたいということも改めて要望しておきたいと思います。","respondent":"五十嵐保健予防課長","answer":"いきなりコロナのような感染症の対応とかではなく、今年度はまだ大きな訓練をするという予定までは立てていないところになっております。","id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"確認","question":"このたび品川区健康危機対処計画の策定ということで確認でお伺いしたいのですけれども、品川区内のデイサービスでコロナ感染者が職員で出ました。","respondent":"五十嵐保健予防課長","answer":"すみません。品川区の状況は存じ上げておりませんが、ほかの区でも同様のことをやっている区もありましたし、私がいた区でもそのようにしておりました。","id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"以前、委員会でこの話をしたときに、そんなことがあったのですかみたいな感じの理事者の方の答弁だったと私は記憶しているのです。要望でありますが、何か受け止めがあれば、お答えほしいと求めました。","respondent":"阿部品川区保健所長","answer":"外部人材を活用した患者対応のシステム、その結果、あるいは在宅の患者への支援などもいろいろな仕組みが整ってまいりました。いかに外部の資材も含めて活用して、そこのところはご理解をいただければと思いますし、保健所はそのように迅速に対応したいと考えているところです。","id":"exchange-011"},{"speaker":"ひがし委員","kind":"質問","question":"いろいろと報告書も作成してくださっていて、詳しく書かれていたので、その点はすごく評価をしています。１点、そういう点はこういう計画の中にどのように反映されているのか、教えてほしいと求めました。","respondent":"五十嵐保健予防課長","answer":"医療従事者等への風評被害はかなりあったと思っていますし、私も実際対応している中で感じた部分はございました。そのようなことがないようにということは必要になってくるかと考えていますし、区としても考えていかなければいけないところかと思ってあります。","id":"exchange-012"},{"speaker":"ひがし委員","kind":"質問・要望","question":"働いてくださる方のための子どもたちを預ける場所みたいなところまでできると、実際の病院はもう少し回ったのかと思っていて、難しいですか。何かあれば、お願いします。","respondent":"五十嵐保健予防課長","answer":"今後、学校や保育園などでどのように対応できるかというのも含めて考えさせていただきながら、対応したいと思います。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"意見","question":"１ページのところの背景と目的というところの２段落目のところに、「ＩＨＥＡＴの法定化等の措置が講じられた。地域の保健師などの専門職が登録をして、このＩＨＥＡＴの取組というのは品川区としてはされている部分があるのか、説明するよう求めました。","respondent":"五十嵐保健予防課長","answer":"昨年度策定しました予防計画に、ＩＨＥＡＴの対応につきましては入れさせていただいているかと思います。ただ、そういう方に対して検証させていただいたりということも必要かと考えていますので、できればやっていきたいと思っているところです。","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問","question":"ということは、そういうものはどこかにされていて、ぜひ登録をしてくださいという取組というのは既にされているのでしょうか。それであれば、どんな取組をされているのかも伺います。","respondent":"五十嵐保健予防課長","answer":"すみません。今、コロナの終わった頃に関しましては、少しそういう話は出ていたのかと思っているところです。","id":"exchange-015"}]},{"id":"topic-04","title":"令和７年度５歳児健康診査事業〈モデル実施〉","agenda":"令和７年度５歳児健康診査事業〈モデル実施〉","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"それで、なぜここあぽというアプリになったのか、その理由も伺いたいと思います。なぜここあぽになったのかと聞いたのは、５歳児健診マニュアルとかというのがあったのですけれども、その理由を伺いたいと思います。","respondent":"石橋品川保健センター所長","answer":"１２園で定員が大体３００人程度ということで予定しておりまして、まず、こういった健診を実施しますというアンケートの通知を送ります。区民の方の利便性も考えて、電子アンケートがいいということも考慮して、このここあぽというものを活用することを検討いたしました。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問","question":"そのときに、そういう形で、リスクの高い子どもに絞ってだけ集団健診を行うということになっていくということなのでしょうか。そこのところをもう１回説明するよう求めました。","respondent":"石橋品川保健センター所長","answer":"保護者のアンケートおよび心理職の集団観察というところも一つの健診と考えて実施をするということになりますので、年中クラスの１２園の全児童に対して同意を得られたご家庭には全て実施をしていくという形で、アンケートからの健診という形で位置づけをしております。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問","question":"2)番の心理職による集団観察による評価ということなのですが、心理職というのはどこのどういう方が行うのか。その心理職をどこにどういう方に委託をするのか、そして、その心理職の集団観察というのはどのように行われるのか、その点についても伺います。","respondent":"石橋品川保健センター所長","answer":"保護者への返し方というのはしっかりと事業所と連携を取って、そういったところと連携を取って、しっかりと丁寧に対応していきたいと考えております。そういったところも園と連携を取って、心理職の方にお願いをしていこうという形で、今検討を進めているところです。","id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問","question":"結構、私は、すごくいろいろと複雑な思いというのがあるのではないかと思うのです。それをどう捉えるのかということをしっかりと研修をしていかないと、あとは５歳児健診を行う対象の父母、その点はいかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"保護者や保育士に対する研修や周知というところになります。今回対象になる園の保護者に対しては、どのような手法が一番適しているかというところで検討をしているところになります。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"確認","question":"５歳児の保護者に対しても、研修だったりとか、そのようなことをしっかりと行うということで確認させていただいていいでしょうか。１１月なので、また改めて報告があるのかどうか分からないのですが、その点も伺います。","respondent":"石橋品川保健センター所長","answer":"しっかりと保育士や保護者の方にはそのことを認識していただくということは必要だと考えておりますので、ご回答はできませんが、その辺りについては。","id":"exchange-020"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"気にかかる子で終わってもらって、小学校へ上がるときには、４５分の授業で席に座っていられるようになるのかということをどうやってお考えなのか。そうすると、どういうことを求めているのですかというのがよく分からなくなってくる。","respondent":"石橋品川保健センター所長","answer":"委員ご指摘のとおり、５歳児健康診査は、発達障害を見つけるために実施をするというわけではありません。全園実施、その辺の幼稚園ですとか保育園のカラーというところもしっかり認識しながら、公立の保育園にはどう対応するとか。","id":"exchange-021"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"だけれども、今、品川区はこれだけ子育て支援をやっているわけではないですか。これは答弁できないかもしれないから要望にしておきますけれども、それのほうが私はいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２０２８年までには全ての子どもにやっていくという方向というのは取られるのか、そこの点についても伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"いやいや、２０２８年までにはと国が出しているのです。これに対してどう考えられているか、伺います。","respondent":"石橋品川保健センター所長","answer":"品川区としましては、今回モデル実施をしまして、次年度以降どう実施していくかの検討を考えていくところになります。国がいろいろ動向を示したときに、それに準じて区としてはどう動いていくかというところも、しっかりと国の動きを注視しながら検討してまいります。","id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そこら辺のところの体制整備というのはどうなっているのかということを伺いたいと思うのですけれども、９月には大原でできるので、そういうことで。","respondent":"石橋品川保健センター所長","answer":"そこについてはしっかりと丁寧に説明を、しっかりとそういった丁寧な説明を実施して、しっかりとフォローには努めてまいりたいと考えております。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"就学前の健診までの間に、そこで支援につなげるということが必要だからということで５歳児健診が必要だと言われているわけではないか尋ねました。","respondent":"石橋品川保健センター所長、阿部品川区保健所長","answer":"その辺り、しっかりと認識していくことがとても重要だとは捉えております。委員ご指摘のとおり、今後、関係各課としっかりと調整をして進めてまいりたいと考えております。それぞれが同じやり方では効果的な健診ができないということで、今回の今年度のモデル実施を通じまして、実施をしてまいりたいと考えております。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当にこれは健診をやったことによって、でも、６０人ぐらいは集団健診に行くだろうということで想定がされているわけですから、ここの中でしっかりとフォローの体制、それから支援の体制、そこのところをセットでやっていただくということで強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（秀）副委員長","kind":"提案","question":"委員の皆様からもご意見をいただいて運営をしていくという形の中で、行政の皆様にもいろいろなご提案、ご提言ができたと考えています。１年間ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/166682?Template=document&Id=7041#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":31024,"voices":85}},{"id":"r07-20250512-8","meetingId":"r07-cm05","date":"2025年5月12日","dateIso":"2025-05-12","committee":"建設委員会","time":"午後 １時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)羽田空港周辺地域における地価動向分析調査結果","agenda":"はじめに、(1)羽田空港周辺地域における地価動向分析調査結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"残念ながらというか、不動産価格への影響は確認できなかったという結果だということで、まず確認させていただきたいのですけれども。今回、これは実際この不動産の購入とか借りたりするときの重要説明事項になっているのかどうかというのも伺いたいと思います。","respondent":"高梨都市計画課長","answer":"国が公示値をデータとして、それのこの２０１６年から２０００年まで、分析・調査したということで聞いたところです。最後に、不動産を購入する、一般的にそれについては記載されてないものということで認識しています。","id":"exchange-001"},{"speaker":"のだて委員","kind":"確認","question":"その周辺環境のことも影響してくると思います。区の認識を伺いたいのと、これの見方がよく分からないというか、これは影響を与えることは確認できなかったというのが結果ですけれども。","respondent":"高梨都市計画課長","answer":"新飛行ルートの影響を区としてはどのように考えているかといった部分につきましては、今回、不安の声を受けて国が実施した調査結果は。２点目の、国から説明を受けた中では、この表の中で係数として記載されている小数点以下の数字があるかと思います。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"区としてはなぜ影響があるということで声が上がっていると思うのか、伺いたいと思います。こうした実際の影響が出ているという中で、やはり資産価値の下落の声も上がっていると思いますので、区としての考えを伺いたいと思います。","respondent":"高梨都市計画課長","answer":"今回はその声、調査を行っていただいて結果をお示しいただいたものかなと感じているところです。引き続き、そういった声につきましては、区としてしっかりと国に届けてまいりたいと考えているところです。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"区としてぜひ、実際なぜこういう声が上がるのかというのをつかんでほしいと求めました。引き続きほかの調査もやっていただくように国に求めてほしいと求めましたし、国がやらないのであればぜひ実施をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのは、この調査結果に対する区の評価を伺います。先ほども記載の結果が得られたと思うとか、不動産価格への影響は確認できなかったとする国の調査結果について、品川区はどのように見ているのか。","respondent":"高梨都市計画課長","answer":"今回、国がこの調査を実施したといったところは、一定区の意向をくんだ調査であるといったところで評価をしています。様々、そういった声につきまして、引き続き受け取った声については国に対してしっかりと届けてまいりたいと考えているところです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、区としては不動産価格の影響は確認できないという国と同じ立場なのか、それとも、いや、国とは違う立場であればどういう立場なのか。区としては影響があるともないとも言う立場にないというものなのか、その区の立場を改めてご説明ほしいと求めました。","respondent":"高梨都市計画課長","answer":"地価だけではない様々な感じ方をされる方もいらっしゃるというのもありますので、そういった声につきましては真摯に受け止めて、しっかりと国に届けてまいりたいと考えているところです。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"私もこの結果がどういうものなのか、次の質問は、では調査の方法としては合理的だと思っていらっしゃるのかという点を伺いたいと思います。","respondent":"高梨都市計画課長","answer":"国によりますと、過去も羽田新飛行ルート運用開始前も、影響を確認することはできないといった結果を得ているという説明を受けたところです。私の考えですけれども、一定その土地の価格の推移を見る上では、一定その信頼に足るものではないかと感じているところではあります。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"羽田新ルートが始まって数年たちますけれども、この運航後、そういう業界の方からはどのような声が寄せられているのか伺いたいと思います。地元の不動産業界の方々や直接のオーナーだと思うので、区としては何か声が寄せられているのか、そこを最後に伺いたいと思います。","respondent":"高梨都市計画課長","answer":"都市計画課のほうに羽田新飛行ルートに関する不動産価格の下落といった内容で、業界団体からいただいた声というのはございません。令和６年中、不動産関連、不動産価格の低下であったり補償に関する内容については０件といった内容となっております。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"業界からはないというところですけれども、それぞれが実際どのように思っていらっしゃるのか、ぜひ把握に努めてほしいと求めました。区としてもそれを細かに把握して、区としての知見といいますか、見解を持っていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"リニア中央新幹線オープンハウス型説明会の開催","agenda":"リニア中央新幹線オープンハウス型説明会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"六丁目が対象ということで、ここまでになっているのがなぜなのかというところを伺いたいのと、一般的に掘り進めるとどのくらいかかるのか。様々な問題点、ぜひ教室型説明会の実施をＪＲ東海に求めてほしいと求めましたけれども、いかがでしょう。","respondent":"大石まちづくり立体化担当課長","answer":"教室型説明会を求めるべきですけれども、その手法につきましては、当然教室型説明会を含め様々なものがあると認識しています。適切な手法を用いて区民からの不安の声や質問に対し丁寧な対応を行うよう、必要な要請を行ってまいりたいと考えているところです。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"お知らせがどうなっているのか、しっかりその対象地域にやれるようにしていただきたいと思うのですけれども、そうした関係を伺いたいと思います。共有していけるような形で、こちらの説明会はぜひ実施をしてほしいと求めましたけれども、改めて伺います。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の教室型説明会につきましては、その手法につきましては、教室型説明会も含めまして様々なものがあると認識しています。適切な手法を用いてしっかりと区民の声や質問に対して丁寧な対応を行うように、引き続き求めてまいりたいと考えているところです。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"以前１２月、区としてこの気泡の問題で原因究明をしてほしいということで申入れをしたと思うのですけれども、それで十分だと考えているのか。そこはしっかり原因究明していくことが必要なのではないかと思いますが、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の原因究明についてですが、現在ＪＲ東海は泡の状況等を引き続き注視しつつ、対応について検討していくと聞いているところです。区といたしましては引き続き区民への丁寧な説明、適切な措置を講じるようＪＲ東海に求めるなど、必要な要請を行ってまいります。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"今、気泡などの影響については観測井戸で調査をしているということで、その調査結果などを聞いているところがあれば伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"現在のところ、ＪＲ東海からは、周辺に影響を及ぼすような結果は得られていないと聞いているところです。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"影響を及ぼすような結果がないというのは、つまりどういうことでしょうか。水位の変化があるとか、気泡が出ているとか、水質が変わったとか、内容を伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"ＪＲ東海は、酸素濃度測定を行っていると聞いてあります。そちらで周辺環境に影響が認められるような結果は確認されていないです。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"もしほかにも調査しているところがあれば、伺いたいと思います。やはりこの原因究明をしっかり求めていくと、ぜひこれは強く求めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"質問の２点目の本格掘進を進めていかないようにですけれども、リニア中央新幹線はＪＲ東海が国土交通大臣から認可を受けて行っているものです。引き続き区といたしましては、必要な要請を行ってまいりたいと考えているところです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"何かパネルの説明資料はホームページで確認できるのですか。そもそもそのパネル展示の中身を事前に区が把握しているかどうかも私には分からないので、まずそこをご説明ほしいと求めました。","respondent":"大石まちづくり立体化担当課長","answer":"こちらもどのような形でご説明しているかというところを区は認識していないのですけれども、区としては把握していないところです。オープンハウス型説明会に来られた方に配布する資料はホームページに公表すると聞いてありますが、区として把握していないところです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"気泡について起きた事柄について説明するように、やはり区としてＪＲ東海に求めるべきだと思いますが、いかがでしょうか。ＪＲ東海としての立場といいますか見解をきちんと説明するように、区としてＪＲ東海に求めていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"説明するよう求めるですが、ＪＲ東海からは、区といたしましてはその説明会の内容をしっかりと把握したいと考えています。ほかの説明会でそういったご意見があったということは認識していますので、引き続き必要な要請を行ってまいりたいと考えているところです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは区として公表をＪＲ東海に求めるべきだと、数値を公表するよう求めるべきだと思いますが、いかがでしょうか。結局はリニア中央新幹線の工事が気泡の原因だったのか、地上への影響がないと言い切れるのか、そこら辺についても最後に伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"今、まずＪＲ東海のほうは５月に開催するオープンハウスの説明会で、そちらの内容をしっかりと区として注視してまいりたいと考えているところです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"調査箇所、調査結果の公表をするよう、区としてＪＲ東海に求めていただきたいと改めて思います。その追加の調査が結局どういう方法でされたのかが公表されない限り、これで区民や住民に安心を求めることはとてもできる状況ではないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"みどりの実態調査の結果","agenda":"みどりの実態調査の結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"緑被調査によってみどりが増えたというご説明ですけれども、その増加の要因をもう少し伺いたいと思います。特に樹木被覆地の７.６haのほうですけれども、先ほど公園もちょっと聞こえたのですけれども、増えた理由を伺いたいと思います。","respondent":"大友公園課長","answer":"改めてご説明しますと、区内各地の集合住宅地などの建築や公園の新設に伴い、緑化が増加したものです。開発も絡めて回答をというところなのですけれども、緑化について指導することでみどりの確保をしています。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"このまちづくり計画が、再開発を進めることで、みどりというか樹木被覆地を増やすという考えに立っていらっしゃるということですか。ご説明ほしいと求めました。","respondent":"大友公園課長","answer":"その中におきまして、緑化の指導という形のものもあります。結果としてこのまちづくり、敷地３００m2を超えるような場合については緑化指導を行っておりますので、そこにつながっているという形になるです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"意見","question":"今もう３０階建てがぼんぼん増えているわけで、一体どれだけの電力を消費して、どれだけのＣＯ２を排出しているのかと私は思います。高層化によってＣＯ２排出を増やすのではなく、高層化そのものを規制しつつ、そうした方向に向いていくことが必要だと述べたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"この緑被率を増やしていくということは、環境問題の地球温暖化などの問題でも重要なことだと思います。具体的に増やす取組を考えているのかということを伺いたいのと、今回接道部では減ってしまったということ、この原因を伺いたいと思います。","respondent":"大友公園課長","answer":"水とみどりの基本経過・行動計画の中には１２の施策があり、数多くの事業が設置されているところにあります。短縮の影響が大きいというところなのですけれど、建て替えに伴う緑化の喪失が影響していると考えているところです。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"建て替えで減ってしまっているということで、狭い敷地の建て替えが多いと思うのです。エネルギーの消費量がそこで急激に上がるということですから、そうした開発で、緑被率を増やしていくということでやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問","question":"幾つか順番に伺ってまいります。令和６年の調査ではどうだったのかというところと、民有地屋上、それぞれもし分かりましたら説明するよう求めました。","respondent":"大友公園課長","answer":"こちらのほうは最も多い木増加が、土地利用別でいくと水面というところになっておりまして、８.８％の増加となっております。こちらについては、それに伴って護岸上のみどりの日照等の影響があり、護岸上のみどりが減ったのかなというところで分析しています。","id":"exchange-025"},{"speaker":"横山委員","kind":"質問・要望","question":"昭和５０年代に都のほうで、どうしてその３０％だったのかというところ、もう少し詳細を教えていただきたいと思いました。品川区は１８位ということもあると思うのですけれども、今回の調査を通してどのように改めて考えていらっしゃるのかというところも説明するよう求めました。","respondent":"大友公園課長","answer":"東京都とともに３０％という形では、厳しいだろうということで、２５％という形で目標を認識しています。そのままでいくのかどうするのかというのは、この推進会議等の中で検討していきたいと考えているところです。","id":"exchange-026"},{"speaker":"横山委員","kind":"意見","question":"１点だけ分からなかったところがあるので、もう一度ご答弁をお願いしたいのですけれども、接道部の可能性が高い箇所と、可能性が低い箇所というのが、どういった状況なのかというそのイメージのところもお聞かせいただけますかとの意見を述べました。","respondent":"大友公園課長","answer":"生け垣や植え込みなどの接道部緑化、空き地、または塀やフェンスを取壊すことで接道部緑化整備が可能な場所というところになります。駐車場の出入り口に利用しているであったり、または建物の擁壁だったり、壁を取り壊さないと接道部ができないような場所を言っているです。","id":"exchange-027"},{"speaker":"横山委員","kind":"質問・要望","question":"これから令和８年度の中間のところに向けて、例えばマイガーデンの応募者が増えているのかなと思います。どういったことが品川区でこれからやっていけるのかということをぜひ進めていってほしいと求めましたので、その部分について一言お願いします。","respondent":"大友公園課長","answer":"現在の施策にとどまることなく、新たな施策事業というところについて、他区の事例等も踏まえ研究し、検討してまいりたいと考えています。","id":"exchange-028"},{"speaker":"つる委員","kind":"質問","question":"どのように今までやってきたのか、もしくはこれからどういう考え方でやっていくことができる可能性があるのでしょうか。日常使っている生活道路になったりする部分があろうかと思うので、その辺りの区同士での整備のあり方というのがどういう形か、それを説明するよう求めました。","respondent":"大友公園課長","answer":"こちらについて水とみどり、水も含めてなのですけれども、近隣自治体との方針というものを図りながら、ネットワーク整備方針を検討していくです。大田区等の軸の連携であったり、隣接区との連携など、各連携を図っているというところになってあります。","id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"計画とか考え方とかは当然あると。そういったところのみどりを考えていくときに、こういう計画に基づいて実施された具体的な場所というのはあるのか尋ねました。","respondent":"大友公園課長","answer":"品川区内にそこが入ってきていることがあるのですけれども、そこの軸の近隣というところでは、しながわ花海道というところですね。整備等々もこのみどりの軸の連携の一つになるのかなと計画しています。","id":"exchange-030"}]},{"id":"topic-04","title":"五反田～天王洲、舟旅通勤","agenda":"五反田～天王洲、舟旅通勤","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点伺いたいのは、行くのは勝手だけれども会社としてはこの道の分しか出しませんというような、ほとんどそうだろうなと思うのです。でもそれを区に聞いてもどう答えるのだろうというのがあるのですけれども、通勤で認められるのですかとしか聞きようがないのですね。","respondent":"関根河川下水道課長","answer":"そういった使い方等も考えられるのではないかと考えているところです。水辺のにぎわい創出につきましては積極的に取り組んでいくこととしておりますので、そのような形での利用の方法もあるのかなと認識しています。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"そうではないのですか。伺います。","respondent":"関根河川下水道課長","answer":"今ご質問いただきました点で、本当に通勤だけなのかというところですけれども、こちらは令和４年度に社会実験として実施をしております。特段再開発と絡めたものであるという認識はしてございません。","id":"exchange-032"},{"speaker":"中塚委員","kind":"意見","question":"だから断定的にはまだ言えないけれども、そういう動きとこういう運航が連動し得るものだと。よほどそちらのほうが面白いのではないかと思うけれども、やはり通勤だと言い切るところがうさんくさいなと思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"これは屋根がないということで、あと、実際今見込んでいる利用量というか人数というのはどのくらいなのか伺いたいと思います。五反田と天王洲を行き来する人ということになると思うのですけれども、これが実際に成り立つのか、そこをお伺いしたいと思います。","respondent":"関根河川下水道課長","answer":"実際にどのぐらいの利用を見込んでいるのかという点ですが、区としてどの程度の利用を見込んでいるかというものは持ち合わせてございません。３点目、区としても水辺利活用推進計画に基づきまして、区としてできることは取り組んでいくということで考えてあります。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"区としても船着場の整備とかはしているわけですから、関わっているということはあると思いますので、見ていってほしいと求めました。それと、私も最後に、これを再開発につなげないようにということは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"横山委員","kind":"確認","question":"私のほうからは数点確認したいのですけれども、１点、具体的に教えていただけたらと考えています。都の事業ですので、都としてどのようなことを行う予定なのかというところを区としてどう把握しているのかということも併せて説明するよう求めました。","respondent":"関根河川下水道課長","answer":"まず１点、いわゆる現地のところにそうした舟運をはじめとするそうした案内のポスターなどを掲示できるスペースなどを設置済の状況です。申し訳ありません、事業者のほうではそういった公共交通機関へのポスターの設置等も検討していきたいという話は聞いているところです。","id":"exchange-036"},{"speaker":"横山委員","kind":"質問","question":"こちらは５月１４日から運航開始ということなのですけれども、終了の予定はいつ頃になっているのでしょうか。現在の５月１４日からの形でそういった自転車シェアサイクルであったりとか、通勤ということなので、その辺りの区としてのご見解を説明するよう求めました。","respondent":"関根河川下水道課長","answer":"東京都の補助制度を利用して事業者のほうで開始するものでございまして、運航開始が５月１４日という情報をいただいているところです。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"以前質問させていただいたのですけれども、都のほうと連携していただきながらぜひ進めていただきたいと要望をさせてほしいと求めました。他課とも連携していただきながら、様々に足を延ばしたり、どうぞ。","respondent":"関根河川下水道課長、大友公園課長","answer":"今、東京都と連携してこの舟運事業を支援していくというのが区の取組としていますので、都と情報共有して進めてまいりたいと考えています。先ほど横山委員から説明を求められた件で、みどりの面積について確認が取れましたので、ご説明をさせていただきたいと思います。","id":"exchange-038"},{"speaker":"つる委員","kind":"意見","question":"年間何組とかという点はあるかもしれませんけれども、そういう可能性という部分ではどうなのか。ジールだけではないと思うのですが、そこの辺り、一番肝としては品川区にとっての経済効果がこの航路でどれだけあるのかなというとの意見を述べました。","respondent":"関根河川下水道課長","answer":"そうした中で、経済的な効果は多少あるのかなと認識しています。区としても水辺のにぎわい創出に向けて連携できるものがあれば、そうした話を地域も含めて進めていきたいと考えています。","id":"exchange-039"},{"speaker":"つる委員","kind":"意見","question":"今年度の当初予算で、東京湾大花火大会を復活させた場合どうなるかという調査委託費が確か計上されているのです。その動きがどうなのかなというのが少し気になるのですけれども、これは別にあえてではなく、もし何かあればご答弁ほしいと求めました。","respondent":"関根河川下水道課長","answer":"いろいろとありがとうあります。ソフトの充実というのが非常に重要な観点かなと考えていますので、取組の検討ですとか地域の取組支援等を進めてまいりたいと考えています。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/570689?Template=document&Id=7039#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":35841,"voices":96}},{"id":"r07-20250512-9","meetingId":"r07-cm05","date":"2025年5月12日","dateIso":"2025-05-12","committee":"文教委員会","time":"午後 １時００分～午後 ４時１９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"令和７年度学級編制","agenda":"令和７年度学級編制","exchanges":[{"speaker":"西村委員","kind":"意見","question":"人数も含めてある程度予測をつけていただいていたと思うのですけれども、教室が足りなくなっている学校もあると、様々聞いております。そこを活用するなど、学校の中でそういった措置が必要になっている事例があれば、お聞かせほしいと求めました。","respondent":"石井学務課長","answer":"フリースペースの部分を教室に変更したりとか、学級数の増が見込まれるところにつきましては、工事費の改修費用などを予算化した上で対応に当たっているです。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"以前の委員会のご報告の中に、城南小と城南第二の学区域の変更というのがありましたが、そのことは、今回はここには反映されていないのか、変更後のことも反映されての今回の結果なのか、そこを確認させてほしいと求めました。","respondent":"石井学務課長","answer":"学区域の変更につきましては、令和８年４月１日入学からとなっております。今回については、令和７年４月１日入学者までですので、現状、反映されていない状況の一覧となっています。","id":"exchange-002"},{"speaker":"田中委員","kind":"意見","question":"分かりました。現状においての対応というのは、ぜひ柔軟にご対応いただけるように、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"意見","question":"その点で、特に浜川小学校などは、５クラスでもういっぱいかと。現時点のことで結構ですので、どのようにお考えになっているかというのを、まずお願いしますとの意見を述べました。","respondent":"石井学務課長","answer":"最新の人口推計ですと、ピークが令和１１年ぐらいまで伸びるような形になってあります。そういった工事をするときの設計時のプロポーザルも、今後の就学人口の増に関しては、適切に対応してまいりたいと考えているところです。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問","question":"１クラスの標準、文科省の標準は８人と伺っているのですが、２４人になっていないけれども３クラスにしていると。柔軟に対応できるということは、よろしいかと思うのですけれども、その辺の対応はどのようにされているのか尋ねました。","respondent":"石井学務課長","answer":"こういった中で就学増が見込まれるところについては、教室の確保については、学校と相談しながら適切に対応していきたいと考えているところです。特別支援学級については、柔軟な対応ということではなく、通常の恒例どおりの対応という形でやってあります。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そのほかの、特別支援教室とか特別支援学級に影響がないようにしていただきたいという、これは要望です。１クラス増やして、１クラスの人数を減らして、その辺の柔軟な対応はどのようにしているのかというところを説明するよう求めました。","respondent":"石井学務課長","answer":"学校から、例えばより丁寧な対応をしたいということで、一定程度柔軟な要望があった場合については、もちろんこれは加配教員の関係も出てくると思いますので、その辺り、要望を受けつつも、法令にのっとって適切に対応できるような形で進めていきたいと考えております。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぎりぎり３２だから４クラスとかではなくて、置いておいて、学校の要望に応えてほしいと求めました。最後にそれだけ。","respondent":"石井学務課長","answer":"特別支援学級などのお子さんに対してきめ細やかな教育ができるような形で、東京都とも適宜相談していきながらになってくるとは思いますけれども、適切な対応を進められるようにしていきたいと考えております。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"確認","question":"それとも品川区のいわゆる民間の建築確認機関とか、そういうところに集まってくるものを聞いて、人口動向というのを見定めているのか。なかなか見極めが難しい問題だと思うのですけれども、どういったところから情報を取っていらっしゃるのか教えてほしいと求めました。","respondent":"石井学務課長","answer":"大型マンションの建築の予定を照会したりとか、そういったところで一定程度、需要についても調査をするようにしております。コンサル会社に調査委託している部分もありますので、それらの情報を総合した上で、人口動向の把握をしています。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"子育て世代がこれから入ってくるという中で、こうしたところの大井町周辺の学校の人口動向というのも押さえていらっしゃるのかということが一つ。大体それは想定内に収まっているのか、想定外のことも起こっているのか、その辺りを最後に説明するよう求めました。","respondent":"石井学務課長","answer":"私自身が今すぐにぱっと、当然そういった大規模な開発が行われる際の情報というのは、これからきちんと確認していくような形です。当時の想定を超えるような形で入ってきているということで、想定外もあり得るということは、常に肝に銘じておかなければならないと考えております。","id":"exchange-009"},{"speaker":"山本副委員長","kind":"質問・要望","question":"有効な話合いが行われて、予定の教室数を超えて児童が増えて、逼迫するようなことがない状況が一つずつ確認できているのかどうかというところ。ほかの委員からも質問ありましたけれども、もしくはできるのかという、その辺りのところを教えてほしいと求めました。","respondent":"石井学務課長","answer":"基本的には、教室数が足りなくなるから開発規模を下げてくれとか、そこまで強力な形の要請というのはなかなか難しいのではないかと考えております。それがどこまで再開発組合で取り入れられるかどうかはさておいても、意見の申し述べは可能なのではないかと考えております。","id":"exchange-010"},{"speaker":"山本副委員長","kind":"質問・要望","question":"その中で、一つお伺いしたい事例がございまして、日野学園の事例です。これまでの経緯とか完成後の見通しなどが、それでも大丈夫だとかという推計が既にあるようでしたら教えていただきたいのですが、いかがか尋ねました。","respondent":"石井学務課長","answer":"今の日野学園個別事例については、申し訳ございません、今、手元に資料がないので、この場でご説明することはできないのですけれども、ただ、今そういった声があるということについては受け止めた上で、そういった不安が生じないように対応してまいりたいと考えております。","id":"exchange-011"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ご確認いただきたいです。こういった形でマンションが建ってくると、周辺住民や保護者の方々には、大丈夫だというところの分かりやすい説明をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"別の切り口からお伺いしたいのですが、先日、どこと言うとあれなのですけれども、小学校の卒業式に行きました。義務教育学校に入ってほしいと、こういう数字の傾向を見てどのようにお感じになっていらっしゃるのかというところをお伺いしたいと思います。","respondent":"石井学務課長","answer":"より特色ある学校づくりに努めていくような形で、もちろん、それぞれ親御さんの選択もあります。そういう意味では、きちんと魅力があって選ばれる品川区立の学校になるため、こういったことを含めて取組を強化していきたいと考えているところです。","id":"exchange-013"},{"speaker":"山本副委員長","kind":"質問","question":"学校選択の中で、選択して希望が通らなかった児童・生徒はどの程度いるのかということと、理由はどのようなものかということを教えてください。これまでの傾向と、過去と比較した今年度の特徴があれば、併せて説明するよう求めました。","respondent":"石井学務課長","answer":"特に例えば兄弟枠で、本当だったら入れるところを入れなかったことが、令和７年度は１名出てきております。令和６年度は兄弟枠で入学できない方はいらっしゃらなかったのですけれども、令和７年度は１校、そういったところが発生しています。","id":"exchange-014"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ほかに、全体的な数字の割合とか、把握できるものがあれば教えていただきたいのですけれども、いかがでしょうか。もしくは、ある学校ではこうだという形でのご説明がもしいただけるようだったら、お願いしてもよろしいか尋ねました。","respondent":"石井学務課長","answer":"令和３年度ですと、令和６年度に関しては８０％、令和７年度に関しては８６.３％が入学可能となっているところです。大体６０％台で推移しているのですけれども、令和７年度に関しては６８.１％という形で、ほぼ似通った数字で推移しています。","id":"exchange-015"},{"speaker":"山本副委員長","kind":"意見","question":"希望した学校に入れる割合が上がってきているというのは、とてもよいことだと考えています。やむを得ないと思うのですが、どのようにできるかというのはありますけれども、できるだけかなえていただくようになればいいなと期待しておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"}]},{"id":"topic-02","title":"区立学校におけるいじめの重大事態の調査結果","agenda":"区立学校におけるいじめの重大事態の調査結果","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"まとめて伺いますが、２つの事案で、保護者の方は２名です。その辺り、なぜＶという表記なのか、まず全体的なところを説明するよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"そうした趣旨を保護者に説明いたしまして、公表を希望というか、公表について許諾をいただいたという流れです。今回３点について確認漏れがあったということですので、確認の際には、今後はより一層確認をしていきたいと考えております。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"提案","question":"先ほどご説明ありましたけれども、２つ目の事案の１５ページの発達支持的生徒指導、これも本委員会における答申において複数回提案していると。複数回、何度も提案を受けているということですが、そこについてのお考えを伺いたいと思いますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"は前向き行動支援という言葉で伝えているのですが、子どもたちのよい行動を増やして、悪い行動を減らしていきましょうと。今後この成果が表れるように、我々もしっかりと学校の取組を注視して見ていきたい、また支援していきたいと考えております。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"確認","question":"学校において積極的に状況の確認・整理をし、保護者らの不安等を除去することが必要と、最後の結論のところにもあるのです。先ほどもありましたけれども、私にはそのように読めてしまったので、そこについての見解を最後に伺って、終わりにしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"なおかつ児童・生徒に寄り添った対応をしていくということが求められるわけですけれども、考えられなかったりということが出てきます。学校がしっかり対応できるような取組、最終的には教育委員会が責任を持って対応していくということが求められていると捉えております。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問","question":"最後と言いましたが、その前に２つお聞きすると言ったのが、１つ質問し忘れてしまったので、それも伺います。今のお話を伺っていると、その報告書自体が事実関係と学校の判断の区別ができていない、そのこともしっかり是正すべきであるという提言もありました。","respondent":"丸谷教育総合支援センター長","answer":"本事案について背景を探ると、部活動の中の人間関係というものも、学校へのヒアリング等で分かってきたところではあるのですけれども、本件いじめとして認知をしたものと直接的な関係はないということで、ここには全体を通しての網羅的な記載はされていないです。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問","question":"圧倒的に被害生徒の立場に立って教育委員会が対応すべきだと思うので、そういう意味でも、こういう公表はすべきだと思うのです。そういう意味でも、僕はここも訂正すべきだと思うのですが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"この報告書を執筆しているのが弁護士という立場の方で、ある意味、専門的な形での表記もなされているかと思います。今後、答申として上がってくるものについては、検討いただくように申入れをしたいと考えます。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ申入れをしてほしいと求めました。専門的表現だから致し方ないと思ったのか、そこはもっと丁寧な表現で書くべきではないかと思ったのか、その受け止めはどうだったのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"こうした細かな表現についてまでは十分に見切れていなかったかなということが、今ご指摘をいただきまして分かりました。その点も含めて今後、受け取る際には、しっかりと被害側に寄り添った表記・表現になっているかというところも、併せて確認していきたいと思います。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"結束して対応されているわけですから、そのような見られ方をしないような表現に、ぜひしてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"西村委員","kind":"質問・要望","question":"今申し上げた第三者による介入というところと、私はつながってくるかなと思っているのですが、１点伺いたいのが教員の負担について。","respondent":"丸谷教育総合支援センター長","answer":"事案番号０５－０９の事案についてですけれども、担任教諭をしていた教員が、学年主任とも検討しながら対応していったというケースです。","id":"exchange-024"},{"speaker":"西村委員","kind":"質問・要望","question":"校内委員会ですとか、先生ご自身が何とか自分でしなければと思い過ぎないように、組織で動いていただきたいというのは切にお願いしたいと思います。教育委員会としてのお考えがあれば、この間の立川市の事件を受けて、何か動いたことがあればお知らせほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"何か子ども同士でトラブルがあったときの対応について、そういったことを事が起こる前にしっかり説明することが大切であると、その点。きっかけとなったことがいじめの対応だということが、事故に至らないように、研修等も含めて働きかけをしていきたいと考えております。","id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"確認","question":"疑いの段階から事実確認をという点と、対応チームをつくったほうがという２点に関しては、かねがね言われていたことでした。改めて出てきたのかな、１１月に区教育委員会が保護者からの相談で把握したという部分が１個目の事例であったのですけれども、その点をお尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"いじめの疑いの段階からしっかり確認して対応していく点、これは早期発見、早期対応につながるものだと考えております。今回は、恐らく学校行事の対応も、適切に学校はやっていたと思っていたので、ここまで発展するとは思っていなかったと思います。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これを一つの経験として、恐らく検討されていると思うのですけれども、ぜひそういった形でやってほしいと求めました。これは要望で、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"せらく委員","kind":"質問・要望","question":"ガイドラインに関係者の意向確認というところがありました。これまで非公表だった事案で、そのほかのところで公表の許可が得られなかった、そのような状況となったことはありますか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"そういった意味で、後押しといいますか、趣旨をきちんと説明して、確認を取っているです。今後、こうした公表について意向の確認をしっかり取りながら、被害児童・生徒に寄り添った対応ができるように努めてまいりたいと思います。","id":"exchange-028"},{"speaker":"せらく委員","kind":"質問・要望","question":"先ほどあくつ委員がこの内容を皆さんに見ていただきたい、内容に納得できないから公表したくないのかなと考えたところでした。今後とも被害児童・生徒と保護者との信頼関係というところがすごく重要だと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"山本副委員長","kind":"質問・要望","question":"せらく委員のご質問にもありましたが、被害生徒・児童の方々に納得度の確認、調査に対する満足度の確認というのはやっているのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"同じように学校や区教育委員会の対応、それから再発防止に向けた提言について、いただいているところです。説明をしていく中で、保護者に説明するのは委員長が自ら行っているのですけれども、丁寧に説明をして。","id":"exchange-030"},{"speaker":"山本副委員長","kind":"質問・要望","question":"一つ一つ確認していかなければいけないというところでの時間がかかること、素早く変えていくような、いじめの事案の解決時間に対する思いです。これは要望です。","respondent":"丸谷教育総合支援センター長","answer":"そうした保護者の不安がないような形で説明もしていきたいと考えます。こうした国が示しているものに沿って対応するということが、そういったご意見もしっかり受け止めながら、対応は進めていきたいと思います。","id":"exchange-031"},{"speaker":"山本副委員長","kind":"質問・要望","question":"公表された２事案の中にも出てきていますけれども、そういった一つ一つのところを丁寧にやっていただきたいというのは、改めてご要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-03","title":"朝の児童の居場所確保事業試行実施","agenda":"朝の児童の居場所確保事業試行実施","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"まず、ここに書いてある４番目の保護者への周知・利用登録というところなのですが、もうこの利用登録は終わったのでしょうかというところが１点です。適切に周知する必要があると思うのですが、それはどのような仕組みを考えられているのか説明するよう求めました。","respondent":"三輪子ども育成課長","answer":"現時点で予定していますのが、源氏前小学校が図書室、戸越小学校が多目的室、豊葉の杜学園が和室を予定しています。最後に、台風等により受入れができないということに関しましては、事前に分かり次第、保護者に対してメール等で周知を予定しています。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今お伺いすると、たしか以前体育館だと伺っていたような気がするのですが、そもそもそういう考えだったのかというところも含めて説明するよう求めました。","respondent":"三輪子ども育成課長","answer":"３点のご質問にお答えいたします。詳細については今検討中ですので、よろしくお願いいたします。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問","question":"試行開始を予定という言い回しになっているのですが、端的に言うと、朝の居場所に来られる子どもたちにアンケート調査をするということなのか尋ねました。","respondent":"三輪子ども育成課長","answer":"需要調査につきましては、各学校、試行３校において、保護者向けに朝食支援を希望するかという調査をしたいと考えています。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"ということは、これは朝の児童の居場所を使っている子どもやそのご家庭にということではなくて、今回試行する３校全体で需要を調査するという認識でいいか尋ねました。","respondent":"三輪子ども育成課長","answer":"委員おっしゃるとおり、今使っていない方についても、朝食支援が始まった段階で使うということもあり得るかなと思いますので、幅広の調査をする必要があるかなと考えております。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"最初の「朝の小１の壁」というのは、朝の居場所対策をすることの解決にどう結びつくか、改めてお伺いしたいと思います。目的の「小１の壁」との関係性で、もう一回改めてご説明をいただきたいのですが、お願いします。","respondent":"三輪子ども育成課長","answer":"小学校１年生の保護者様から多くいただいているところもありますので、そういったことを踏まえて、需要はあるのかなと考えています。実際、校門前に立たれてしまっていると、安全・安心の確保の観点から、少し課題があるかなというところがありますので、本事業を実施するです。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"まずは小学校１年生を含むそういう子どもの居場所の確保ということですが、義務教育学校も対象になっています。中学校へのこういう対応を今後考えていらっしゃるのかどうかをお伺いしたいと思います。","respondent":"三輪子ども育成課長","answer":"現段階で中学校というところまでは、検討しているところではございません。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"特に小学校１年生の場合は、学習をしたりというのは、まだ習慣づいていない子どもの段階だと思います。対応のメニューをもう少し増やしていくことも、今後必要になってくるかと思われるのですが、その辺の見通しはいかがか尋ねました。","respondent":"三輪子ども育成課長","answer":"実施の趣旨として、校門前に集まってしまっている子どもたちを安全な場所で過ごせるようにするというのがファーストステップかなと考えています。試行の中で検証していくことになると思うのですが、どこまでできるかということも含めて検討していくのかなと考えています。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"最初の確認いたしました「小１の壁」、保育園には親御さんがお送りして、預かっていた子どもが、小学生になった瞬間に自ら学校に行くわけです。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"西村委員","kind":"質問","question":"前もご説明いただいていたら、繰り返して申し訳ないのですが、見守り員の委託先がシルバー人材センターなのか、どこなのかを改めて伺いたいのと、あと、すまいるスクールの職員もここにフォローで入ってくるのか、どれぐらい入ってこられるのか、改めて伺えればと思います。","respondent":"三輪子ども育成課長","answer":"試行３校につきましては、すまいるの職員に協力を直接いただくところまでは、今求めてはいません。ただ、本課のほうに朝の居場所の担当で新しく配置されている職員がおりますので、何か緊急事態等あれば対応できるような体制を取っているです。","id":"exchange-041"},{"speaker":"西村委員","kind":"質問・要望","question":"これは需要だけではなくて、その際に実態調査も行っていただきたいと要望させていただきたいです。提供するものの栄養価なども考えながら取り組む必要があると思うのですが、その辺りのお考えを伺えればと思います。","respondent":"三輪子ども育成課長","answer":"これから考えていくですので、我々としても把握した上で実施する必要があるかなと考えておりますので、しっかり対応してまいりたいと考えております。","id":"exchange-042"},{"speaker":"西村委員","kind":"質問・要望","question":"すみません、もう１点だけ要望させていただきたいのですが、ご飯はおいしいのだと分からせてあげられるような機会にしていただきたいというのが１点。もう１点は、そういった教育を同時にしていくことも必要ではないかと思いますので、お考えがあれば説明するよう求めました。","respondent":"三輪子ども育成課長","answer":"まず朝食は、楽しくないからということであれば、そういう場になるような形で支援していくというところも考えられるのかなと考えています。教育の分野のところまでのお話は、すみません、私のほうからはお答えすることが難しいです。","id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"質問","question":"さらに３掛ける３０校ではないですけれども、１００人以上必要になってくるので、その点について見通しみたいなのはいかがでしょうかというのが一つ。ただ、お子さんたちが７時半に来るとは限らない部分もあるので、どのような形で事業計画を立てているのかお尋ねします。","respondent":"三輪子ども育成課長","answer":"今回の集まり具合を見ると、どういった方策があるかというのは、今まさに検討を進めていかなければいけないというところの課題になっております。","id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この３校の試行で課題が見えてくると思いますので、委託する方の確保も含めて、早いうちに何とか対応してほしいと求めました。閉まっていて、見守り員の方が開けるということで安全が確保されるということで、ありがとうあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"提案","question":"この事業を一般質問等でご紹介するときに、小１のときにはまず保護者が最初、今回はそういう縛りはかけないということでいいのでしょうか。いきなり１人で小学校１年生が、自分でその時間に来てくださいということなのかどうか、その３点を説明するよう求めました。","respondent":"三輪子ども育成課長","answer":"２点目のご質問が、家で食べられないお子様の対応については、いろいろなご意見は恐らくあるかと考えています。それ以前の登校になってしまう方につきましては、保護者同伴でお願いしたいとご案内をさせていただいているです。","id":"exchange-046"},{"speaker":"山本副委員長","kind":"質問・要望","question":"これまでもどうするのですかというお話をしていたのですけれども、今回７時半に、区の方が雇われる誘導員の方が旗当番とかで見てくださる。","respondent":"三輪子ども育成課長","answer":"１点目につきましては、誘導員のところはご認識のとおりです。若干、現段階では、アレルギー食までの対応というのは難しいというところをご了承いただいた上での申込みをしていただいているという状況です。","id":"exchange-047"},{"speaker":"山本副委員長","kind":"質問・要望","question":"そういったことも試行の中で検証いただきながら、万全な体制となるように進めてほしいと求めました。現場や保護者の方々や子どもたちの声を丁寧に拾って、安心して利用できる体制づくりとなることを期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"確認","question":"これは所管には確認させていただきましたけれども、大井町周辺はどうしても通勤のハブ駅で、突発的に募集をしたということでご説明を受けました。どのようにお考えになっているのか、これから誘致はやらないという考え方なのか、そこだけ説明するよう求めました。","respondent":"芝野保育入園調整課長","answer":"ご質問の答えは、私立保育園でよろしいですか。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"どうやらそれはないということで、そこは引き続き、努力をしていただきたいというところです。保護者の方からもいろいろ言われている中で、そういったところへのお考えを最後に伺って、おしまいにしたいと思います。","respondent":"染谷保育施設運営課長","answer":"令和６年の４月にお示しをしております品川区内保育園等あり方基本方針の中で、保育の質の向上と考えておりまして、そういったものについて定めてまいりたいと考えているところです。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"区内全域で４２７人で、その不承諾の子どもの行き場はどうなっているのかというところの確認なのですが、待機児童と不承諾数との関係性です。これは、入れるけれども何らかの要因があって入園できないという、その辺の状況をお聞かせいただきたいです。","respondent":"芝野保育入園調整課長","answer":"回答が前後しますが、細かく言ってしまいますと、これは待機児童に当たらないというものです。トータルで言えば、お困りになっている状態というのは、区内ではないと認識しております。","id":"exchange-051"}]},{"id":"topic-04","title":"の２のその他","agenda":"の２のその他","exchanges":[{"speaker":"高橋（し）委員","kind":"質問・要望","question":"卒業アルバムについてなのですけれども、私費会計でやられていると思うのです。どうやって卒業アルバムの業者を選定して、学校になるのだと思うのですが、契約しているものかを確認させていただきたいです。","respondent":"舩木庶務課長","answer":"今回の事例は私費であれどもあくまでも学校の名前で契約をしているというものなのですが、場合によってはＰＴＡの名前で契約していると。この対応に当たっていただいていると思いますけれども、現時点で情報を持ち合わせてはおりませんので、答弁は省略します。","id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"質問","question":"チェックできるかどうかは置いておいて、だからきちんとしていますと言われて、はいそうですかと言うわけにもいかない。なかなか難しいので、その辺り、今後どのようにしていったらいいのか、現時点でのお考えを伺います。","respondent":"舩木庶務課長","answer":"こういう事象が発生しましたということで共有しておりますし、他に同様の事例がないかということについても調査を既に済ませているところです。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/178682?Template=document&Id=7037#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":59131,"voices":152}},{"id":"r07-20250512-5","meetingId":"r07-cm05","date":"2025年5月12日","dateIso":"2025-05-12","committee":"総務委員会","time":"午後 １時００分～午後 ３時０９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"キッチンカー活用事業の実施","agenda":"キッチンカー活用事業の実施","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"災害時協力体制と言われますけど、本当にこのキッチンカー、物が入ってこないのに有効利用というのは可能なのですか。必ず食品がここから仕入れられる、油もここから持ってこられるという体制ができているということなのか尋ねました。","respondent":"佐藤経理課長","answer":"災害時の対応のところでのご質問かと思います。そういった実績も踏まえて協力体制が組めるのではないかというところで、今後協議しながら進めていくということになろうかと思います。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問・要望","question":"水の入手、それから、ガソリンの入手も一時的にほとんど止まってしまう状況だと思います。やはり食料品などをどこから仕入れるのだ、区民が安心してキッチンカーに頼れるような仕組みづくりをしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"それから、その取られた分を金額に上乗せしてしまうと高いものになってしまうという見方もあるのですけれども、それはいかがか尋ねました。","respondent":"佐藤経理課長","answer":"こういった事業を次年度以降やるのであればぜひ参加したいという前向きな回答がいただけましたので、今回の事業の実施につながったというところです。試行実施のときはホームページに出して、職員が対応したのですが、なかなか難しいというのは感じたところです。","id":"exchange-003"},{"speaker":"西本委員","kind":"意見","question":"せっかく庁舎に来ていただいて、こういうものがあって、すぐ食べられるというような流れはつくってあげてもいいのかなと。これは意見なので、参考にしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"松本委員","kind":"提案","question":"災害時のことも検討されてこちらの業者を選ばれているのではないかと思いますが、話合いの中で出ているのかというところを伺えればと思います。その辺り今、話合いの中でどういうことになっているのか、お伺いできればと思いますとの意見を述べました。","respondent":"佐藤経理課長","answer":"先ほども紹介しましたけれども、食に関する支援を積極的に行うという面での提案をいただいておりまして、協議していると聞いております。非常に多く抱えていると聞いておりますので、すぐには枯渇するようなことはないのかなというのは認識しております。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"このキッチンカーが試行実施されていたときというのは、仲介業者は入っていなかったということでいいのでしょうか。なぜ、仲介業者を入れるようになったのかを伺いたいのと、関係ないというかどういうタッチの仕方になるのか伺いたいと思います。","respondent":"佐藤経理課長","answer":"試行実施の際にどういった体制だったかということですけれども、先ほど少し回答いたしましたが、仲介事業者を使うのは今回が初めてということです。それによって賠償するといった体制も説明を受けておりますので、そういった点でも優れていると考えております。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。その中でも事故やトラブルということになってくると、そういった場合の区の対応というのは何かすることになるのか、伺いたいと思います。","respondent":"佐藤経理課長","answer":"食中毒等が起きた場合の区の対応ということですけれども、区の事業として行うところですので、区のほうで対応するというのが大前提ではあります。","id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"例えば皆さん１２時に、当たり前ですけれど、たくさん来るではないですか。３０分前に上げる、１５分前に上げる、何かそういうのはあるのかないのか説明するよう求めました。","respondent":"佐藤経理課長","answer":"昨年、来たときに私も買いましたけれども、やはり並ぶというところが一つあろうかなとは思います。なかなか難しい点ではあると思いますが、ノウハウの中で対応いただければなというので、引き続き伝えていきたいと思います。","id":"exchange-008"},{"speaker":"大倉委員","kind":"質問","question":"１点だけ、これを１年間やった中で、効果測定というのはどのようにしていくのでしょうか。意見を聞くとか、この効果がどうだったかというのは、どうやっていくのか教えてほしいと求めました。","respondent":"佐藤経理課長","answer":"その中でも、振り返りといいますか、どういったデータが出せるかというところも提案いただいております。区に提供いただけると聞いておりますので、そういったものを活用しながら、事業の効果について判定していきたいと考えております。","id":"exchange-009"},{"speaker":"大倉委員","kind":"意見","question":"分かりました。どういったデータが出せるのか、そういったこともできるのかなと思いますので、いろいろ考えてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"新妻副委員長","kind":"提案","question":"そこら辺の提案として、そこは広げてもらいたいというような、そういう要請をされるお考えがあるのかというところです。モスバーガーが全国で１台しかないキッチンカーを出動していただいた事例があったかと思うのですが、やっていますよ、併せてお聞きしたいと思いますとの意見を述べました。","respondent":"佐藤経理課長","answer":"２点目に、試行実施のときの、職員の利用についてはアンケートを取りましたけれども一般の区民の方はどうだったかというところです。そうした中で何ができるかできないかというところはありますけれども、ご意見としては、伝えていきたいと考えております。","id":"exchange-011"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"やり方というのはお任せをするといいますか、そこは投げかけるというような仕組みが今回の取組ということでの認識でよろしいですかね。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"では２階の食堂は閉鎖、見直しをする考えも出てくるのかなと思いますが、その辺何か考えがあるのでしょうか。集約するとか、それはそれとしてやっていくとか。","respondent":"宮尾人事課長","answer":"職員の食堂ということで私から答弁をします。キッチンカーの試行実施ということで、今回も、やるに当たってはその辺の動向はしっかり見ていきたいなと考えています。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ、当面は並列でやっていただきたいなと思います。いろいろ状況を見ながらということなので、それを注視しながら、でもサービス低下にならないように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"令和７年度定額減税しきれないと見込まれる方への給付金（不足額給付）の支給","agenda":"令和７年度定額減税しきれないと見込まれる方への給付金（不足額給付）の支給","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"たった１度の減税ということ、それが焼け石に水であったということが、地方自治体の職員の皆さんの様々な事務が増えて本当に大変だったろうなと。Ｂのところで推計約３,０００人ということで、下のＢのほうは一律４万円となっているのですけれど、分かる状況か尋ねました。","respondent":"宮澤税務課長","answer":"６月２日を基準日として算出して金額等を出すところですが、予算上、給付金に関しましては８億７,０００万円余を予算としております。特にＡの方に該当する、不足が生じた方というのは扶養人数等で控除額等が変わりますので、算出してみてその金額が出てくるです。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"引き続きの減税策、私たちは消費税減税が一番だと思っていますけれども、区としてもぜひ求めていただきたいなと思っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"それから、合計所得金額１,８０５万円以下の方ということなのですけれど、この仕組みをもう少し教えてもらえないでしょうか。どういう方々が対象で、どういう方々に支払われるのか、なぜそういうことが起きるのかということを説明するよう求めました。","respondent":"宮澤税務課長","answer":"仕組みの部分を説明しますと、昨年度定額減税が実施されまして、所得税と住民税、合わせて４万円になります。合計所得１,８０５万円以下というのは、例えば、給与収入２,０００万円を超える方は定額減税の対象外という形になっているところです。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"令和６年度の年末調整などの中での算出した形で、逆に多くなってしまった場合は引かれるのですか、そういうことはないのですよね。逆の方はどうなってしまうのですか、それはなしなのか尋ねました。","respondent":"宮澤税務課長","answer":"令和６年中の収入が、所得等が仮に大きくなった場合に関しましては、国の方針としまして、返還等は検討しないというふうになってありますので、返還等は特段ないです。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"去年ですか報告があったときに、先ほども質問がありましたけれどもすごく煩雑で、事務量が多くなってきて大変だよねという話をしていたのです。","respondent":"宮澤税務課長","answer":"今回その金額につきましては、１億３００万円余の委託費を計上しております。それらの事務経費につきましては、１０分の１０補助金で賄える形になっております。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"今後こういうことをやるときには、かかったお金をもらうにしても、事務を行う区側としては意見を言えるところがあったら言ってほしいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"松本委員","kind":"質問・要望","question":"便乗詐欺が出たということが報道されていて、被害で大きいところは３００万円とか出ている自治体もあると伺いました。ここは周知といいますか、こういう可能性があるというところの周知を行っていただきたいと考えていますが、いかがか尋ねました。","respondent":"宮澤税務課長","answer":"給付金事業を実施する際、今回につきましては７月に広報しながわ、そこでも注意喚起をしていきます。昨年度の調整給付金のときに詐欺被害等にお遭いになったというところは特段、把握はしていない状況です。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"先ほども質問がありましたが、この給付金事業ですけれど１億３００万円というお話ですが、これからもまだ続くわけではないですか。やはり、品川区も独立した一つの自治体ですから、こんなことをやっていたら大変だということで言うべきではないのですかと。","respondent":"宮澤税務課長","answer":"減税等におきまして、可処分所得を押し上げて物価高の中で区民の負担軽減を図るというところで実施しています。事務作業につきましては、効率的に進めていって、なるべく職員にとっても負担がかからないような形で進めていくです。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"すみません、言い方が悪かったと思うのですけれど、これからも委託費はまだ続くということですから、増えていくと考えていいのでしょうか。区民の方がありがたいなどとは思わないと、私は思うのですが、その辺について少しご見解だけ説明するよう求めました。","respondent":"宮澤税務課長","answer":"昨年度もほぼ同様の金額をかけて行っておりまして、今回１１月末で事業は終了する予定ですので、昨年度と同様の経費がかかっているです。区民の方の評判ですが、こういった給付金事業というのはとにかく速やかに実施するというところを念頭に進めているところです。","id":"exchange-023"},{"speaker":"須貝委員","kind":"意見","question":"こんなことを地方自治体に押しつける、やれというのは何か間違っているような気がしますので、それだけ少し指摘しておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-03","title":"「品川区職員・教職員向け性的指向・ジェンダーアイデンティティに関する行動指針」の改訂","agenda":"「品川区職員・教職員向け性的指向・ジェンダーアイデンティティに関する行動指針」の改訂","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この性自認をジェンダーアイデンティティに変更した理由というのは何なのか伺いたいのと、これまで、伺いたいと思います。どう進めていくのかというのを知りたいので、そうした研修の回数や、ほかにもう少し何か工夫があるのか伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"にじいろ相談を今実施しているのですけれども、３月まで第２、４月１日から第２土曜日と第４水曜日という形で実施をしております。勤務時間内、就業時間内に実施している形になったことと、そういったものも含めて総合的に取り組んでいきたいなと考えております。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"目標みたいなものというのですか、さらに改訂していくみたいな指針、そういった今後へどうつながるのかなというのもお聞きしたいなと思うのです。","respondent":"木村人権・ジェンダー平等推進課長","answer":"令和５年の法律と令和６年の条例について、そういったものについても取り上げていくというふうな形で、行動指針の次の改訂の時期については考えていくような形になると思います。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"パートナーと配偶者どう違うのとか、とか、逆に分かりづらいというようなことがあるのではないかなと思うのですがどうなのでしょうか。それをどういうふうに、各学校との調整を図ろうとしているのか、まずこれを説明するよう求めました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"区役所の窓口でパートナーって何だろうと思われた方が、例えば窓口で説明を受けて、自分でもそういう言い方を使ってみようだとか。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"例えばトイレだったらトイレを変えていくというようなことを積極的にやってほしいなと私は思いますので、どういうお考えかお聞きしたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"例えば会議に出させていただいて説明をさせていただいたりというような形で、昨年も実施しておりますが、少し話の内容を変えて。選んでいただけるようにしていただいて、拾っていくというかお話を伺う機会を持てるようにしていくように考えております。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"そう書いてあるけれど、それを実際きちんと守りなさいよというときに罰則規定がなくて、果たして守り切れるのでしょうか。しても、それを抑制するような効果が発揮できないと私は思うのですが、その辺についてご見解を説明するよう求めました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"例えば、うまくその方の話しやすい状態をつくっていくというので、内部と外部があるというのは必要なことかなというふうには考えます。","id":"exchange-029"},{"speaker":"須貝委員","kind":"確認","question":"毎回免許更新のときも確認をする。１人でもその弱い立場の人を助けていくということが、パワハラもそうですけれど、人間社会では当たり前にやるべきことではないかなと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"それから、候補者の住所の公表はするのでしょうか。なので、もう少し早くできないものかなと思いますが、いかがか尋ねました。","respondent":"今井選挙管理委員会事務局長","answer":"もう既に６か月前からいろいろな個人ポスターは難しいということで、品川区の会派、そして全議員に１月には通知をさせていただいているところです。今回行いました立候補者説明会につきましても、この２連ポスターにつきましては、通知文書も含めて徹底しているところです。","id":"exchange-031"},{"speaker":"西本委員","kind":"確認","question":"これ１点確認なのですけれど、公報紙にそういうものはあまり書けないと思うので、多分書かないと思うのです。ただ、何かそれを知る機会というのをホームページ上でもご案内するなどということはぜひしてほしいなと思うのですが、いかがか尋ねました。","respondent":"今井選挙管理委員会事務局長","answer":"立候補届出の告示事項から、事前審査終了後、ご本人の同意に基づき報道機関に情報提供をするところになると思います。ですので、今後事前審査終了者につきましては、東京都のほうの届出の告示などを確認していただくようになるかと思います。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"すみません、今の件なのですが、６月１３日が提出ではないですか。それともその６月１３日の情報なのか、例えばホームページなどでの公表になるのか、その辺少し教えてほしいのです。","respondent":"今井選挙管理委員会事務局長","answer":"初めに、５月２６日から事前審査を行いますので、そちらのほうは速やかに報道機関へ提供いたします。東京都のホームページは確認はしていないのですが、告示事項の対象になりますので、一定の情報が都の選管から提出されるものと思われます。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"７２面というのは結構大きな数だなと思うのですけれど、今の時点で、何面掛ける何面みたいなことが分かるでしょうか。スペース的に大丈夫ではない場所も出てくるのかなと思ったりもするのですが、その面の感じが分かれば教えてほしいと求めました。","respondent":"今井選挙管理委員会事務局長","answer":"今回大分幅を取りますので、４段掛ける１８列でいきたいと考えております。４段になりまして、一気に板面を設置できるところと、何とか４段の中で収められる場所を探しながら進めてきたところです。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"４段掛ける１８列ということで、様々工夫が必要になってくる場所もあるということで分かりました。今後、少し工夫が必要なのではないかなと思っていますが、区としてはその辺の現状をどう捉えられているのか伺いたいと思います。","respondent":"今井選挙管理委員会事務局長","answer":"今日発行いたしました、今、要介護３・４まで引き下げることも含めてこの郵便投票による不在者投票の枠を拡大する検討が行われているところです。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"様々な方が無理なく投票できるようにしていただきたいなと思うのですけれども、引き続き私たちとしても求めていきたいなと思いますし、区のほうでもぜひ積極的に考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"意見","question":"細かい中身はいいです、守秘義務もあると思いますので、それはどうなっていますか。どういうふうに進んでいますかとの意見を述べました。","respondent":"藤村総務課長","answer":"その公正証書を作るか否かというところにつきましては、こちらの委員会のほうにお伝えしておりますけれども、個人情報に係るものなので適切な時期にご報告させていただきたいと考えております。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"なので、それをしっかりと、議会への報告はしていただくように強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問","question":"すみません、少しお聞きしたいのですが、新庁舎建設の予定地に建築資材が多数置かれているのですが、あれは品川区の新庁舎の建築資材なのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"今、新庁舎の整備予定地に置かれている建設の資材関係につきましては、隣接で行われているＪＲの工事、そこは今、収去の工事ということで、更地にするための工事を行っておりまして、そういった関係の資機材が置かれているという状況です。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"先ほどの報告事案で出てきたのですけれど、キッチンカーが地所賃貸料で１２日間で少ない面積で１４万６,０００円、賃料として取っていますよね。","respondent":"泉広町事業調整担当課長","answer":"広町のまちづくりの進め方の中では、今そういったところのＪＲとの関係性の中では、そういったお金は請求できないような形になってあります。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"もう、もうそれぞれ土地の配分というか、品川区はこれだけの面積があってここへ建てますよということは確定されているわけですよね。地所代ですか、そんなことはＪＲでも知っていると思うのですが、何かおかしくありませんか。","respondent":"泉広町事業調整担当課長","answer":"新庁舎の整備が予定されている敷地につきましては、その敷地の管理につきましても、今ＪＲが管理をしているということになってあります。使用収益という形で、今は従前のＪＲのほうでその敷地を管理しながら、そこを使用しているということになってあります。","id":"exchange-041"},{"speaker":"須貝委員","kind":"質問・要望","question":"そうしたらそれは区の土地でなければ、その確認申請は受理できないではないですか。そんなことないのではないか尋ねました。","respondent":"堀越副区長","answer":"担当課でご説明いたしましたとおり、その中で今、土地のいろいろな残置物の整理をしているＪＲの収去工事というようなお話をしました。","id":"exchange-042"},{"speaker":"須貝委員","kind":"質問","question":"いや、そういう関係性ではなくて、普通そういうふうに、借りるなら借りるという、そういう権利というのは、社会通念上、向こうも支払うべき話だし、こちらももらうべき話ではないですかということを申し上げています。","respondent":"堀越副区長","answer":"お考えはよく分かりますが、区が当然得るべき利益を得ていないということではございませんので、それはご安心いただければと思います。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"おやっと思ったというか、ここは都市計画審議会でも権利変換などして、もう決まっているのではないのですか。それで、都市計画審議会でもこれが審議されていて、それで、これ全部品川区の持ち物というものではないのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"まず、新庁舎の整備をする予定地となっているところにつきましては、そこは品川区のほうに仮換地をされてあります。使用収益を開始しなければいけないのですけれども、ＪＲのほうで収去工事をやっている関係上、まだ使用収益が回収できてございません。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"ではそれがいつになるのですか。それはいつがそういう状況になるのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"そういったものを撤去する間は、当然ＪＲのほうで工事を進めなくてはいけませんから、今そこでＪＲが工事を進めているです。新庁舎の整備の契約は１０月頃を予定していますが、その前の段階で、品川区のほうで使用収益を開始したいということで考えておるです。","id":"exchange-045"},{"speaker":"新妻副委員長","kind":"提案","question":"理事者の皆様におかれましては、委員から提案がありましたことを実現していただけますようお願いを申し上げまして、ご挨拶とします。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/121362?Template=document&Id=7045#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":39825,"voices":111}},{"id":"r07-20250513-14","meetingId":"r07-cm05","date":"2025年5月13日","dateIso":"2025-05-13","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"品川区ＤＸ推進基本方針の改定","agenda":"品川区ＤＸ推進基本方針の改定","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"では、もう一度確認しますけれども、１月の段階で、今回の内容についてはご説明を受けたという認識でよろしいのか尋ねました。","respondent":"西澤ＤＸ戦略担当課長","answer":"はい、ご認識のとおりです。説明済みの内容になっております。","id":"exchange-001"},{"speaker":"新妻委員","kind":"確認","question":"まず第１弾、そこでしっかりと情報が確認できることが職員の方への業務の改善にもつながっていくかと思いますので、ぜひここは分かりやすいホームページの改定は早めに進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"山本委員","kind":"質問","question":"６名、１８件というところで、さらに進めてほしいなということが思いとしています。１枚紙で示された内容、これまでの取組や評価指標、これは作成はしていらっしゃらないのでしょうかというところからお願いします。","respondent":"西澤ＤＸ戦略担当課長","answer":"時期を明確に定めていて、重点施策については、このスケジュールのとおりやっていくという方針で考えております。ものによるということです。","id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"新妻委員からもご質問、ご要望がありましたけれども、私もぜひ進めていただきたいと考えています。２３区、簡単にアクセスできるようなホームページの改善の手法の１つとして、そういうようなところのお考えについていかがか尋ねました。","respondent":"西澤ＤＸ戦略担当課長","answer":"令和７年度から検討を開始して、令和８年度、令和９年度に向けてホームページのリニューアルをしようというふうに考えております。今年１年間、どういったホームページがあるべき姿かというところを検討しながら、このリニューアルに向けて進めていきたいと考えております。","id":"exchange-004"},{"speaker":"山本委員","kind":"質問・要望","question":"こちらは重点施策３点でございまして、私も要望しているところであり、ぜひ進めていただきたいと考えています。目標延べ６１２回、それから参加人数が延べ２,１１２人とありますけれども、どのような指標の設定なのかをお聞きいたします。","respondent":"横田デジタル推進課長","answer":"高齢者スマホ教室につきましては、少し件数が横ばいになりつつあるというところで、基本的には同程度を想定しています。で、個別のよろず相談は伸びているので、よろず相談を今後集中的にやっていきたいというふうに考えているところです。","id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"私も従前から要望していますけれども、まだまだ高齢者の皆様の全体の数からすると、そういったところの工夫も引き続きお願いしたいと思います。去年１０月に試行実験して、既に１００件以上の声を集めることができたので、お考えをお聞かせいただきたいです。","respondent":"横田デジタル推進課長、西澤ＤＸ戦略担当課長","answer":"私からは、通訳タブレットについてお答えいたします。令和８年度になると、もう２,０００件近くなっているということで、アジャイル的に数値については見直していきたいというふうに考えております。昨年は試行的に実施したところもありまして、結構多くの方々に利用していただいたかなというふうには評価しております。２件以上と、まずできるところから進めていって、毎年この件数を見直していくという方向で考えております。","id":"exchange-006"},{"speaker":"山本委員","kind":"質問・要望","question":"絶対できるみたいな目標だけを設定するのではなく、適切な設定を、効果のある設定をしていただきたいです。前者のほうが学務課、デジタル推進課と教育委員会との連携の方針や進め方がどのようにされるのかということが分かれば教えてほしいと求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"そういったところの協議といったところは我々も支援していますが、この場ではお答えできないところになってしまいまして、申し訳ございません。","id":"exchange-007"},{"speaker":"山本委員","kind":"質問・要望","question":"重点施策が全体の中でも非常に多く、全体８つのうち６つになっておりますので、どれも重要施策ということで進めてほしいと求めました。ぜひ進めていただきたいと思っておりまして、また、これからの見通しがあれば説明するよう求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"学校の教職員の方々の校務の業務改善を進めようとして、校務の中でどういった活用ができるかというところを一緒に考えながらやっていけたらと思っていまして、計画している段階にあります。","id":"exchange-008"},{"speaker":"山本委員","kind":"質問・要望","question":"データ利活用による好事例創出目標５件、データアナリストとの共同案件目標３件というのは、これはそれぞれぜひ進めてほしいと求めました。この辺りについて、なにか現状で説明いただけることがあれば、お願いいたします。","respondent":"西澤ＤＸ戦略担当課長","answer":"全職員対象にアンケートをとる予定でありまして、年度ごとに評価をして、それで改善につなげていくというところを実施しようと思っています。実証としている施策とか、こちらは結構チャレンジングですが、次の報告でまたいい報告ができたらなというふうに思っております。","id":"exchange-009"},{"speaker":"つる委員","kind":"提案","question":"１月のときにも、デジタル庁のデジタル推進委員との連携ということで活用はどうですかという質疑をさせていただきました。貴重なご提案として参考としますというふうな区の回答がありますが、品川区の今後の予定とか、この間の検討状況について説明するよう求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"先ほども説明したとおり、こちらを進めていく内容にはなるのですが、今後進めていけたらというふうに考えております。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"やはり現場でのそういう対応ができる、ぜひ改めてまた積極的なそうした方々との連携について、改めてご検討いただきたいというふうに求めておきます。何かまた改めてご答弁があれば、どうぞ。","respondent":"西澤ＤＸ戦略担当課長","answer":"そうですね、デジタル化の取組で、デジタル庁とも連携して、調査して進めていきたいというふうに考えております。","id":"exchange-011"},{"speaker":"のだて委員","kind":"意見","question":"アクションプランが出てきたのは今回が初めてだと思うのですけれども、最初の説明だと、あまりにも簡潔過ぎるので、このアクションプラン、先ほどから説明されている部分はありますが、さらに説明しておきたいところとか、少し説明をしてほしいと求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"そういったところと連携していくことが重要だと考えておりまして、複数部署での情報共有と横断的アプローチが必要なものだというふうに考えています。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"これがどういった支援システムなのかというところを伺いたいのと、これによって、どのような改善がされてきたのかというところを伺いたいと思います。今、どのくらいあるのか、どのようなものがあるのかというところを伺いたいと思います。","respondent":"西澤ＤＸ戦略担当課長、横田デジタル推進課長","answer":"窓口改善調査を去年１２月に実施しまして、そういったところを見た上で、どこに課題があるかといったところを調査したものになります。近年につきましては、セキュリティインシデントは、品川区においては起きていないような状況になります。","id":"exchange-013"},{"speaker":"筒井委員","kind":"確認","question":"私からは、確認ですけれども、基本方針とアクションプランの関係性です。更新の期間が５年間ですけれども、大体３年になっているかと思うのですけれども、その期間の違いについて伺いたいと思います。","respondent":"西澤ＤＸ戦略担当課長","answer":"基本方針は５年で設定していて、基本方針に掲げた３つの施策は、テクノロジーの進歩に関わらず重要なものだというふうに考えています。それを３か年で実施していくという、見直せるポイントを短く設定するというように考えて、アクションプランは３年で設定しております。","id":"exchange-014"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。重点施策６、このＢＩツールは、具体的にどのようなものをお使いになっているのか示すよう求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"こういった可視化することによって課題が見えてくるので、そういった使い方を職員と一緒に実施しながら、政策のほうへ反映させていくところを実現したいというふうに考えております。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"提案","question":"１点だけ、アクションプランのほうの１７ページのＥＢＰＭ、子どもの食が大切だという意見が多かった。提案、教えてほしいというか、その辺りを教えてほしいと求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"１７ページに示したポートフォリオといいますか、先ほどおっしゃっていたとおり、扱いが結構難しいと思っているポイントであります。データが全てというふうには私ども思っていなくて、データが全てというわけではないというところだけはお伝えしていきたいと考えています。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そういうものだったのかどうかとか、ぜひ進めていただきたいのですが、それは我々もしっかり注視していきたいなというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"西村委員","kind":"質問・要望","question":"１点、要望と質問をさせていただきたいのですが、見えてきた課題から具体的な対策をぜひ拡充していただきたいなというふうに要望します。移行に負担がないのかどうか伺いたいのですが、５月６日だったと思うのですけれども、システム障害が起きていたと思います。","respondent":"横田デジタル推進課長","answer":"今回の５月６日のシステム障害につきましては、住民票と印鑑証明が出力できなかったというものになります。ＳＥを含めて、この辺りを反省しながら、二度と起こさないように推進していきたいと考えております。","id":"exchange-018"},{"speaker":"西村委員","kind":"質問","question":"ということは、これぐらいの不具合は例年起きているということでよろしいのか尋ねました。","respondent":"横田デジタル推進課長","answer":"今回たまたま起きてしまったというところになります。ただ、たまたまということを反省しながら次回に活かしていきたいというふうに考えております。","id":"exchange-019"}]},{"id":"topic-02","title":"「品川区ふるさと納税特設サイト」の開設および「しながわ団体応援寄附」の開始","agenda":"「品川区ふるさと納税特設サイト」の開設および「しながわ団体応援寄附」の開始","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"本当に全然分からないので教えていただきたいのですけれども、これは業者を代えてしまうということでいいのかどうかということが１つと、今までは。代えるのかというところと、今のところを説明するよう求めました。","respondent":"宮澤税務課長","answer":"２つ目の質問にもかかるのですが、様々な自治体の寄附、商品等が掲載されているというところです。逆に言うと、例えば目玉商品であったり、特集をすることによって魅力を発信していくということができるということがポータルサイトとの違いです。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問","question":"３番目にクラウドファンディングとあるのですけれども、どういう立て分けをされるのか、そこだけ説明するよう求めました。","respondent":"宮澤税務課長","answer":"クラウドファンディングする場合、既存のポータルサイトを今年度も予定しておりますけれども、そちらのほうも活用します。ただ、このふるさと納税特設サイトのほうでも、同じ時期、同様に募集を開始するという形になります。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問","question":"例えば、毎年やってきたしあわせ食卓事業のためのガバメントクラウドファンディングと同じものをこの特設サイトでやるということなのでしょうか。金額もそれぞれ立ててやるということなのか、その辺りをもう１回説明するよう求めました。","respondent":"宮澤税務課長","answer":"同じ内容で、同じ目標金額を立ててやります。集まった金額は、両方が最終的には合算するというような形になります。","id":"exchange-022"},{"speaker":"山本委員","kind":"質問","question":"その中でより効果的にやっていくということが大事であると考えています。その中で幾つか質問しますけれども、委託でやっているのか、そして幾らぐらいかかっているのかを説明するよう求めました。","respondent":"宮澤税務課長","answer":"今年度から、ふるさと納税を進めていく上で、中間事業者に委託をかけております。その委託金額、予算上は７００万円を計上しておりまして、その中で事業者のほうで区と連携しながらサイトを構築しています。","id":"exchange-023"},{"speaker":"山本委員","kind":"質問","question":"そうしますと、やはり効果をどう検証していくかというところがあるかなと思うのです。そういったところの目標があれば、目標設定内容、それぞれの目標指標等を教えてほしいと求めました。","respondent":"宮澤税務課長","answer":"先ほど説明もさせていただきましたが、今回このふるさと納税の特設サイト上でしながわ団体応援寄附という新たな寄附の枠組みも行います。そういった方が区の返礼品を伴う寄附もあるというところで、より目を向けてもらえればというふうにも思っているところです。","id":"exchange-024"},{"speaker":"山本委員","kind":"質問・要望","question":"例えば、見てもらうためにどういう工夫が必要かということで考えて、より多くの方々に知っていただいて寄附をしていただきたいと考えています。","respondent":"宮澤税務課長","answer":"特設サイトの周知という部分ですけれども、今年度、ふるさと納税の取組に対して、広報しながわの特集号を発行する予定です。そういったところはよく横串を刺すといいますか、連携しながらやっていきたいと考えているところです。","id":"exchange-025"},{"speaker":"山本委員","kind":"質問・要望","question":"いずれにしましても、より多くの方に知っていただいて、効果が出るように進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"今回、しながわ団体応援寄附というものを始めるということで、この事業を区が実施するに至った経緯を伺いたいと思います。上限７割というのはどういうことか伺います。","respondent":"宮澤税務課長","answer":"そういったところも踏まえまして、今回、特設サイトの開設と併せまして、しながわ団体応援寄附を開始するに至ったところです。１０万円のうちの７割、７万円を補助金として交付する、そういうイメージになります。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"経緯はご説明いただいて分かった部分はあるのですけれども、そうすると、今、区内の大学や高校、中学校の経営がなかなか大変な状況があるということで、国もそうしたモデルケースなどを示してやっているということなのか、そこを伺いたいと思います。","respondent":"宮澤税務課長","answer":"学校法人を対象とさせていただいていまして、区内の学校法人の経営が厳しいというようなことではなくて、今回、広く多くの方に応援してもらうというところで寄附を集めまして、事業に活用していただくというところで寄附を集めるというものです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"違っていたらまた教えてほしいのですけれど、特別区長会等々を通じて、それと今回は特設サイトをつくられて頑張っていくということは理解しました。広がりが増えていくと思うのですけれども、都市ブランディング事業との連携ということで、どのようにお考えなのか尋ねました。","respondent":"宮澤税務課長","answer":"委員のご指摘のとおり、流出していく金額が令和６年度で５０.９億円というところで、この金額は年々増えていくことは間違いないと見ております。その中で都市のブランディングというところを担当部署とも連携しながら進めていきたいと考えております。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"ぜひ都市ブランディングとの連携をよろしくお願いします。その点を考えて、こうした仕組みにしたのか、その辺りのお考えはいかがか尋ねました。","respondent":"宮澤税務課長","answer":"委員ご指摘のとおり、在学時代は区内に通っていただいて、全国にお住まいの方が非常に多くあろうかと思います。まさに区外にお住まいの多くの方が、団体応援の寄附もしてもらいつつ、返礼品を伴うような寄附にも発展していけたらと考えているところです。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それがもう４００でも５００でも出てくるのですかということをまずお聞きしたいのと、クラウドファンディングでもいいのです。２％でもいいではないか尋ねました。","respondent":"宮澤税務課長","answer":"１点目の部分としまして、プロを入れるというお話に関連してです。今年度は、現状、約５０品目程度なのですけれども、それを今年度中に２００品目以上にはしていきたいというふうに考えているところです。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"メニューの数が５０から２００にしていきますと言うのだけれども、渋谷区とかでも、もう４００幾つとか５００ぐらい出しているわけではないですか。なぜこういうところに手がつかないのですかということを聞きたかったのです。","respondent":"宮澤税務課長","answer":"プロの活用という部分ですけれども、中間事業者をこの４月に入れて進めております。私も４月から着任しておりますけれども、事業者としっかり連携しながら、まずは品目の拡大も含めてやっていきたいというふうに考えているところです。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問","question":"１軒２軒やっていきます、どうしてそういう営業的な方、プロで営業を１軒１軒潰して歩くぐらいの人を見つけたほうがいいような気がする。だけど、それぐらいの勢いでやったほうがいいのではないですかということをお願いだけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"つる委員","kind":"確認","question":"別でいろいろ確認もさせていただいて、次年度以降ですか、そういうふうな本来区に入ってくるべきものがなかなか入ってこなくなる。見えやすい場所というのですか、品川区の位置ですから、説明するよう求めました。","respondent":"宮澤税務課長","answer":"花火大会におけるふるさと納税の返礼品です。実行委員会と調整しておりますので、返礼品として、そういうものを用意するということは可能です。","id":"exchange-034"},{"speaker":"つる委員","kind":"質問・要望","question":"東京湾大花火大会が再開できることを物すごく強く期待するのですけれども、そういったときに、品川区はあちら側の１３号地もあるわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/390831?Template=document&Id=7047#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":30539,"voices":92}},{"id":"r07-20250514-19","meetingId":"r07-cm05","date":"2025年5月14日","dateIso":"2025-05-14","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 １時５６分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"令和７年度しながわゼロカーボンアクション助成の受付開始","agenda":"令和７年度しながわゼロカーボンアクション助成の受付開始","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"どこがどのように減らしていけばいいのかというロードマップを出してくださいとずっと要望していたのですが、若干といいますか、すごく一家庭がどう。","respondent":"中西環境課長","answer":"２３区の取組状況といったところのお尋ねです。ほかの区でも特色ある取組をしていますので、品川区でそういったものが落とし込めないかというものは日々研究してまいりたいと考えているところです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですから、国と都のものも分かりやすくするということはできないのでしょうかという、いかがか尋ねました。","respondent":"中西環境課長","answer":"ちょっとどういったお示しの仕方ができるかということはあるのですが、ホームページのほうでも国や東京都の補助メニューはご案内はする予定です。ちょっとどこまでできるかといったところはありますが、研究させていただければと思います。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、先ほど６月に説明、パネルを展示して区民の皆さんに説明していくということで、いつどこでということがもう決まっているのですか。６月のいつかをちょっと、すみません。","respondent":"中西環境課長","answer":"今、６月１７日火曜日から６月３０日の月曜日まで、コミュニティラウンジ内のパネルが貼れるところに展示をしようと考えています。それから説明会に関しましては、１２時から１７時の間で説明会、相談会を行おうと考えているところです。","id":"exchange-003"},{"speaker":"吉田委員","kind":"確認","question":"１点確認です。その先が２つに分かれていくということは、記載がきちんとされていれば、審査では基本交付決定というようになるという理解でよろしいか尋ねました。","respondent":"中西環境課長","answer":"例えばエコジョーズとか、エネファームとか、最近少し間のような機種も出てきております。そういったものがきちんとその申請内容と合っているかといったところの審査といったものはあるところです。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"基本やはりきちんと記載されていたら、皆もらえたほうがいいなと思って質問をしたのですけれども、それはどこかで分かるということですか。ごめんなさい、きちんと読み込めていないので、その辺が分かるようになっているのか説明するよう求めました。","respondent":"中西環境課長","answer":"この資料の１０ページのところにも、エアコンが何％以上、冷蔵庫だと何％以上といったものは記載をしています。大型の家電量販店などですと、この制度もご存じなので、そこに合うような形でご紹介をいただいているということも実情かなと考えています。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほどの６月のエコルとごしでの説明会なのですけれども、この説明会というものは、ちょっとその辺のところを教えてほしいと求めました。そのようなところも含めての相談が、この説明会ではできるのか、その辺のところも教えていただけたらと思います。","respondent":"中西環境課長","answer":"基本的には区の助成制度についてのご相談を承るというところになります。環境部門の制度に関してはご説明できるのですが、なかなか責任を持ってお答えが難しい部分がありますので、私どもでは難しいかなと思ってあります。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから２ページのところで、かなりこれで、東京都のゼロエミ住宅は多分南側の屋根しかつけられないということだったと思うのです。東側に太陽光をつけるとか、そのようなものでも補助金がつくのか教えていただきたいということと、ちょっと教えていただけたらと思います。","respondent":"中西環境課長","answer":"それからこちらのパンフレットの太陽光システムの試算なのですけれども、４キロワットアワーの想定でつくってあります。何というのでしょう、その電気でご家庭を回したとするとこれぐらいといったような試算になっているということで、ご了承いただければと思います。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その期限で、これを超えた場合は抽せんになると、そのようなことでしたか。それは、要望に応えられるだろうという件数で想定しているのでしょうかというようなことを伺いたいということと、その点も伺いたいと思います。","respondent":"中西環境課長","answer":"１つ目の予定件数のところですが、例えば太陽光に関していいますと、今年度は１００件という予定件数にしています。件数に達してしまった場合の対応といったところですが、そのときの状況の中で判断をさせていただきたいなと考えてです。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひこれは積極的に、気候危機に対しての対策というようなところでも、これだけ区としても積極的な対応していただいているということで、要望がそれを超えた場合は要望に応えられるようにぜひともしていただきたいということで、要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"確認","question":"それに対して７０件というものは、これはもう本当に、７０件というものは私分かります。もう一つが、建設４団体の方々には、４団体の方たちにはどのような周知をされているのかどうかということを確認したいと求めました。","respondent":"中西環境課長","answer":"それから建設４団体など、そういったところで、データのほうをお送りしたいと。どういった形がいいかということはこれから相談しながら進めていきたいと考えています。","id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。それは区のほうでこのような助成制度をやりますよということでお伝えをした上で、その認識をしているということでいいのか尋ねました。","respondent":"中西環境課長","answer":"量販店の方に関しては、昨年度、特段こちらからアプローチをしたわけではなくて、先方のほうで助成制度をお調べになってご説明をされていたといった経緯があります。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですから、今言ったまちの電気屋にもお知らせをし、もっと言えば、不動産屋もこのようなことを知っておいていただきたいというところです。","respondent":"中西環境課長","answer":"まとめてのご回答になるかと思いますが、例えば城南信用金庫など、そういったような金融機関のほうにお力をお借りして周知をしようと考えています。走りながら、もっとできることはないかということを考えながら進めてまいりたいと考えています。","id":"exchange-012"},{"speaker":"まつざわ委員","kind":"質問","question":"でも防犯カメラというものは所管が違ってしまうではないですか。何ですか、助成金の表をつくっていただけると非常に助かるかなと思いますが、いかがか尋ねました。","respondent":"中西環境課長","answer":"ただ、おっしゃるとおりで、なかなか文字だけになってしまって具体的に何に使えるのかということは分かりづらい部分はあろうかと思います。引き続き、他課と連携をしながら、どういった見せ方ができるかといったものは環境課のほうで考えてまいりたいと思っています。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"それとこれ、ちょっと大きな意味でお聞きしたいのですが、今太陽光発電のシステムをやっている事業者がどんどん倒産していると。その辺についてもどのようなご見解を持っているのか、簡単でいいので、もしお考えがあったら説明するよう求めました。","respondent":"中西環境課長","answer":"区民の皆様、ひいてはそういった事業者たちの活躍の場が広がっていけば、私どもとしては１つ支援をしている形になるのかなと考えているところです。ちょっと回答になっていないかもしれませんが、以上です。","id":"exchange-014"},{"speaker":"須貝委員","kind":"意見","question":"ぜひ、これは区にお願いをするというよりは国にお願いするしかないので、ぜひいい方向に進んでいくように期待をしておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問","question":"何というのですか、区としては、そのような庁内横断型のプロジェクトチームのような形ではなっていないのか。そのようなプロジェクトチーム、この中に品川区が入っているのか、ちょっとその点を説明するよう求めました。","respondent":"中西環境課長","answer":"ではＰＴを組んで何とか推進会議というような形というものは、この助成制度を、ほかの助成制度をという形でやっているものは特段ございません。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"意見","question":"一体化しているような、そのような点では庁内横断型のプロジェクトチームというものも、今後に向けてご検討いただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"ゆきた副委員長","kind":"質問","question":"１４ページの東京都や国の併用は可能ですかということで、よくある質問の中でありますが、少し複雑だと感じています。先ほどの答弁の中でも、載せていく方向でさらに研究というようにありましたが、改めてこの辺についてお聞きできればと思います。","respondent":"中西環境課長","answer":"間違った説明になってしまわないようにといったところが一番重要かなと思います。一般的な制度説明など、それからこのページを見てくださいというような説明はできるかなと思いますので、取り組んでまいりたいと思います。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問・要望","question":"そのような、何というのですか、体制だけは何とか私は早急に取っていただきたい。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"何というのですか、し尿処理車両というのですか、それほど台数はないのではないですか。トイレトラック１台ではどうしようもなくて、未来像というのですか、そのようなことももちろん検討されているのか尋ねました。","respondent":"星災害対策担当課長、羽鳥防災課長","answer":"今回の訓練につきましては、トイレトラック１台について１台バキュームカーが来ます。そちらで十分吸い取りが可能な量ですので、今後もそのような形で考えているところです。助けあいジャパンの考え方としても、各自治体１台ずつという考え方にのっとっております。その取組の中で、バキュームカーも同時に支援を受けるような仕組みになっていると伺っております。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"人が動けなくなったということはまずいと思うので、そのようなことも、区としても考えていただきたいと私は思います。公園に置けば、そのような諸問題たくさん出てくると思うので、この大都会の中の防災ということを私はしっかり考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"配慮があったのですか、非常に何というのですか、すばらしいと思っています。やはり地域の人たちに、これから水防訓練にも求められていくのではないかなと思っていますけれども、その辺説明するよう求めました。","respondent":"星災害対策担当課長","answer":"地域によって様々な地域特性がありますので、今回行う水防訓練が、優先度が高い地域とそうでない地域とあると認識しております。まず地区での防災訓練の中に取り入れていただく、こういったところを進めて、区民の皆様の技術向上も図っていきたいと考えているところです。","id":"exchange-022"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"地区防災協議会でしっかりご意見を聞いていただいて、地区防災協議会だけではなくて、やはりこのようなところにも、訓練の重要性がありますよということは、引き続き周知してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/505358?Template=document&Id=7049#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":19138,"voices":66}},{"id":"r07-20250515-10","meetingId":"r07-cm05","date":"2025年5月15日","dateIso":"2025-05-15","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件整理しています。","topics":[{"id":"topic-01","title":"常任・議運・特別委員会の構成","agenda":"常任・議運・特別委員会の構成","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"申合せ確認事項を読みますと、こちらについては、いかがでしょうか。ご意見があれば、委員長含めてお伺いできればと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"まつざわ委員長","kind":"質問","question":"議会運営委員会に入れてほしいというお話であったりとか、ではこうしてほしいというお話が、現状維持のままやっていきたいと考えています。よろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"特別委員会が３つとなりますと、合わせて１６個なのですけれども、ここで言ってもいいでしょうか。それとも後がいいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"示された民意を正確に議会に反映するというのが私は民主的な議会だと思っているので、こういうルールにそろそろ切り替えるべきだと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"私たちがあるべきだというのが比例配分方式で、今、なおかつ大会派の方がやはり選挙をやればそれは数が多いわけですから当然勝つわけです。変えたほうがいいのではないかと思っているという意見を述べさせていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"土地開発公社議会選出評議員の推薦","agenda":"土地開発公社議会選出評議員の推薦","exchanges":[{"speaker":"せお委員","kind":"質問","question":"１つ前の附属機関なのですけれども、この１列目の数というところはトータルの数ですか。これというのは足した数か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/350163?Template=document&Id=7051#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":13143,"voices":73}},{"id":"r07-20250521-10","meetingId":"r07-cm05","date":"2025年5月21日","dateIso":"2025-05-21","committee":"議会運営委員会","time":"午後 １時００分～午後 １時０８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/350163?Template=document&Id=7053#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":3433,"voices":26}},{"id":"r07-20250526-10","meetingId":"r07-cm05","date":"2025年5月26日","dateIso":"2025-05-26","committee":"議会運営委員会","time":"午前１０時００分～午前１０時４５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件整理しています。","topics":[{"id":"topic-01","title":"議事日程(1)、追加議事日程および追加議事日程(2)","agenda":"議事日程(1)、追加議事日程および追加議事日程(2)","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"採決時の起立が難しいため賛成は挙手によるものとしていただきたいということ、投票箱への投票に当たって、以上３点をご了承いただけないでしょうか。ご検討。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"安藤委員","kind":"意見","question":"毎回そのたびに申し出があるのですが、恒久的に、その都度申し出がなくてもできるように改善できないのかという考えを持っていますので、もしよければそういった制度を検討していく必要があるのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/350163?Template=document&Id=7055#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":6373,"voices":47}},{"id":"r07-20250527-6","meetingId":"r07-cm05","date":"2025年5月27日","dateIso":"2025-05-27","committee":"区民委員会","time":"午前１０時０７分～午前１１時０４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"第６７号議案、令和７年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第６７号議案、令和７年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"そういう地域経済活性化の中身の分析というのはしているのかというのを、改めてお伺いしたいと思います。もう少し詳しく説明していただきたいのと、歳出のどこら辺にそれが含まれているのかというのも説明するよう求めました。","respondent":"小林地域産業振興課長","answer":"対面のほかに、買い方ということを問合せたときにお答えできるような専用の電話を設けるイメージで考えております。今回導入に際して、どういうふうに入れていいのか分からないなどというお話もあると思いますので、そういう対応もしていきたいと考えております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"券種を２種類にしているではないですか。その理由を改めてお伺いしたいと思います。","respondent":"小林地域産業振興課長","answer":"ただ、中小店舗の支援というときに大型店舗ばかりで使われるという場合の逆の悪い影響というのもあると思いますので、こういった２券種をつくって。その利用料として、発行総額に応じたシステム利用料を必要とするということで予算計上しているものです。","id":"exchange-002"},{"speaker":"ゆきた委員","kind":"質問","question":"もちろん利用開始となる１０月には示されることになると思われますが、店舗はいつまでに示されるのかというのをお聞きできればと思います。そこについてお聞きしたいと思います。","respondent":"小林地域産業振興課長","answer":"今、我々は最大８,５００店舗と考えております。システム利用料１,８１５万円とありますけれど、店舗側の方が買う側、売る側の両方のシステムをこの部分で対応するという予算です。","id":"exchange-003"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。ということは、ＰａｙＰａｙへの手数料負担については補填されないということになるのか尋ねました。","respondent":"小林地域産業振興課長","answer":"決済手数料については、特段、品川区で直接補助するということは考えてございません。例えばですが、お店側がこのデジタル商品券に参加するからプラスアルファで上乗せを支払うといったことはございません。","id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"これについて、キャッシュレスを促進する区の相談窓口の対応を進めてほしいと求めましたが、今どのようなお考えなのかというのがまず１点です。","respondent":"小林地域産業振興課長","answer":"１点目の、例えば高齢の経営者のお店の対応です。もう１つのご質問が、利用者側も同じでして、使用期間あるいはそれ以外の問合せにも対応できるようにしていきたいと考えております。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問","question":"ぜひこの期間の地域センターに行けば担当の方がいるなどの対応で、丁寧に進めてほしいと求めました。もし何かありましたら、お願いします。","respondent":"小林地域産業振興課長","answer":"利用者に今回幅広く使っていただくというところが大事なポイントだと考えていますので、説明会というのは、そういったフォローができるようにというのを考えていきたいと考えています。","id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問","question":"出てくる中小店舗というのは同じものなのでしょうか。チェーン店などは、どちらに入るのかもお願いします。","respondent":"小林地域産業振興課長","answer":"我々も実際に店舗側への周知をやっていく中で、例えば商連の加盟店は１,６００店がありますが、我々はまだ完全に把握し切れていない部分です。","id":"exchange-007"},{"speaker":"おぎの委員","kind":"質問","question":"紙面で５００円という券を持っていると、少し高額というか、それでこの際に自転車もということも過去にあったのかと思います。それともやはり５００円といった単位みたいな、目安みたいな数字というのはあるのか尋ねました。","respondent":"小林地域産業振興課長","answer":"先ほど安藤委員へのご回答の中でお伝えしましたが、実際の買物では、そういう形で地域の店舗で使っていただくというような形が多いようです。ふだん買わなかった物をこの機会に区内で買っていただくという１つのきっかけになるのではないかなと考えているところです。","id":"exchange-008"},{"speaker":"石田（し）委員","kind":"確認","question":"改めてお伺いします。それとも区外の方も買えるのか尋ねました。","respondent":"小林地域産業振興課長","answer":"４番の契約方法に絡めて、こちらは最初に当初予算をまずご承認いただく段階で、複数の事業者に提案していただきました。今回、ほかの事業者よりもより多くの店舗で使える仕組みを提案してきたということで、ＰａｙＰａｙが選択の理由になっているところです。","id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問","question":"紙とデジタルの今回の補正予算額を見ると、デジタルのほうが圧倒的に事務手数料みたいな部分がかかっているわけではないですか。そこを説明するよう求めました。","respondent":"小林地域産業振興課長","answer":"１０％でもかなり反応がいいということもあるので、かつ、発行総額を増やすということで考えたものです。お店側の対応です。","id":"exchange-010"},{"speaker":"せお委員","kind":"質問","question":"そして、委員の皆様の質疑で大体分かってきましたが、１点だけ。効果の違いみたいなところというのは、どのように考えられているのかと疑問に思ったので、お願いします。","respondent":"小林地域産業振興課長","answer":"あるいは直近では東京都も２回ぐらいやっていますが、そこでポイントがついて、ちょっとどうなのですかねというご意見をいただいたところです。仕組みとしては、その意味では区の財源を使ってというところで、区内により還元できる仕組みになっていると思います。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、今回プレミアム率が２５％ということですが、なぜこの時期にこういうふうに上げたのですか。それをしっかりつかんでおかないと、何だかという思いがやはり出てしまうから質問させていただきたいのですが、その辺はいかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"今、委員がおっしゃるとおり１０％が従来ずっと続いてきて、今でも品川区の商品券の基本的なスタンスとしては１０％というふうには考えております。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"１０％といっても、私は考えの中の１つだと思いますが、その辺はよく区商連と話していただいて。ありがたいので、その辺も考えていかないといけないと私は思いますが、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"今回ＰａｙＰａｙが一番金額的にも効率的であり対象店舗も広いということでやっておりますけれど、仕組み自体もこれが絶対不変とは考えておりません。","id":"exchange-013"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１０月上旬というから間に合わないのかもしれないので今回はあれですけれど、ぜひそういうのも含めて検討していただきたい。その辺、もしお考えがあれば説明するよう求めました。","respondent":"小林地域産業振興課長","answer":"東京アプリも、ひとまず今回のように、区民の方が地域で買物するときに東京アプリがダイレクトに使えるわけではないような仕組みです。そのシステム自体が今後各自治体の仕組みにどう関係するのか、しないのかというところは、きちんと勉強していきたいと考えています。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"米高騰対策支援の支援金やお米券の配布や、あるいはインボイスと合わせた物価高騰、米トランプ関税の区内事業所・個人事業主の実態調査。それと省エネルギー対策、業務改善設備更新助成金の復活を、さらなる物価高対策を求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/541601?Template=document&Id=7063#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":19186,"voices":60}},{"id":"r07-20250527-7","meetingId":"r07-cm05","date":"2025年5月27日","dateIso":"2025-05-27","committee":"厚生委員会","time":"午前１０時０８分～午前１１時１５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"第６７号議案、令和７年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第６７号議案、令和７年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"１２本ずつ２４本ということでいいのでしょうか、それの確認をさせていただきたいのと、まずお聞かせほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"飲料２４本を２回に分けて配送するのですけれども、高齢者本人やご家族から聞き取りを行って、確認する事業スキームとなっております。熱中症予防を契機とした見守り支援が目的ですので、世帯の人数によって数を変えるということは考えてはおりません。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうすると、どういうふうに分析するのかなというのを少し伺いたいのですが、つながっているかどうかというのも含めてアンケートで取るのですかね。","respondent":"菅野高齢者福祉課長","answer":"今、委員がお話ししていただいたように、「エアコンの冷房を使用されていますか」などの項目等を聞く予定となっております。本当にその人の体調が在宅介護支援センターなのか、少し今対応している中で、緊急的に対応したり。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、これだけの状況になっていると思うのですが、そういうためにも、できれば、リーフレットがあるではないですか、熱中症予防のリーフレット。","respondent":"菅野高齢者福祉課長","answer":"民生委員や在宅介護支援センターの職員に、気になる方にはということで、環境省作成の熱中症対策のリーフレットを配布しています。配送員の方も、このリーフレットで書かれていることを基本にアンケートを実施して、そのあたりで対応をしていきたいなとは思っております。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これからぜひご検討いただきたいと、これは厚生委員会なので、要望させてほしいと求めました。熱中症に対しての啓発の講座の取組がされているというのは伺ったのですが、今どのような状況になっているのかを伺いたいのと、伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区で在宅介護支援センターが２０か所ありますが、ベースとしてこの時期も同じように行ってまいりたいと考えています。今回、普及啓発については、在宅介護支援センター等を通して何かお話ができるような仕組みはつくってまいりたいと考えています。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に熱中症に対しての、何というのですか、暑さも感じにくい。最後に、都が体内の温度を確認できる腕時計型端末を高齢者に無料配布というところも書かれていたのですが、この中身が分かったら説明するよう求めました。","respondent":"菅野高齢者福祉課長","answer":"熱中症の予防啓発については組織的に対応していくという部分につきましては、そういった組織的な対応も今後は検討してまいりたいとは思っております。２０か所の在宅介護支援センターがありますので、在宅介護支援センターのケアマネジャーの判断で、考えているところです。","id":"exchange-005"},{"speaker":"ひがし委員","kind":"確認","question":"高齢者の熱中症に対する対策を取ってくださるということは、とてもすばらしいことだなと思います。もしご家族とかが、問合せ先とか確認をできる窓口というのもしっかり設けられているのかというところを、まずは確認したいと求めました。","respondent":"菅野高齢者福祉課長","answer":"運送事業者が今後決まってまいりますので、少しでも高齢者の方が不安を取り除けるような形で考えていきたいなとは思っているところです。コールセンター等も設置させていただきたいと考えていますので、多分、そういった流れをつくっていきたいなと考えています。","id":"exchange-006"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その点は要望とさせてください。６月から本当は動き出しておくのが一番効果的なのではないかなと思うのですが、その点についてのお考えをお聞かせほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"今回この補正で緊急的に対応という形で提案させていただいたのも、少しでもということで、このタイミングで補正予算を組ませていただきました。８月の上旬から１回目、９月の上旬から２回目という形で、少しでもそこはお応えできるようには頑張ってまいりたいと考えています。","id":"exchange-007"},{"speaker":"筒井委員","kind":"確認","question":"確認ですが、今回、一般財源で２億８,０００万円ほどになっておりますけれども、この一般財源を見て、財政調整基金の繰入金５億４,０００万円のうちの２億８,０００万円ということでよろしいか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"財政当局のほうから、そのような形でとは聞いております。","id":"exchange-008"},{"speaker":"筒井委員","kind":"意見","question":"やはりそれほど緊急性を感じられて、今回この補正予算となったということなのか、そのあたりのお考えを説明するよう求めました。","respondent":"菅野高齢者福祉課長","answer":"民生委員や、あとは在宅介護支援センターのケアマネジャー等のご協力も得ながら、進めさせてはいただいておりました。そういったところも含めて、そういった熱中症の部分と物価高騰の部分を併せて、両面の形で補正を組ませてもらっております。","id":"exchange-009"},{"speaker":"筒井委員","kind":"確認","question":"本当に物価高騰で今後もますます大変だと思いますので、こうした観点からはよかったかなと思います。１本あたり約１６６円程度ということでよろしいのかということと、そういうことも配られるのか、確認としてその内訳を改めて説明するよう求めました。","respondent":"菅野高齢者福祉課長","answer":"はお茶なども混ぜさせていただいて、スポーツドリンクだけではなく、ほかの飲物も一緒にセットにさせていただこうかなとは今考えております。全ての高齢者の体に優しい飲物が基本であると考えておりますので、そうした組合せなどを検討してまいりたいなとは思っております。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"ぜひそうした体に優しいものをお配りしていただけるとよろしいかなと思います。単純に配送業者の方に委託されると考えているのか、それとも飲料系専門の卸売業者のところに頼むのか、どういったことを想定されていますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"熱中症予防・高齢者見守り支援事業委託という形で、今回予算が整いましたら、早速公募を始めさせていただきたいなと考えています。見守りの支援を行っていただくというところとコールセンターの設置などについて、今回、事業者を選定していくという形になっていくと思います。","id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お願いします。当然、どれぐらいの人員で配送をしてもらうような、１日何人ぐらいの方が稼働するみたいなイメージというのはあるのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"３万６,６００世帯の方を回っていただくという形でお願いさせていただこうかなと考えていますので、１日何軒ぐらい回るのかというのは、それぞれの事業者で見積もっていただくことになっていくのかなと考えています。","id":"exchange-012"},{"speaker":"やなぎさわ委員","kind":"確認","question":"住所も確認しながらということになると、同じ番地でどうとかとやっていると、結構時間がかかると思うのですね。そうなったときに、本当に１日１,２００軒回れるのかというところが結構、その辺は何か想定されていたりしますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"この間、区としては、報道させていただいたことによって、運送事業者何社からか問合せもあったりしております。見込みとしてはできるのではないかというお声も聞いておりますので、この事業スキームで進めさせていただければなと考えています。","id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"１回目も２回目も回るなんて言っていたけれども、いい事業だと思いますけれども、ぜひ事前にもう少し見込みを立ててほしいなということは要望します。どういった経緯で去年の内容からこういった内容にバージョンアップしたのか、その辺も少し教えてほしいと求めました。","respondent":"菅野高齢者福祉課長、寺嶋福祉部長","answer":"関わっている方たち以外のそういった方たちにも、アウトリーチという形で実施できたらなというところで、事業は始めするものです。検討したという経緯がありますが、残念ながらそれを形にするところまで検討が煮詰まらなかったというのが、これまでの正直なところです。","id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"確認","question":"当然、私はあれはいい事業だと思っているので継続してほしいのですが、あれはたしか１０月ぐらいですよね、見守りされるのが。その辺は特に関係なく、別々でやるということでよろしいか尋ねました。","respondent":"東野福祉計画課長","answer":"同じ長寿見守りですけれども、１０月ではなく９月に行っております。当然、かぶる方はいらっしゃるかもしれませんが、目的が全く違うものですので、通常どおり実施します。","id":"exchange-015"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。その中にぜひＯＳ－１を、もし熱中症、その辺はご検討はしていただけるか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"よくよく、ＯＳ－１は脱水症のための食事療法に用いる経口補水液で、医師から指示された場合に飲むことが望ましい飲物のようなのですね。","id":"exchange-016"},{"speaker":"若林委員","kind":"確認","question":"大体その３つが大きな事業の柱になるのかなと思うのです。それで、この紙面には出ていないので、そこら辺、金額的なところを確認します。","respondent":"菅野高齢者福祉課長","answer":"飲料費が１億４,４２９万２,０００円、そのほかにアンケート管理システム経費等で２,３２６万９,０００円を計上させていただいて、合わせて今回の委託料の総額となっております。","id":"exchange-017"},{"speaker":"若林委員","kind":"質問・要望","question":"これは２回の配送なのですが、特に配達のほうですかね、配送のお尻というのはどのぐらいで設定されているのかというのをお聞きするのが一つ。この３番の事業内容の中には、この約３万６,６００世帯全部に配れなくても、そこら辺を確認したいと思います。","respondent":"菅野高齢者福祉課長","answer":"まず、委託の契約期間ですが、こちらは７月の中旬から始まって１０月の末までという形で今のところ考えております。は不在者連絡票で対応する、それぞれのお考えもあるので、難しさもあるのかなとは捉えております。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"それはやはり、今年度は補正予算という形でこの真夏の事業になったわけですが、では、来年度はどうしようかと。１０月末ということでしたけれども、継続してこの事業の中で行っていただきたいなと思いますけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"配布の中でアンケート実施ということで、取らせていただこうかなと考えていますので、考えていかなくてはいけないかなと思っているところです。","id":"exchange-019"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"これはこれで２度行っていただく、そういうのが確認できたとき、これはフォローが必要だなという人が……。それから、お伺いしたいのは、これ、歩留りはどれぐらいで考えているのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"事業者としては見込みで仕入れをするような形がいいのではないかなということを言っている事業者もおりました。先ほどの緊急時の対応というのが、やはり一番大事な肝ではないかなと私も思っております。","id":"exchange-020"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"ぜひよろしくお願いします。やはり特に９月は少しでも早いほうがありがたいわけだから、そこら辺はぜひお考えいただいて、よくやってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"高齢者の７５歳以上の方全てに基本的にアンケートが取られるというのは、そういう人が適切なサービスにつながるというところにもつながっていく。","respondent":"菅野高齢者福祉課長","answer":"もちろん事業についての、急に始まった事業ということもありますので、そういったことも含めて、報告できる機会がありましたら、研究していきたいとは思っております。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/166682?Template=document&Id=7061#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":21484,"voices":69}},{"id":"r07-20250527-9","meetingId":"r07-cm05","date":"2025年5月27日","dateIso":"2025-05-27","committee":"文教委員会","time":"午前１０時０７分～午前１０時３９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"第６７号議案、令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第６７号議案、令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"１５７万４,０００円と２７９万８,０００円ということで、何というのですか、適正と認めてこの金額にしたのか。いわゆる人件費が上がっているというようなところだと思うのですけれども、それにしては少し軽微だなと思ったので、その辺り説明するよう求めました。","respondent":"芝野保育入園調整課長","answer":"この補正予算案が通りましたら、今度は契約変更の手続になるのですが、そちらについては総務委員会のほうでご審議いただく形になります。続きまして、毎年インフレスライドによる対応は発生しておりまして、ここで補正を組ませていただいているところです。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ではちょっとまとめて、最後私立幼稚園のほう、いわゆる物価高騰の私立保育所等運営事業者の支援について伺います。ご参考までに教えていただきたいのですが、もし（１）から（４）、それぞれ分かるのであれば教えていただきたいです。","respondent":"佐藤保育事業担当課長","answer":"持ち合わせていないのですが、大体私立保育園ですと在園児数１００名以上の園がありますので、半年で５０万円以上になるかなと算定できます。１０万円いかないぐらいの金額ということになりまして、その程度の差は発生するものかというように認識しております。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"３番目の表によって、どのような内訳になっているのかお伺いしたいということと、請求があったときのその協議の内容についてお伺いしたいと思います。","respondent":"芝野保育入園調整課長","answer":"今回の契約変更におきまして議決額の５％を超えましたので、第２回定例会において契約変更の議決をいただく形になるかと思います。あくまでもこれ予定ですが、というような、今流れになっております。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"施設整備課のほうで詳細は担当されているということなので、そこは後で確認をさせてほしいと求めました。区が単独で補助を出すところがあるのかどうか、あると思うのですが、それは具体的にどこなのかをお伺いしたいと思います。","respondent":"佐藤保育事業担当課長","answer":"本補助事業の東京都の対象外の施設ですが、対象外の施設は、私立幼稚園および公設民営保育所等となります。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"１点確認をしたいのですけれども、都が対象にしなかった私立幼稚園に対して、ちょっとまず、すみません。もし分かればお伺いをしたいということと、逆になぜ区は補助をしようとしたのか、そこの区のお考えをお伺いしたいと思います。","respondent":"佐藤保育事業担当課長","answer":"本補助の目的として、事業者の方が値上げによる保護者の方への価格転嫁や、一体的に私立幼稚園も対象として実施する必要があると考えています。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"私立幼稚園側から、物価高騰によって保育の質の低下につながりかねないから補助してくださいという要望があったのでしょうか。そこを確認したいと思います。","respondent":"佐藤保育事業担当課長","answer":"正式に私立幼稚園協会等々を通じた要望というものはいただいてございませんが、幼稚園協会などの園長会などを参加するときには、物価高騰による影響というものは非常に強くあるというようなお声というものはいただいているところです。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"幼稚園協会側から要求、要望がないにもかかわらず、このように税金を投入するということですか。今回の対応をぜひ検証していただきたいと思うのですが、ご決意というか、お聞かせほしいと求めました。","respondent":"佐藤保育事業担当課長","answer":"補助事業の実施に関しては、区としての思い、しっかりと説明した上で実施させていただいてあります。一方で、委員のお話のように、その後の効果検証につきましては、区としてもしっかりと対応していきたいと考えております。","id":"exchange-007"},{"speaker":"山本副委員長","kind":"質問・要望","question":"１か月当たりで試算していて、６か月相当ということで、それを踏まえてどう考えていくのかということがあれば教えていただきたいということ。こういったところについてどのように設定されているのかということを教えてほしいと求めました。","respondent":"佐藤保育事業担当課長","answer":"区といたしましても、昨年１年間事業者が支払っている費用等々と消費者物価指数の動向を勘案して、妥当な数値であるというように認識しています。前回補正でご提案させていただいたときも、同様の考え方によって単価を算定しているものです。","id":"exchange-008"},{"speaker":"山本副委員長","kind":"質問・要望","question":"この合理的な金額説明ができるように決めてほしいと考えていますので、区民の皆様からのご質問などがあれば、しっかりと答えていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"今の質疑を通じて、先方から要望がないが、区の思いとして補助金を出すということでした。それで、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/178682?Template=document&Id=7057#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":10168,"voices":43}},{"id":"r07-20250527-5","meetingId":"r07-cm05","date":"2025年5月27日","dateIso":"2025-05-27","committee":"総務委員会","time":"午前１０時０７分～午後 ０時０９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"第６８号議案、専決処分の承認を求めること","agenda":"第６８号議案、専決処分の承認を求めること","exchanges":[{"speaker":"西本委員","kind":"質問","question":"４番の専決処分とした理由で、令和７年３月３１日ということなのですけれども、これはこのようなものなのですか。それはいかがか尋ねました。","respondent":"宮澤税務課長","answer":"やはり軽自動車税の種別割と、やはり３月３１日が公布日で４月１日が施行日ということで、専決処分をさせていただいたという過去の経緯があります。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"その流れは分かるのですけれども、３月３１日に決めて４月１日からということはあり得ないではないですか。ですから、このようなことをやられてしまうと、全部専決処分にすれば終わりなのという形になってしまうので、なぜこのようなものか、分かります。","respondent":"宮澤税務課長","answer":"地方税法の改正の内容というものが、いわゆる住民税に係るものなどがあります。そのうち、特に軽自動車税に係る部分というものが４月１日が基準日というところで、専決処分ということになる可能性が高いです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"そうやっていくことも必要なのかなと、この間、私たちもそれに対応していかなければいけなくなってきているのかななどということを少し感じました。国はやはり地方のことも考えてやってほしいなという要望も必要かなと、これは意見として言わせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"１番の概要の一番下に、現行の５０cc原付バイクは、伺いたいと思います。","respondent":"宮澤税務課長","answer":"その排気量、そこが５０cc以下のオートバイだと、今後新たな５０cc以下の排気量でのオートバイが生産されなくなってくる見込みです。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしたら、今５０cc以下の原付に乗っている方は、今後もずっと、もし大事に乗っていくという状況であった場合、どうなっていくのか尋ねました。","respondent":"宮澤税務課長","answer":"現在乗っていらっしゃる５０cc以下については引き続き乗っていけますし、引き続き５０cc以下原付としての登録もできるです。ただ、１１月以降は、新車での販売流通というものはなくなるということです。","id":"exchange-005"}]},{"id":"topic-02","title":"第６７号議案、令和７年度品川区一般会計補正予算","agenda":"第６７号議案、令和７年度品川区一般会計補正予算","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"５月の初旬に深刻な物価高騰から区民の命と暮らし・営業を守る緊急対策を求める申し入れを区長に対して行いまして、そして、やはり大本のところでは。","respondent":"加島財政課長","answer":"今後事業者とのプロポーザルを行いますので、アンケートの内容は詰めてまいりますが、必須項目になってくるものと考えております。９月、電気代支援が入ってまいりますことと、今区のほうではこちらの飲料水の配布による見守り支援を予算化させていただきました。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。何というのですか、引き続き熱中症予防という観点から、対策を進めていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"その残り２億何がしかのものというものは、プレミアム商品券ということで計算された形になっていますという理解でいいでしょうか。確認したいのですけれども。","respondent":"加島財政課長","answer":"高齢者福祉費の見守り支援としての２.８億円余、合わせての２.４億円余、１３ページのところに保育所の物価高騰対策支援を入れております。これは都補助ではなくて、区の一般財源での対応となりますので、その分での基金繰入金となります。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"そのような検討もなく、唐突に今の時期にポンと出てきたということはなぜなのですか。今回の補正予算も決めているわけだから、ある程度その辺の議論は所管とされているのではないかなと思うのですけれども、いかがか尋ねました。","respondent":"加島財政課長","answer":"それがなぜこの５月補正で対応するのかというところですけれども、予算編成後、気象庁のほうで今年の夏も猛暑という発表がなされております。経済対策として国が支援を発表いたしましたけれども、今回５月補正で飲料配布による高齢者の見守り支援実施の必要性があるということで。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"なぜ入れ込むことができなかったのですか。そのようなことで見切り発車するということは、私はどうかなと思うのですが、いかがか尋ねました。","respondent":"加島財政課長","answer":"つまり令和７年度に向けて、こういった熱中症対策の検討がなされなかったのかというご質問かと思いますけれども、検討はしてまいりました。今回５月補正、それから熱中症予防・見守り支援でいく中で、今回提案させていただいたものになります。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"１世帯につき幾らということが出てくるではないですか。そこの細かい計算はしているのか尋ねました。","respondent":"加島財政課長","answer":"配送は２回で終わらせるというようなご趣旨だったのかもしれませんが、本配送、不在配送というところの２回でまず見積りを取らせていただきました。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"１００％やりたいという意気込みは分かるけれども、状況を考えたりしたら、結果によっては非常に無駄が多くなるのではないですか。いかがか尋ねました。","respondent":"加島財政課長","answer":"は予算額の中で対応するということです。仮定の話にはなりますが、対象件数のほうが著しく伸びたり、契約金額の変更ということも恐らく必要になってくるのではないかと考えております。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"もしも被害があったらどうするのですかということ、それも想定していなければいけないですよね。ですから、そこの犯罪に対しての対応をどう考えるのか、区の責任はきちんと取ってくれるのですよねということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"蓋開けの、何かあるではないですか。そのようなことをなぜ考えた上でやらないのかな、私はこれに関しては準備不十分、意見を言わせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"今回配達時に１回だけ見守るということですが、その方をケアできるような、そのような人たちを私は選んでもよかったのではないかなと思います。質問というよりは意見だけ言わせていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"先ほどの質問の答弁をいただきたかったので、安全面の保証の件と、区の責任はどこまでありますか。それから蓋の件、法で決められるということではないと思うのですけれども、その２つ、ご答弁お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"新妻副委員長","kind":"質問","question":"委託料ということで、これは商品代がここに含まれているということの理解でよろしいでしょうか。そうすると、お一人当たり８,０００円分、金額に換算すると８,０００円相当の支援というように受け取めてよろしいのか尋ねました。","respondent":"加島財政課長","answer":"見守り支援としての委託ということを考えているところです。その１２本を２回分、２４本で、配送料も含めて４,０００円相当という形になります。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして品川区からも飲料が届くとなったら、もう大分安心なのではないかなと思いますので、そういった面も考えてほしいと求めました。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"松本委員","kind":"意見","question":"そしてどうするかと考えたときに、人と人というものは、高齢者の見守り事業というものはもう１回整理してもいいのではないかと考えております。このようなこともいろいろ、課題はあるということは私も認識しておりますが、本件については一応賛成というように申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"そのロスはよしとするのですか。いろいろな必要なものがあるではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/121362?Template=document&Id=7065#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":18362,"voices":65}},{"id":"r07-20250527-10","meetingId":"r07-cm05","date":"2025年5月27日","dateIso":"2025-05-27","committee":"議会運営委員会","time":"午後 ２時１４分～午後 ２時１７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/350163?Template=document&Id=7059#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":1311,"voices":11}},{"id":"r07-20250609-6","meetingId":"r07-cm06","date":"2025年6月9日","dateIso":"2025-06-09","committee":"区民委員会","time":"午後 １時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"藤原副委員長","kind":"意見","question":"それが一番今は感激しております。今後ともとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"区民保養所のあり方検討の開始","agenda":"区民保養所のあり方検討の開始","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"私から１点だけお伺いします。外部有識者を交えた検討体制による検討を行うということですが、どういった方を予定されているのか尋ねました。","respondent":"平原地域活動課長","answer":"現在どういった方がいいのかといったところを内部で探している状況ですけれども、これは例えばですが、保養所事業についてお詳しい方や、建物ですので、土地、建物などの資産に詳しい方、そういった方々を中心にお願いできればと考えているところです。","id":"exchange-002"},{"speaker":"おぎの委員","kind":"意見","question":"その中で検討期間中に２回程度会合を実施ということですが、他区における保養所事業の状況なども調査しながらと書いてありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"こんの委員","kind":"質問","question":"どのような背景で、もっと前からこの検討会はあってよろしかったのかなと、私はそのような感じがしているのです。今この時点でこれが始まったという、その経緯と背景を説明するよう求めました。","respondent":"平原地域活動課長","answer":"近年におきましても、運営形態がどういったものがあるのかといったところの内部検討は行ってまいりました。予断を持たずに検討したいというようなところをもちまして、改めて検討し直してみようということで、このタイミングで行うものです。","id":"exchange-004"},{"speaker":"こんの委員","kind":"確認","question":"今ご説明があった、そのタイミングだということで、なぜそのタイミングということは分かりました。これまでどのような区民の方へのアピールなり、利用促進に取り組んでこられたのか、改めてその辺を確認したいと求めました。","respondent":"平原地域活動課長","answer":"そういったところに固定客がつくような取組も一緒にさせていただきまして、宿泊した際にそういったご紹介をさせていただいてきたところです。今言った、今回の検討ではそういったところの周知の仕方などをどのようなものがあるのかということは、今ご説明のとおりです。","id":"exchange-005"},{"speaker":"こんの委員","kind":"質問","question":"その辺のところがやはり、今後検討していくに当たって事業形態をどうするのかといったところも、さっきお声も出ておりました。このような形で運営してもらいたい、検討を進める必要があるのではないかと考えるのですが、その点についてはいかがか尋ねました。","respondent":"平原地域活動課長","answer":"様々な形態をたどってまいりましたけれども、やはり課題を踏まえまして、そういった変更を行ってきたところです。どのようなやり方があるのか、そういったところを全て勘案して、今後どのような道があるのかといったところをまず始めてまいりたいと考えています。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"提案","question":"事業者もいろいろ季節の食べ物、お食事にしても、結構いろいろと提案されていて、お泊まりになる方もそれを楽しみにしている方もいるわけです。会議体として、協力と書いてあるから、どのような関係性で協力体制を取るのかということをお尋ねさせてほしいと求めました。","respondent":"平原地域活動課長","answer":"大きな利用主体としての教育委員会のお話もやはり一緒になって進めていかなければといったところで、協力という形の下、一緒にやっていくというように捉えていただければと思います。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問","question":"教育委員会と協力体制を取って、あくまで教育委員会、あと現場は現場の学校管理者がいるわけではないですか。校長先生など学校側の現場の方も、その会議体の中に入れて発言をしてもらうという認識でよろしいか尋ねました。","respondent":"平原地域活動課長","answer":"実際の検討につきましては、だんだん議論を集約していきたいという方法を考えてありますので、そういったところはあるのかなと考えているところです。","id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで、３か月の期間があって２回程度と会合がなっているではないですか。集約して、おおむねこの２回で大体その検討というものはまとまるのかなと、それが３回になる可能性もあるということでいいのですよね。","respondent":"平原地域活動課長","answer":"それ以外につきましては私どもが個別で説明するとか、今は２回と考えているのですが、程度ということで今回資料上させていただいたところです。","id":"exchange-009"}]},{"id":"topic-03","title":"しながわシティラン開催報告および次回開催に向けた進捗","agenda":"しながわシティラン開催報告および次回開催に向けた進捗","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"そのようなご配慮などはされていたのかなという点がまず１点と、２点目が、また課題についても教えてほしいと求めました。視覚障害など、その点についてどのような体制を取っていくのかという、この３点について教えてほしいと求めました。","respondent":"守屋スポーツ推進課長","answer":"先日も説明させていただいて、気をつける点があるというところを意見交換して、今回の開催にそこを反映させていきたいと考えているところです。","id":"exchange-010"},{"speaker":"ひがし委員","kind":"質問・要望","question":"昨年度の議事録を確認していくと、自転車で２人１組になって、どのような方法を取っていたのかなというところの具体のお話を聞きたいなと思います。","respondent":"守屋スポーツ推進課長","answer":"医療学生が２名１組で自転車で移動観察を行うというものを５隊設定しまして、レース中に移動して、そういった体制を整えておりました。２点目の、２０２６大会、できるだけ参加者の方々に満足していただけるような形で進めていきたいと考えております。","id":"exchange-011"},{"speaker":"ひがし委員","kind":"質問・要望","question":"３００人ぐらいは参加できる幅があるということでいくと、１点、あそこは少し危なかったかもなというようなご意見がありました。今回と次回と、そこの混雑状況などについては把握をしていると思うのですが、その改善案があれば教えてほしいと求めました。","respondent":"守屋スポーツ推進課長","answer":"本年度大会につきましては、最初から１車線にするというところで、まずは人がたまらないような形をまず１つ考えております。５分間隔を空けてスタートさせるという、１,５００人と１,０００人というところで、ランナーの渋滞の緩和を図ろうと考えているところです。","id":"exchange-012"},{"speaker":"おぎの委員","kind":"質問","question":"実行委員会がまた今年度も既に立ち上がって、次回に向けて既に話合いが持たれているということですが、前回参加された方からも、アンケートなどというものは取られているのか尋ねました。","respondent":"守屋スポーツ推進課長","answer":"現状５０９件と把握しておりまして、サービスともに、およそ約８０％の方に「満足」「とても満足」というところでご回答していただいております。","id":"exchange-013"},{"speaker":"おぎの委員","kind":"質問・要望","question":"先ほどの２車線や、幅の部分で見直せる部分があったら見ていただきたいなということと、または何かイベントがあったらいいのかなと思います。次回も。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問・要望","question":"今後の予定の中に９月から募集をということですけれども、役務内容、要所要所に多分立つ方などいたと思うのですが。お声をいただいているかどうかといった点、その辺の当日のボランティアについての活動の総括について教えてほしいと求めました。","respondent":"守屋スポーツ推進課長","answer":"関係団体のボランティアが１３０名程度、町会のボランティアの方が１２０名程度ということで、この場をお借りしてお礼申し上げたいと思います。","id":"exchange-015"},{"speaker":"こんの委員","kind":"質問・要望","question":"その辺の体制を取っていただいて、今年度も楽しくボランティアの方たち、１５０名が集まっていただくようにお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/541601?Template=document&Id=7081#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":39551,"voices":86}},{"id":"r07-20250609-7","meetingId":"r07-cm06","date":"2025年6月9日","dateIso":"2025-06-09","committee":"厚生委員会","time":"午後 １時００分～午後 ３時２３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"議会運営委員会でも何度か確認をしたのですけれども、それについては当委員会で議論してもいいということでよろしかったのかどうかが１点。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど時期、ごめんなさい、７月とおっしゃっていましたか。もう一度、対象の方がどれぐらいいるのかということと、送付の時期について説明するよう求めました。","respondent":"山下国保医療年金課長","answer":"時期につきましては、国民健康保険につきまして、令和７年７月中旬以降を目途に送付を予定しています。国民健康保険におきましては、おおむね半々ぐらいの方に資格情報のお知らせと資格確認書をお送りするような形で、今準備を進めているところです。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ品川区としても、全ての国民健康保険加入者に資格確認書を交付していただきたいと思うのですけれども、そこら辺のところは検討はされたのか。ぜひそうしていただきたいと思うのですけれども、いかがでしょうかということでお願いします。","respondent":"山下国保医療年金課長","answer":"マイナ保険証を基本とする仕組みに昨年１２月より変わった中で、資格確認書というような形で、法律の条文上も例外的な取扱いとなっているところです。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ほかのところで質問させていただきたいのですけれども、体制強化したところはどういう思いで体制強化されているのかということも伺いたいと思います。","respondent":"松山障害者支援課長、菅野高齢者福祉課長","answer":"そのニーズに応えるために、また、今年度、国の制度でも就労選択支援という新たな制度が始まってまいります。緊急的にサービスが必要な場合には、ケアマネジャーのほうで暫定プランという形で対応はしていますので、そのような形で対応させてもらっております。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"２ページのところで、会計年度任用職員というのは、これは常勤換算の人数ということで考えていいのかという点についても伺いたいと思います。長寿お祝い金のことで伺いたいのですけれども、この３ページを見ると、これに対しては区としてどう考えられているのか。","respondent":"東野福祉計画課長","answer":"組織のところの体制強化のところ、福祉計画課のところも説明したと思っていたのですけれども、再度説明させていただければと思います。ほかにつきましては、各課のほうからという形になりますと、なかなか長くなると思いますので、個別にお聞きいただければと思います。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"去年傍聴したので何となくは分かるのですが、その辺のことが書かれていないというのはどういうことなのでしょうかというのを率直に聞きたいです。","respondent":"松山障害者支援課長","answer":"相談支援部会、子ども支援部会、就労支援部会に加えまして。それから、開催回数としましては２回を予定しています。","id":"exchange-006"},{"speaker":"やなぎさわ委員","kind":"質問","question":"大枠でお伺いしたいのですけれども、電子だと６５ページのところなのですけれども、新しいセクションをつくったりというようなことで進められているという理解でよろしいか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"介護人材不足のことにつきましては、喫緊の課題ということで区としては捉えております。やはり外国人人材というのは大変貴重な要員だと考えていますので、区としては、事業者が受け入れられるように支援をしていきたいと認識しております。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"予算が４億４,６４０万円を組んでいたのですけれども、７割弱になったことで、教えてほしいと求めました。実際は２０時間というのが、移動時間も入れて２０時間にするとか、その点についても伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"営業所は対象にならないと言われたということで伺ったのですけれども、そこのところは確認させてください。２０時間というのは、せめて移動時間も含めたようなことでもぜひ検討いただきたいということで、これは要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問","question":"ここで聞かないと聞くときがないので。これ、大きなところなので、ぜひそこのところがどのような形で検討が進められていくのかということを教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ代わりのところを確保していただきたいと思っていまして、そこでは高齢者の医療ショートステイとかは受け入れていた経過があると思うのです。幾つかそういう病院はありますので、ぜひそういうところで進めていただきたいと思っているのですが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"私どもも、この森山リハビリテーションクリニックの休止については、非常に驚きとともに、今後、本当に何とか区内で医療ショートステイ事業を実現させるためにも、区内の様々な医療機関にさらに積極的に働きかけを行ってまいります。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/166682?Template=document&Id=7079#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":45174,"voices":92}},{"id":"r07-20250609-8","meetingId":"r07-cm06","date":"2025年6月9日","dateIso":"2025-06-09","committee":"建設委員会","time":"午後 １時００分～午後 ２時４０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"建設委員会ですから、建設的な議論をしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"東京都と品川区でどのような取決めで派遣してもらっているのかなども伺いたいと思います。東京都で経験されてきた主な略歴というのですか、どういった業務を経験されて品川区に来ているのかというのを伺いたいと思います。","respondent":"高梨都市計画課長、鴇田都市整備推進担当部長","answer":"東京都の仕事のやり方、まちづくりにおいても円滑な事務遂行に非常に有効であるといったところから開始をさせていただいているです。それぞれ派遣している場所によって開始の年代は異なりますが、そういった理由で派遣をしています。経験ということでご質問がありましたので、私からお答えします。品川区以外にもほかの自治体に行ったり、また国に行ったり、民間に行ったりというところで、経験をこれまで積み重ねてきたところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"２年ごとに入れ替わるみたいなそういうルールがあるのか、聞かせてほしいと求めました。そこら辺、私は委員会に今後報告すべき事項だと思うのですけれども、区の認識はいかがか尋ねました。","respondent":"高梨都市計画課長","answer":"２年ごとに代わっている、必ず２年ごとに代わらなければいけないといったようなルールがあるのかというのは把握していないところです。分科会の開催有無にかかわらず、当委員会のほうには報告をさせていただきたい、そういう回答です。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"何か取決めなどはあるのでしょうか。現在就任されている担当部長の自衛隊での経験されてきた主な任務というのはどのようなものだったのか、こちらも伺いたいと思います。","respondent":"羽鳥防災課長、七嶋災害対策担当部長","answer":"１０年前からこの制度が開始されていまして、現在の七嶋部長で３人目という形になってあります。先ほど、災害におきましては一般災害、いわゆる風水害の災害派遣等にそれぞれの部隊におきましてスタッフまたは部隊長として参加をいたしております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"改めて今回は両部長のところについて伺わせていただきました。私からは以上になります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"再開発問題というのは、このまま今までのようなやり方で進めていいのかということがあるので、ぜひ所管事務調査に入れていただきたいという意見です。前段の道路大会の件についても一言いいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"意見","question":"品川区でもトイレ確保管理計画が策定されて、空白地帯とかも示されて、ますます重要視されてきているところだと思います。木密の整備についても含めて、災害の対応について案として挙げられればと思いますので、お願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"せっかく良いことだと思っているのだけれども、議会のほうに説明や、議長はさすがに出席されているのですか。全然分からないので、何があったのだというのが正直なところなので、少し説明だけいただいてよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"松永委員","kind":"質問・要望","question":"私もやはり南海トラフ地震とか大きな地震が迫っている中で、こうした緊急対策としては災害、先ほどのゆきた委員と同じように、災害防災のほうに入れていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"再開発を進める区の説明を伺うと、いわゆる災害だったり防災。それぞれ両方持ち合わせているところだと思いますので、ぜひ再開発についても、まちづくりという点で防災対策に加えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"安藤委員","kind":"提案","question":"やはりこれは耐震化とかですごく重要な要素になってくるので、埼玉県の八潮市に視察に行く。所管事務調査と併せてそういったことができると良いのではないかと提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"意見","question":"特に甚大な被害があった輪島市とかの行政の取組姿勢とか、今後の対応の仕方というのを学ぶのも非常に参考になるかなと感じていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"中塚委員","kind":"提案","question":"２人の意見はとても良い意見、提案だと思うのですけれども、区民の関心が引き続き高いと。さらには長野県飯田市における駅周辺の開発、もしくはまちづくりのそれぞれの取組が把握できたらと思いますので、提案をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/570689?Template=document&Id=7077#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":32618,"voices":81}},{"id":"r07-20250609-9","meetingId":"r07-cm06","date":"2025年6月9日","dateIso":"2025-06-09","committee":"文教委員会","time":"午後 １時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井副委員長","kind":"意見","question":"副委員長の筒井ようすけです。１年間どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認なのですけれども、事務事業概要、１５ページの学校施設のところで、いろいろ改修などもありますけれども、プールの問題です。２８ページの学校給食のところで、現場との調整など、現在の状況を伺いたいと思います。","respondent":"荒木学校施設担当課長、石井学務課長","answer":"昨年度の各学校のプールの実施状況なども踏まえまして、まとまりましたら、また皆様にご説明させていただきたいと考えております。令和８年度以降、こういったシステムの選定のプロセスを含めて、現場には丁寧に説明していきたいと考えているところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"ＰＦＡＳの関係とか、今回、これは地域の方とかと話し合って実施していくということでよいのかということを改めて確認させてほしいと求めました。そこを伺いたいのと、令和５年度は７９９人だったと思うのですけれども、令和６年度の人数が分かれば伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"２か月たって空いているところはないのかどうか心配になってきますので、ぜひそこの確保をしていっていただきたいと思うのですが、状況を伺います。今、区としての不登校対策、どこに課題があると考えているのか伺いたいと思います。","respondent":"酒川指導課長、丸谷教育総合支援センター長","answer":"年度が始まってから、病気休暇ですとか休職もちらほらと始まっている現実はありますので、東京都とも連携して、人材の確保、補填に努めていきたいと考えています。昨年度から取り組んでおります不登校対策によって微増に抑えられたと現在捉えているところです。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、さらに小学校でも３０人学級と進めていっていただきたいと思うのですが、ぜひそうしたところで区としても進めていってほしいと求めました。少人数学級と多忙化解消を進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、校長先生や副校長先生のマネジメント努力というのでしょうか、どのようにして仕事している方々にお話ししているかを伺いたいと思います。相当な教員以外の方がたくさん働いているので、そこのところだけ内容を説明するよう求めました。","respondent":"酒川指導課長","answer":"たくさんの外部人材が入っていますので、１つは、こういった方々の勤務についてのマネジメントは副校長がやっております。個別に見られた課題についての情報を発信して、各学校において、よりよく機能していくように働きかけを行っていきたいと考えております。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問","question":"その辺のギャップをどう埋めていただけるかというところを、少し分かりにくいですか、すみません。","respondent":"酒川指導課長","answer":"やはり校長、副校長レベルで吸い上げて、現場で有効活用していくということになるかと考えています。そういった力を存分に発揮しているというようなところもありますし、子どもの支援についても一存あるというようなところも聞いております。","id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"学校のために、そういう方をぜひフォローして、学校全体の教育活動がよくなるようにお願いします。これは要望です。","respondent":"佐藤子ども未来部長、三輪子ども育成課長、柴田子ども施策連携担当課長、吉野子ども家庭支援センター長、柏木子育て応援課長、芝野保育入園調整課長、染谷保育施設運営課長、佐藤保育事業担当課長","answer":"子ども未来部の令和７年度事務事業概要について、ご説明申し上げます。以降、各課の事務事業につきましては、各課長よりご説明申し上げます。（３）番ですが、子どもたちの多様な意見を聞き施策に反映するため、品川区こども会議を実施いたします。１つ目は、フリースペースを設置し、その保護者のサポートを実施しております。関係機関との連携と、関係者が児童に関する情報や考え方を共有し、適切な連携のもとに対応していくことを目的として設置されております。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"すまいるの環境整備について、今、区のお考え、どうよくしていこうとしているのか、そこを伺いたいと思います。１０３ページの区内保育園等のあり方についてなのですけれども、つまり、区立保育園を減らしていくということなのか伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"区立保育園はなくさないようにしていただきたいと、さらにこの役割が重要になってきていると思うので、要望しておきたいと思います。何か具体的な環境をよくしていく手だては、今、お考えがあれば伺いたいと思います。","respondent":"三輪子ども育成課長","answer":"リソースはやはり学校の中ということで運営を考えている中では、やはり学校施設の活用が大事になると思っています。そういった中でも活用できるような部屋は、学校の管理職も含めて、教育委員会とも連携しながら模索していく必要があるとは考えているところです。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"生徒がたくさんいると、いろいろ妨害とまではいかないかもしれませんけれども、グレーゾーンの子たちとか、そうした子どもたちがやはり安心して遊べないような状況にもなりますので、ぜひ子どもたちに適した環境を整備していっていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"虐待相談とかは約６００件ですか、１人当たり、ケースが何件なのかも伺いたいと思います。それで今の人材配置が十分なのかどうかというところを伺いたいと思います。","respondent":"長谷川児童相談課長","answer":"子ども会議の実施状況についてのご質問ですけれども、できる限り対応を図っていくというところで、毎週定例で実施しています。それから、人材の確保ですけれども、紙の５ページ、データの８ページになりますけれども、先ほどご説明しましたとおり、法定数の確保は済んです。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそうした子どもたちの意見を聞きながら、引き続きやっていってほしいと求めました。それと、やりがいを感じられるようにやっていっていただきたいと、子どもたちがしっかりと成長できるようにしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"どういう課題というか問題が起きるのかということと、何らかの方策を考えられないものなのでしょうかという、その辺りはいかがか尋ねました。","respondent":"長谷川児童相談課長","answer":"お子様の状態によりまして保護をするわけですけれども、所長の方針もありますけれども、必要な保護は必ずすると。職員の育成をどんどん進めていくと同時に、保護の期間を適正な保護期間にしていくように力をつけていけるようになればいいとも思っております。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"２３区全体、あるいは東京都との協力というか、そちらも踏まえて進めていってほしいと求めました。その点が出てくると思うので、ぜひ、今お話があったような形で進めていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"その後それがどうなったのでしょうかという、何か大きなノロだとか、そういうものも何かあったのでしょうかということが１つ。それからもう１つ、それについてのご説明をいただければ、今分っている時点で結構です。","respondent":"石井学務課長","answer":"各保護者からアンケート調査を実施して、そういったことも含めて保健所の調査を実施した結果、生徒等も含めて感染が広がったものであろうと。消毒作業を実施しまして、２日間の臨時休業を経て、生徒の皆さんは元気に学校に通っている状況です。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"意見","question":"すみません、新聞の報道であったので、品川を含め、ほかの二、三区で、あと私立の学校でも殺害予告が来たということがあったのでお尋ねしたので、また詳細が分かったら、報告してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"意見","question":"警察が把握している、警察に新聞社が取材をしたか、警察の発表を聞いたということです。新聞の報道では、東京都教育委員会がということではないですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"のだて委員","kind":"意見","question":"報告書を公開してほしいという希望の方もいて、そうしたところも見ながら、区としてどういったことが必要なのかというところをできたらと思います。まずは不登校にならないということと、あとは、通いやすいような学校にしていくということでできたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/178682?Template=document&Id=7075#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":35407,"voices":107}},{"id":"r07-20250609-5","meetingId":"r07-cm06","date":"2025年6月9日","dateIso":"2025-06-09","committee":"総務委員会","time":"午後 １時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それのスケジュールなどが少し分かればお聞きしたいということと、それがどれぐらいあったのかというのが、数字が分かれば教えていただきたい。ではそこも少し踏まえて、どこでどういう介入のされ方をしてくるのかというのを伺いたいと思います。","respondent":"佐藤経理課長、木村人権・ジェンダー平等推進課長、宮尾人事課長、小林新庁舎建設担当課長","answer":"夏ぐらいから議論を開始していただきまして、大体年末ぐらいにかけて、諮問に対する答申をいただきたいというふうに考えております。昨年度、７月１日から開始したところではありますが、昨年度中には１件もなしということになります。公募によらない再度の任用制度ですが、こちらは導入に向けて今、前向きに検討させていただいているところです。それと、２点目の介入ですが、基本設計、実施設計と進めてきているところですけれど、これは全ての期間におきまして関与されている状況です。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"翌３月ぐらいに告示されるということですので、全ての職種の方々に適切な額がしっかりと渡るようにやっていただきたいなというふうに思います。人事のところでは、ぜひ早急に、というのはもうお答えいただいていますので、よろしくお願いしますというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"２年前ですか、具体的にはどういう成果があってどういう方向に持っていくのかということを、少し具体的なところを簡単でいいのでお示しください。これは要望になりますけれども、品川区の財政がどうなっているのかというのが見えないので、そこら辺を教えていただきたいです。","respondent":"崎村企画課長、加島財政課長、西澤ＤＸ戦略担当課長","answer":"区だけで行っているものではなくて、国においても、引き続きそういう取組を進めていきたいと考えているところです。私どもといたしましては、その３０年先の財政シミュレーションに取り組んでいくに当たって、基本を整理していくかというところで取り組んでおります。私のほうから、ＥＢＰＭの推進について説明します。統計データ、人口データといった様々なデータを用いながら、政策に活かしていくことを考えております。","id":"exchange-003"},{"speaker":"西本委員","kind":"提案","question":"そして質問は、区のどの部門にも属さない事象というのはどんなものがあるのですか。そこのちょっとした例などをいただけるとそういうイメージ湧くのかなと思うのですけれど、いかがか尋ねました。","respondent":"崎村企画課長、藤村総務課長","answer":"当然全国一律でそういったサービスを提供されているものというふうに考えておりますけれども、もう一方で、考えていく必要があると考えています。あれは危機管理対応の一例というところではあるのですが、なかなか明確ではないというところなので、総務課で担当したというような例があったりするというところを指しているものです。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"総務課でやるのだったら分かるのです、総務課というのは総務課なのでしょうけれど、でもほかの担当の方が非常に判断しづらい。何でもいいから言ってきて、という状況になってくるのか、この辺の仕切りはどういうふうになっているのか尋ねました。","respondent":"藤村総務課長","answer":"連携等のご指摘というところですけれど、どういった課が主導権を持つかというところがやはり不明確である事象が出てきた場合の対応といたしましては、そこの流れによるものは総務課のほうで担当していくというような形で対応していきたいと考えております。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"カスハラの問題もありますが、一人で悩んでいる方とかに対するフォローとか、そういうものはどうなっているのですか。ということになるとなかなか言いづらいとは思うのですけれど、それは大丈夫でしょうかという、最後のお尋ねです。","respondent":"宮尾人事課長","answer":"直接職員に言うのがはばかられるという職員もいるかと思いますので、今は外部に相談窓口を委託でつくっております。目安箱がなくなったからというふうにならないような、様々対策を講じながら、しっかりと職員の声を聞いてまいりたいと考えています。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"ということは、外部の窓口がいろいろあるので目安箱をなくしたという認識でよろしいのですか。なくなった理由を説明するよう求めました。","respondent":"宮尾人事課長","answer":"その組織の中で、上司のほうに相談をしてというような、そういった相談の解決の方法というのもあるのではないかというふうに思います。自分の組織、例えば職員の悩み事に対してその組織全体で解決をする、こういった力というのも大切にしていきたいというような思いもあります。","id":"exchange-007"},{"speaker":"須貝委員","kind":"確認","question":"渋谷区と世田谷区がマイナ保険証の有無に関わらず国民健康保険の加入者全員に健康保険証と同様に使える資格確認書を独自に発行することを決めました。渋谷区だけでも４万６,０００人、世田谷区がおよそ１６万人、資格確認書を順次発行するというふうにあります。","respondent":"横田デジタル推進課長","answer":"その１週間ぐらい前の通知に、基本的に資格証明書を全員出すものではないという通知がございました。急遽１週間で方向転換したので、あとは健康推進部で調整して、近いうちにどうしていくかというのを出していくというふうに考えております。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"２点目は、何かいじめの重大事件がまた、何件か発生したというような話が聞こえているのですが、これは事実ですか。それを説明するよう求めました。","respondent":"川村コンプライアンス推進担当課長","answer":"いじめ重大事態の件数についてです。累計で申し上げますと、令和４年度からの累計で２４件、うち令和６年度は５件というふうに把握しております。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"それで、令和７年度に入ったばかりですから、令和６年度はいろいろ対応策を考えて、事業部もそれぞれ編成したわけですよね。それに対して、様々な手法、対応をしているにもかかわらず、やはりどんどん増えているといったような状況なのか尋ねました。","respondent":"川村コンプライアンス推進担当課長","answer":"増加傾向にあるかというところで申し上げますと、いじめ重大事態は、令和５年度に比べて令和６年度のほうが減っております。認知件数自体は、申し訳ございません、区長部局ではそこまで報告をいただいていない状況です。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"監査もするというのは何か少しおかしな気がするのですが、区としては、これはこのまま続けるつもりですか。説明するよう求めました。","respondent":"黒田監査委員事務局長","answer":"識見を有する監査委員といわゆる議選監査委員から設置されるという構成で、引き続きこの制度で、運用されるものというふうに事務局としては考えておるものです。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"そういう間違いがだんだん顕著になって、品川区はこのまま、やはり地方自治法にのっとって続けるおつもりですか。もう一度答えるよう求めました。","respondent":"黒田監査委員事務局長","answer":"繰り返しになりますが、監査委員制度につきましては、法令に基づいて運用されている制度ですので、これに基づいて運用していくものというふうに事務局としては考えているものです。","id":"exchange-012"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"確認","question":"確認です。もう一度確認したいのが、それも全部特別委員会だから、総務委員会では扱えないということですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"私としては、財政について、調査をしていただきたいと考えています。３０年先を見据えた、これは調査していただきたいというところで、ぜひお願いしたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"山本委員","kind":"意見","question":"そのやり方等については、ぜひ、もし調査対象になるようでしたら協議をさせていただければいいのかなと。入りのところもどこまでやるかというのは、そこは検討かなというところで……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"庁舎は庁舎であるのだけれども、学校改築とか公有地とかいろいろあるではないですか、それ全体が知りたいのです。全体の財政として品川区の財政どうなっているのですか、どういう方向になっている、プラスアルファで考えておかないといけないねとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"西本委員","kind":"意見","question":"ただ、職員の方々が元気になってほしいのです。ただ、少し気になっていることなのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"いろいろなところを視察しながらお話を伺うというほうが、よりベターな視察になり、そういう方向で進めていただけるとありがたいなと思います。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"西本委員","kind":"提案","question":"ぜひそういう観点で提案、結構共通した悩みとか問題点とかがいろいろあるので、広げて考えていただくのが一番いいのかなと思っています。ぜひ、所管事務調査に関わるような視察先の検討をお願いしたいと思いますとの意見を述べました。","respondent":"石田（秀）委員長","answer":"先ほど言いましたように６月１６日に、何かあれば、６月１６日までにそれも出してくださればありがたいと考えています。そういう形でいきたいと考えていますので、６月１６日、一応、ぜひよろしくお願いいたします。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/121362?Template=document&Id=7083#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":38832,"voices":155}},{"id":"r07-20250610-21","meetingId":"r07-cm06","date":"2025年6月10日","dateIso":"2025-06-10","committee":"子ども若者支援・共生社会推進特別委員会","time":"午後 １時００分～午後 ２時０６分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"ゆきた副委員長","kind":"意見","question":"副委員長を務めします公明党のゆきた政春です。１年間、どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"子ども・若者のほうで伺いたいのですけれども、３ページのところで表の見方を教えていただきたいのですが、そのことを教えてほしいと求めました。","respondent":"染谷保育施設運営課長、佐藤保育事業担当課長","answer":"１点目の、幼稚園の特別支援教育・巡回相談ですが、９園に対して複数のお子さんが実際に在籍をしているという考え方です。こちらの位置づけについては、実際にお子さんに対して何か支援をするというよりは。保育所等訪問のご質問についてお答えします。保育所等訪問は、ふだんの様子というのを見に来ていただく事業でございまして、子ども未来部で対応している事業ではないところです。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"臨床発達心理士というのは、私たちもいろいろな団体と懇談させていただいたときに伺ったのが、この制度ということで捉えていいのでしょうか。その辺の（イ）と（ウ）の違いというのも、仕組みとしてどういう違いなのかというのを教えていただけたらと思います。","respondent":"染谷保育施設運営課長","answer":"臨床発達心理士につきましては、その１名の方にお願いをしておりまして、学校心理士につきましては、区立に関しては４名の方にお願いをしています。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問","question":"重層的支援体制について伺いたいのですけれども、それが本格的に始まったというのは、いつから始まったのかということを伺いたいと思います。こういう整備事業実施計画というのは、区としてはつくられているのか、その点についても伺いたいと思います。","respondent":"東野福祉計画課長","answer":"先ほどもご説明させていただきましたとおり、令和３年度から取組を開始いたしまして、今年度から本格実施となっています。今年度本格実施という現状ではありますが、その辺を踏まえた形で、今年度実施計画を策定するかどうかにつきましては検討をしてまいりたいと思います。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"これから計画とかをつくると全容が見えてくるかと思いますので、ぜひそのときはこちらにも報告をしていただけたらと思います。そこのところでは、品川区としては重層的支援会議というのはどういう状況になっているのか、メンバーとかも併せて教えていただけたらと思います。","respondent":"東野福祉計画課長","answer":"重層的支援会議、それから支援会議という２つの会議体がございまして、重要な支援が必要だと上がってきたものについては支援会議というところで。","id":"exchange-005"},{"speaker":"つる委員","kind":"意見","question":"重層で捕捉する孤独・孤立と２つあって、今後どういう形でその辺りを捉えて、あと現場ではどのようにしてやっていくのかというところの整理を聞きたいと思いますとの意見を述べました。","respondent":"東野福祉計画課長","answer":"この特別委員会で、重層的支援体制、それから若者に関することの中に、孤独・孤立対策についてという項目がありますので、こちらに関することにつきましては、こちらの特別委員会へご報告をさせていただきたいと考えています。","id":"exchange-006"},{"speaker":"つる委員","kind":"意見","question":"これはどういうふうになるのかなということと、品川区でどうかというのは、この中で質疑できたらと思います。そこはどうなっているのかということと、あとは現場レベルでどういう対応、どのようにしてやっているのかというのも含めて聞きたいですねとの意見を述べました。","respondent":"せお委員長、東野福祉計画課長","answer":"今後取り上げていく内容につきましては、この後のその他で皆様からのご意見をいただきますので、そこで取り上げたいと考えていますが、現状の体制など、お答えできるところをお願いします。直接的な所管というよりは、そのものを扱っている部署がありますので、そちらとの連携という部分が必要だと思っているところです。情報共有をしながら、どんな対策ができるかにつきましては連携していきたいと考えています。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"趣旨は違うのですけれども、今年の夏には、暑さ対策と高齢者の空調をしっかり使っていただくという目的で、飲物のアウトリーチがあります。","respondent":"寺嶋福祉部長","answer":"一つの新しい考え方として重層的支援体制整備、これがいわゆる相談支援だけではなくて、参加支援をやったりする。相談支援部分では、先ほど参事からもご説明しましたけれども、庁内のいろいろな部署の係長級が集まって支援会議をやっていると。","id":"exchange-008"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"つる委員","kind":"質問","question":"できれば利用者の方の声も伺いながら、この委員会で次のステップについて、議論していきたい。２３区とか都内とか近県かなと意識していますけれども、そういう既に取り組んでいる場所があれば、そういった場所をぜひ見に行けたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問","question":"委員会でまたお話を伺うということもあると理解が進むかなと思うのと、それから、品川区独自のすごく先進的な取組だと思うのです。そこのところも、実際にされている受けたところからお話を伺えたら、そういうところを委員会としてもご検討いただけたらありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問","question":"重層的支援体制というのは、品川区は今年度から本格的にということですけれども、既に２３区でも、もっと前からされているところがあります。そういうところが、深まっているところがあれば、そういうところを視察してお話を伺うというのも参考になったりするかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"西村委員","kind":"質問・要望","question":"私もぜひ視察はお願いをさせていただきたいと思うのですけれども、今日お話を伺っていても、一旦そこを整理してみたいという思いはあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/170663?Template=document&Id=7085#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":19409,"voices":58}},{"id":"r07-20250610-20","meetingId":"r07-cm06","date":"2025年6月10日","dateIso":"2025-06-10","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午後 １時００分～午後 ２時００分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"幹部職員のご紹介","agenda":"幹部職員のご紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"しながわ未来の筒井ようすけです。どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"公有地なのですけれども、区としての現在の活用検討する上でのスケジュール感といいますか、それをそれぞれ教えていただきたいというのが１つ。行政評価なのですが、これはなぜこのタイミングで報告なのかというのと、何を目的として報告するのかというのを説明するよう求めました。","respondent":"吉岡政策推進担当課長","answer":"検討状況ですけれども、令和５年度から本格活用に向けて検討を進めてきたところでございまして、ＰＦＩ事業で進めているです。４番目の平塚二丁目寄付物件につきましては、先ほど申し上げたように建物除却工事を行う予定ですので、活用に向けて検討していくです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"教えていただきたいのと、もしあるのであれば、ご紹介していただきたいというのがあります。区としてのスタンスを改めて確認させていただきたいのですが、どのような意見を国に区として述べているのか説明するよう求めました。","respondent":"吉岡政策推進担当課長、西澤ＤＸ戦略担当課長、横田デジタル推進課長、宮澤税務課長","answer":"従前からご説明させていただいている部分にもあるのですけれども、事務事業評価シートを１年の中で初めて議会に提出するタイミングです。初めに、適用期間といいますのは、ＤＸ推進基本計画というものを昨年から今年度にかけて定めておりまして、これを５年間実施していくというものです。１１年在籍していまして、合計１５年間、システム関係に携わっております。ふるさと納税の区のスタンスという部分です。","id":"exchange-003"},{"speaker":"筒井委員","kind":"意見","question":"令和６年度の実績が２,２３７回で、令和７年度の目標が１,５００回と回数が少なくなっているのですけれども、どういったことでこういう記載になったのか示すよう求めました。","respondent":"横田デジタル推進課長","answer":"少し過去に遡るのですが、令和６年度に１,８５６件と大幅に伸びた関係もありまして、このような目標を超過する形になってしまいました。今年度の目標の数値は見直していきたいと考えております。","id":"exchange-004"},{"speaker":"筒井委員","kind":"確認","question":"なかなか読みにくいと。１,０００件半ばぐらい、そうしたことも今回せっかく書いているのに記載したのかという理解でよろしいのか、確認したいと求めました。","respondent":"横田デジタル推進課長","answer":"このＤＸ推進基本方針の目標を立てるときには、今年度も令和６年度に近い数字で推移していくのかと、少し伸びているのかと感じております。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ見直しを行ってほしいと求めました。流出額が約５０.９億円ということで、改めて、品川区としては流入額が幾らぐらいを目標としているのか尋ねました。","respondent":"宮澤税務課長","answer":"今年度、品川区に寄附いただく目標額としては、１.２億円を目標としております。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"教えていただきたいのは、１番から４番まではＳＤＧｓに関連するというか、これは直接ＳＤＧｓとどう関係しているのかを教えてください。子どもを中心とした、これがどういう位置づけで表れているのかを教えていただけますか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今回、多様なステークホルダーとの連携というところで、柔軟な発想をまちづくり・区政に取り入れていくというところを１つ取り上げております。令和７年度はこの子ども・若者のほうを、中高生が政策立案まで参画していく、本事業をＳＤＧｓの中で取り上げているところです。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問","question":"子どもというのが入るのは令和７年度からということで、実は前々から子どもと入っていたのか、その辺りのことを説明するよう求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ＳＤＧｓ未来都市に応募・提案した段階から、子どもを１つ大きなテーマにして、子どもという要素を入れさせていただいておりました。少し同じ枠組みとは違った、計画としては子どもも含めて、多様なステークホルダーとの連携というところで推進していきたいと考えています。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"以前は令和６年こども会議というのが入っていたと思うのですけれども、大きく子どもというところが新たに出てきたと捉えていいのでしょうか。逆に、こんなに子どもとうたっていたかなというところでの、私が見落としていたのかなという質問です。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"庁内の関連課と共同で実施していたところで、そこで、こども会議を今後どうするかといったことを見据えながら実行してまいりました。子どもたちにもう少し継続的に区の事業を知っていただいたりとか、昨年度１年実施した内容を踏まえて、改善させていただいたです。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"最後に１点だけ。ということは、中高生リバースメンター事業というのは、ＳＤＧｓの推進の御課での取組ということになるのか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今、委員ご指摘のとおり、中高生リバースメンターは、ＳＤＧｓの達成に向けた取組の大きな要となる事業だと捉えてあります。","id":"exchange-010"},{"speaker":"山本委員","kind":"質問・要望","question":"それはそれでぜひご説明いただきたいのですけれども、そういったご説明いただけると思って、そこの辺りを確認させていただきたいのが１点です。","respondent":"井添ＳＤＧｓ推進担当課長、吉岡政策推進担当課長","answer":"そういうものが入ってまいりますので、全体的な各３側面の進捗状況でございましたり、私から本特別委員会でご報告する予定です。これはＰＦＩ事業で進めていくというところになりますので、事業者を公募するための実施方針、１年間かけてつくっていくことになります。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問・要望","question":"こういったところは一定織り込むかどうか、考えていただけるのかどうか、その辺りを確認させていただきたい。１年前倒しでＤＸ計画が策定されていて、それについても評価指標の策定を進めていらっしゃるかどうかを確認させていただきたい。","respondent":"吉岡政策推進担当課長、西澤ＤＸ戦略担当課長、宮澤税務課長","answer":"これは職員の負担軽減という面からも、あまり細かく変えていかないで、そういった部分は使わせていただきたいと考えています。遅延なく実施するとか、随時やっていこうと考えており、指標をつくりながら計画的に進めてまいりたいと考えております。令和６年度は１社で行っていたところなのですが、令和７年度からはさらに２社追加して、３社という状況になっております。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"要望させていただいているとおり、見やすさのところも非常に課題だと。これはすぐに大幅に拡大していくということはないと思うのですけれども、ぜひ地道に加盟店等、声かけしながら、裾野を広げてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"検討スケジュール感等をお伺いさせていただいたのですが、当委員会で扱っていっていただくようなスケジュールをお願いしたいと考えています。あわせて、必要であれば、現地の視察というのもしっかり入れていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"意見","question":"安藤委員の意見と珍しく同意でございまして、ＳＤＧｓに資する都市でありますとか、あとはいろいろな跡地の活用についての視察、現地を見るということは非常に大事だと思いますので、常任委員会以上に、特別委員会の視察を精力的に組んでほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/416707?Template=document&Id=7087#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":20611,"voices":72}}]);
